export const course = {"id":"preset-ielts7","title":"雅思7分语法日常训练","description":"雅思 7.0 语法（CEFR C1） · 成人","goal":"雅思 7.0 语法（CEFR C1）","cefr":"C1","syllabus":[{"title":"Advanced Tense & Aspect Combinations","skills":["past_perfect_continuous_in_narrative","future_perfect_vs_future_continuous","aspect_choice_for_emphasis","tense_consistency_in_academic_writing","mixed_tense_sequences"],"description":"C1级复杂时态与体的综合运用：完成进行时、过去完成时与叙事时态的精确搭配"},{"title":"Modal Verbs: Nuance & Epistemic Use","skills":["epistemic_modals_must_should_may","modal_perfect_for_past_deduction","semi_modals_be_bound_to_be_likely_to","modals_for_academic_hedging","contrast_between_similar_modals"],"description":"C1级情态动词的细微语义区分：推测、必要性、可能性及学术写作中的语气表达"},{"title":"Passive Voice & Causative Structures","skills":["passive_with_complex_tenses","passive_reporting_verbs_it_is_claimed","causative_have_get_with_past_participle","passive_infinitive_and_gerund","impersonal_passive_in_academic_prose"],"description":"C1级被动语态的多时态形式及使役结构have/get的书面语用法"},{"title":"Conditionals: Mixed, Inverted & Implied","skills":["mixed_conditionals_past_to_present","inverted_conditionals_had_were_should","implied_conditionals_with_otherwise_but_for","conditionals_in_formal_writing","conditional_like_structures_suppose_provided"],"description":"C1级条件句：混合条件、倒装条件及隐含条件的书面表达"},{"title":"Relative Clauses: Advanced Forms","skills":["non_defining_relative_with_quantifiers_many_of_which","preposition_fronting_in_relative_clauses","sentential_relative_which_referring_to_clause","reduced_relative_clauses_with_participles","relative_clauses_with_whoever_whatever"],"description":"C1级关系从句：含量词的非限制性从句、介词前置及which指代整句"},{"title":"Participle & Absolute Clauses","skills":["present_participle_clauses_for_result_reason","past_participle_clauses_for_condition_concession","perfect_participle_having_done","absolute_participial_constructions","dangling_participle_avoidance"],"description":"C1级分词短语与独立主格结构在书面语中压缩信息、增强连贯性的用法"},{"title":"Reported Speech & Reporting Verbs","skills":["backshift_in_complex_reported_speech","reporting_verbs_with_varied_patterns_claim_argue_suggest","reporting_questions_and_imperatives","no_backshift_for_general_truths","academic_reporting_with_that_clauses"],"description":"C1级间接引语的时态回移、多样化报告动词及学术转述的书面规范"},{"title":"Gerunds, Infinitives & Complex Noun Phrases","skills":["gerund_vs_infinitive_meaning_difference","perfect_and_passive_infinitives","gerunds_as_subjects_in_formal_writing","complex_noun_phrase_with_gerund","verbs_taking_both_with_meaning_change"],"description":"C1级动名词与不定式的深层用法：主语位置、复合动词宾语及语义差异"},{"title":"Articles, Determiners & Quantifiers","skills":["generic_vs_specific_article_use","article_omission_in_abstract_nouns","advanced_quantifiers_the_majority_a_number_of","determiners_in_academic_noun_phrases","double_determiners_and_pre_determiners"],"description":"C1级冠词的泛指与特指精确运用、限定词堆叠及高频量词的书面用法"},{"title":"Comparatives, Superlatives & Degree Structures","skills":["double_comparatives_the_more_the_more","comparative_clauses_with_ellipsis","superlatives_with_present_perfect","degree_adverbs_with_adjectives_and_nouns","as_as_constructions_with_inversion"],"description":"C1级比较级与最高级的复杂结构：双重比较、平行比较及程度副词的书面搭配"},{"title":"Advanced Clause Connectors & Discourse Markers","skills":["concession_clauses_although_while_whereas","result_clauses_such_that_so_that","fronted_adverbial_clauses_for_cohesion","noun_clauses_as_subject_and_complement","cleft_sentences_for_emphasis_it_is_what"],"description":"C1级书面连接词精确运用：让步、原因、结果及对比连接词在段落中的语法搭配"},{"title":"Use of English: Open Cloze, Word Formation & Key-Word Transformation","skills":["open_cloze_grammar_word_selection","word_formation_affixation_and_conversion","key_word_transformation_paraphrase","error_correction_in_written_text","integrated_grammar_accuracy_review"],"description":"C1级应用语法综合训练：语篇填空、构词变形与关键词句转换，整合所学书面语法"}],"unitsData":{"1":{"levels":{"1":[{"type":"choice","options":["were collecting","had been collecting","have been collecting","collected"],"sentence":"The scientists ___ the data for six months before the funding was suddenly cut.","subSkill":"past_perfect_continuous_in_narrative","explanation":"'before the funding was cut' 表明有一个过去的参照时间点，动作在此之前持续进行了六个月，因此用过去完成进行时 had been collecting，强调持续性。","instruction":"选择正确的时态形式。注意时间状语和句子语境。","correctIndex":1},{"type":"choice","options":["will work","will have worked","will be working","will have been working"],"sentence":"By next December, Professor Chen ___ at this university for exactly thirty years.","subSkill":"future_perfect_vs_future_continuous","explanation":"'By next December' 是未来参照点，句子强调到该时间点为止动作已持续整整三十年，应用将来完成进行时 will have been working 以突出持续时长。","instruction":"选择正确的时态形式。注意哪个选项强调动作的持续时长。","correctIndex":3},{"type":"choice","options":["searched","was searching","had been searching","has searched"],"sentence":"When the inspector arrived, she noticed that someone ___ through the confidential files.","subSkill":"past_perfect_continuous_in_narrative","explanation":"'when the inspector arrived' 是过去时间参照点，搜索行为在此之前已经持续发生（且留有痕迹），用过去完成进行时 had been searching 既表先于参照点，又强调持续性。","instruction":"选择最能在叙事中区分前后事件时间顺序的选项。","correctIndex":2},{"type":"choice","options":["had reviewed","were reviewing","have reviewed","would review"],"sentence":"The committee members ___ the proposal when the fire alarm suddenly went off.","subSkill":"aspect_choice_for_emphasis","explanation":"叙事中，进行时（were reviewing）描述背景中持续进行的动作，而简单过去时（went off）描述突然发生的前景关键事件，两者形成前景-背景对比。","instruction":"在叙事段落中，哪个时态用于描述关键事件打断背景持续动作？","correctIndex":1},{"type":"choice","options":["rise","are rising","had been rising","have risen"],"sentence":"The study found that urban temperatures ___ steadily since industrialisation began in the region.","subSkill":"tense_consistency_in_academic_writing","explanation":"主句 'the study found' 为过去时，从句描述在过去参照时间之前已持续发生的趋势，需用过去完成时或过去完成进行时。此处 had been rising 强调持续上升的过程，符合学术报告语境。","instruction":"选择学术写作中时态一致性正确的选项。","correctIndex":2},{"type":"choice","options":["was writing","had written","had been writing","wrote"],"sentence":"She ___ three drafts by the time her supervisor returned from the conference.","subSkill":"mixed_tense_sequences","explanation":"'by the time her supervisor returned' 表示过去参照点，强调在此之前已完成的数量（three drafts）——完成三稿是一个结果，不是持续过程，因此用过去完成时 had written 而非进行体。","instruction":"选择正确选项以完成含有混合时态序列的句子。","correctIndex":1},{"type":"choice","options":["will have been submitting","will submit","will be submitting","will have submitted"],"sentence":"By the time the new policy takes effect, the committee ___ its final recommendations.","subSkill":"future_perfect_vs_future_continuous","explanation":"'final recommendations' 表示一个完成的结果（提交完毕），而非强调持续过程，因此用将来完成时 will have submitted，表示在 'the policy takes effect' 这个未来时间点之前已完成提交。","instruction":"选择最准确区分将来完成时与将来完成进行时的选项。句子强调的是完成结果，而非过程持续。","correctIndex":3},{"type":"choice","options":["The researchers concluded that the variable has a significant effect on the outcome.","The researchers concluded that the variable had a significant effect on the outcome.","The researchers conclude that the variable had a significant effect on the outcome.","The researchers concluded that the variable will have a significant effect on the outcome."],"sentence":"Which sentence is correct in an academic report written in the past tense?","subSkill":"tense_consistency_in_academic_writing","explanation":"学术写作中，主句为过去时（concluded）时，描述研究发现的从句应使用过去时（had），以保持时态的逻辑一致性，避免时态回移（backshift）错误。","instruction":"识别以下哪个句子在学术写作的时态一致性上是正确的。","correctIndex":1}],"2":[{"type":"choice","options":["had worked","had been working","would work","has been working"],"sentence":"By the time the documentary aired, the filmmaker ___ in the Amazon for almost two years.","subSkill":"past_perfect_continuous_in_narrative","explanation":"'almost two years' 强调持续时长，且 'by the time the documentary aired' 是过去参照点，用过去完成进行时 had been working 最能体现在该参照点之前持续工作的过程和时间跨度。","instruction":"选择正确选项。注意动作是强调持续了多长时间，还是强调已经完成。","correctIndex":1},{"type":"choice","options":["was hiding","hid","had been hiding","has been hiding"],"sentence":"The police later discovered that the suspect ___ in the building for hours before he was finally caught.","subSkill":"past_perfect_continuous_in_narrative","explanation":"'before he was finally caught' 是过去时间参照点，'for hours' 表示持续时长，'later discovered' 表明整体是过去叙事语境，因此 had been hiding 正确表达在被捕之前持续躲藏的过程。","instruction":"从叙事角度选择正确的时态组合，使句子的时间顺序清晰。","correctIndex":2},{"type":"fill","sentence":"The engineers reported that they (test) ___ the new system for weeks before the critical fault was detected.","subSkill":"past_perfect_continuous_in_narrative","explanation":"'reported' 是过去叙事时态，'before the critical fault was detected' 是过去参照点，'for weeks' 强调持续时长，因此用过去完成进行时 had been testing。","instruction":"用括号中动词的正确形式填空。注意时间参照点和是否强调持续性。","acceptableAnswers":["had been testing"]},{"type":"fill","sentence":"By the end of this semester, my colleague (teach) ___ this advanced course for a decade.","subSkill":"future_perfect_vs_future_continuous","explanation":"'By the end of this semester' 是未来参照点，'for a decade' 强调到该时间点为止的持续时长，应用将来完成进行时 will have been teaching。","instruction":"用括号中动词的正确形式填空，强调到未来某时间点为止动作已持续的时长。","acceptableAnswers":["will have been teaching"]},{"type":"fill","sentence":"By 2028, the team (work) ___ on the project for ten years.","subSkill":"future_perfect_vs_future_continuous","explanation":"改写后句子需要表达到2028年（未来参照点）为止，团队工作将已持续整整十年，强调持续时长，因此用将来完成进行时 will have been working。","instruction":"用括号中动词的正确形式填空。这是一道关键词改写练习：保持原意，用完成进行时改写。原句：The project started in 2018. It will still be in progress in 2028. 改写：By 2028, the team (work) ___ on the project for ten years.","acceptableAnswers":["will have been working"]},{"type":"fill","sentence":"Senior staff members (debate) ___ the merger terms when the CEO unexpectedly resigned.","subSkill":"aspect_choice_for_emphasis","explanation":"叙事中 'were debating' 是进行时，描述CEO辞职时正在持续的背景动作；而 'resigned' 用简单过去时描述突然发生的前景事件，形成前景-背景的体对比。","instruction":"用括号中动词的正确形式填空，选择体（进行体或完成体）以最准确表达叙事中的前景-背景关系。","acceptableAnswers":["were debating"]},{"type":"fill","sentence":"Her manager read the report that she (submit) ___.","subSkill":"mixed_tense_sequences","explanation":"'read' 是叙事过去时，报告的提交发生在阅读之前，因此用过去完成时 had submitted 明确标记事件的先后顺序，这是混合时态序列的核心用法。","instruction":"关键词改写练习。将以下两句合并为一句，使用混合时态序列清晰表达时间顺序。原句：She submitted the report. After that, her manager read it. 改写（以 'Her manager' 开头）：Her manager read the report that she (submit) ___.","acceptableAnswers":["had submitted"]}],"3":[{"type":"fill","sentence":"It was clear to the panel that the candidate (prepare) ___ thoroughly: she (rehearse) ___ her arguments for weeks and (research) ___ every panel member's published work.","subSkill":"mixed_tense_sequences","explanation":"三个动词都描述在 'it was clear' 这一过去参照点之前发生或持续的事情。'had prepared' 强调充分准备的结果；'had been rehearsing' 强调排练过程的持续性（weeks）；'had researched' 强调研究完成的事实，共同构成复杂的过去完成时态序列。","instruction":"用括号中动词的正确形式填空，注意叙事中复杂的过去时态序列。","acceptableAnswers":["had prepared","had been rehearsing","had researched"]},{"type":"fill","sentence":"By next June, the workers ___ (build) ___ the bridge for over two years.","subSkill":"future_perfect_vs_future_continuous","explanation":"改写要求表达到未来参照点（next June）为止动作已持续超过两年，强调持续时长和过程，因此用将来完成进行时 will have been building，两个空格合为一个答案。","instruction":"关键词改写练习。保持原意，用将来完成进行时改写划线部分。原句：The construction started two years ago and will not finish until next June. 改写：By next June, the workers ___ (build) ___ the bridge for over two years.","acceptableAnswers":["will have been building"]},{"type":"fill","sentence":"The historian argued that the empire (decline) ___ for decades before it finally (collapse) ___, and that multiple factors (contribute) ___ to this prolonged deterioration.","subSkill":"tense_consistency_in_academic_writing","explanation":"'argued' 为过去叙事时态。'had been declining' 表示衰落过程在崩溃之前持续了数十年（强调持续体）；'collapsed' 是叙事中的具体事件（简单过去）；'had contributed' 表示多个因素的影响先于分析时间点已经存在（完成体，强调结果）。","instruction":"用括号中动词的正确形式填空，体现学术写作中严格的时态一致性和逻辑。","acceptableAnswers":["had been declining","collapsed","had contributed"]},{"type":"fill","sentence":"It was evident that the team (spend) ___ years collecting samples and (complete) ___ three major studies.","subSkill":"mixed_tense_sequences","explanation":"'It was evident that' 确立了过去叙事参照框架，从句中描述在此参照点之前已发生的两个动作，均应使用过去完成时：'had spent' 表示在参照时间之前已经花费了数年（持续性但强调结果），'had completed' 表示已完成三项研究（强调完成的事实）。","instruction":"关键词改写练习。以 'It was evident that' 开头，将以下情境改写为一个体现混合时态序列的学术句子：情境：The team spent years collecting samples. They also completed three major studies. This was obvious to the reviewers. 用括号中的词语填空。","acceptableAnswers":["had spent","had completed"]},{"type":"fill","sentence":"When the audit team arrived, they found that the manager (falsify) ___ the accounts systematically for years, and that a junior employee (already / raise) ___ concerns about the discrepancies six months earlier.","subSkill":"aspect_choice_for_emphasis","explanation":"'had been falsifying' 用过去完成进行时强调造假行为在审计到来之前已持续数年（强调过程和时长，暗示损害的累积性）；'had already raised' 用过去完成时（简单体）强调投诉这一完成动作发生在两个过去参照点之前（审计到来之前六个月），'already' 增强对时间先后的强调。","instruction":"用括号中动词的正确形式填空。仔细选择体的形式以体现对叙事重点的强调——过程还是结果。","acceptableAnswers":["had been falsifying","had already raised"]}],"4":[{"type":"choice","options":["were collecting","had been collecting","have been collecting","would collect"],"sentence":"By the time the researchers published their findings in 2023, they ___ the data for over a decade.","subSkill":"past_perfect_continuous_in_narrative","explanation":"\"By the time...published\"表示在过去某时间点之前持续进行的动作，应使用过去完成进行时 had been collecting，强调动作的持续性及其与过去时间点的关联。现在完成进行时 have been collecting 不能用于描述过去的时间点之前的情况。","instruction":"选择最准确的选项，完成这段学术写作中的句子。注意时态的一致性。","correctIndex":1},{"type":"choice","options":["will be completing","will have completed","will complete","are completing"],"sentence":"If the construction continues at this pace, workers ___ the bridge by the end of next March, so commuters should plan their routes accordingly.","subSkill":"future_perfect_vs_future_continuous","explanation":"\"by the end of next March\"表示在未来某时间点之前动作已完成，应使用将来完成时 will have completed，强调完成的结果。will be completing 表示届时仍在进行中，与句意不符。","instruction":"选择最准确的选项，注意将来时态的细微差别。","correctIndex":1},{"type":"fill","sentence":"The professor noticed that the student (submit) ___ the wrong draft because she (revise) ___ the document all night and accidentally uploaded the earlier version.","subSkill":"past_perfect_continuous_in_narrative","explanation":"第一空：noticed 是过去时，学生提交错误草稿发生在 noticed 之前，用过去完成时 had submitted。第二空：她整晚持续修改的动作在过去持续进行，且为解释为何出错提供背景，用过去完成进行时 had been revising 强调动作的持续性。","instruction":"根据语境，用括号内动词的正确形式填空，可能需要多于一个词。","acceptableAnswers":["had submitted","had been revising"]},{"type":"choice","options":["ignored","had been ignoring","has ignored","was ignoring"],"sentence":"Critics argued that the government ___ the environmental warnings for years before the crisis finally forced a policy change.","subSkill":"aspect_choice_for_emphasis","explanation":"had been ignoring 是过去完成进行时，强调在过去时间点（危机爆发）之前政府长期持续忽视警告这一动作，体现了动作的持续性和与危机之间的时间先后关系。单纯的过去时 ignored 不能突出这种持续性。","instruction":"在学术写作中，选择最能体现动作持续性并符合时态一致原则的选项。","correctIndex":1},{"type":"fill","sentence":"By the time the grant period ends next autumn, the research team (conduct) ___ experiments for three consecutive years without interruption.","subSkill":"future_perfect_vs_future_continuous","explanation":"next autumn 是未来时间点，到那时实验将已持续进行三年，需同时强调完成性（到未来某点结束前）和持续性（三年连续进行），因此用将来完成进行时 will have been conducting。","instruction":"用括号内动词的正确形式填空，注意将来时态与时间状语的匹配。","acceptableAnswers":["will have been conducting"]},{"type":"choice","options":["had been altering / was sitting","altered / sat","had been altering / had been sitting","was altering / had sat"],"sentence":"When the auditors arrived at the firm, the accountant ___ the records for several hours and the manager ___ in a meeting since noon.","subSkill":"mixed_tense_sequences","explanation":"审计员到达是过去的时间基准点。会计师在此之前已持续篡改记录数小时，经理自中午起一直在开会，两个动作均在基准点之前持续进行，因此两空都使用过去完成进行时 had been altering / had been sitting，强调持续性。","instruction":"选择最准确的选项，注意时态组合对叙事顺序的影响。","correctIndex":2}],"5":[{"type":"fill","sentence":"The scientist started measuring the glacier in 2005 and is still measuring it now. (Since) Since 2005, the scientist ___.","subSkill":"aspect_choice_for_emphasis","explanation":"原句表示从2005年开始持续到现在的动作，改写时以 Since 2005 开头，需用现在完成进行时 has been measuring，强调动作从过去某点持续至今且仍在进行。","instruction":"关键词转换练习：保持句意不变，用所给词改写句子，填入空白处。用括号内的词开头，不得改变其形式。","acceptableAnswers":["has been measuring the glacier"]},{"type":"fill","sentence":"When the documentary crew finally reached the remote village, the epidemic (spread) ___ for two months, and local health workers (exhaust) ___ their entire supply of medicine.","subSkill":"mixed_tense_sequences","explanation":"第一空：记录组到达是过去基准点，疫情在此之前已持续蔓延两个月，用过去完成进行时 had been spreading 强调持续性。第二空：医疗用品耗尽是在到达之前已完成的结果状态，用过去完成时 had exhausted，强调完成性而非持续性。","instruction":"根据语境，用括号内动词的正确形式填空。注意时态序列的逻辑一致性。","acceptableAnswers":["had been spreading","had exhausted"]},{"type":"choice","options":["will have been presenting","will have presented","will be presenting","will present"],"sentence":"By the time Professor Lin delivers her keynote address next Friday, she ___ the same core argument in twelve different countries.","subSkill":"future_perfect_vs_future_continuous","explanation":"句子强调到下周五时，这一动作（在12个国家演讲）已完成的次数和结果，而非动作的持续过程，因此用将来完成时 will have presented。若用 will have been presenting 则侧重于持续过程，与 twelve different countries 这一完成计数的语境不符。","instruction":"选择最准确的选项，注意将来完成时与将来完成进行时的语义区别。","correctIndex":1},{"type":"fill","sentence":"The engineers expect to finish testing the prototype by late December. (will) By late December, the engineers ___.","subSkill":"future_perfect_vs_future_continuous","explanation":"原句用 expect to finish 表达对未来完成的预期，改写时以 will 构成将来完成时 will have finished，强调到十二月底时测试将已完成，by late December 是未来时间点，触发将来完成时的使用。","instruction":"关键词转换练习：保持句意不变，用括号内的词改写句子。","acceptableAnswers":["will have finished testing the prototype"]}]},"mission":{"title":"The Academic Report","scenario":"你的导师要求你完成报告中三个关键段落的分析。每个段落都有写作提示，你需要根据提示内容选择正确的时态和体，使学术表述精确、逻辑清晰。注意：时态选择必须反映真实的时间顺序和语义重点（持续性 vs. 完成结果 vs. 叙事背景），不可随意使用。","scaffolds":[{"hint":"在'before the government introduced'这一过去参照点之前，气温上升持续了四十多年——选择既能表达过去参照点、又能强调持续时长和过程的时态。","prefix":"The data revealed that average urban temperatures","suffix":"steadily for over four decades before the government introduced new environmental regulations in 2015.","example":"The data revealed that average urban temperatures had been rising steadily for over four decades before the government introduced new environmental regulations in 2015.","grammarCheck":"past_perfect_continuous_in_narrative"},{"hint":"2030年是未来参照点，研究将持续约十五年——选择能表达在未来参照点之前动作将已持续的时态，并注意体的选择要强调时长而非仅完成结果。","prefix":"By the time this longitudinal study concludes in 2030, researchers","suffix":"the effects of urbanisation on local microclimates for nearly fifteen years, making it one of the most sustained investigations of its kind.","example":"By the time this longitudinal study concludes in 2030, researchers will have been tracking the effects of urbanisation on local microclimates for nearly fifteen years, making it one of the most sustained investigations of its kind.","grammarCheck":"future_perfect_vs_future_continuous"},{"hint":"这个句子需要两个不同的过去完成时形式：一个描述在'pointed out'之前已持续存在的问题（强调过程），另一个描述更早发生的同行评审未能发现问题这一完成事件——注意体的选择区别。","prefix":"Senior analysts were reviewing the preliminary findings when a statistician pointed out that the original sampling method","suffix":"a systematic bias that earlier peer reviews","example":"Senior analysts were reviewing the preliminary findings when a statistician pointed out that the original sampling method had been introducing a systematic bias that earlier peer reviews had failed to detect.","grammarCheck":"aspect_choice_for_emphasis"}],"description":"你将扮演一名研究助理，为一份关于城市气候变化的学术报告撰写三段分析文字。每段文字需要综合运用本单元的核心时态结构：过去完成进行时、将来完成进行时（或其过去形式）以及混合时态序列，准确表达研究发现、持续趋势和未来预测之间的时间逻辑关系。","grammarType":"mixed_tense_sequences"},"discover":{"tip":"【核心对比：C1复杂时态与体的选择】\n\n1. 过去完成进行时 vs. 过去完成时\n   - 过去完成进行时（had been doing）：强调动作在过去参照点之前的【持续性与过程】，常暗示该过程对后续事件有直接影响。例：She had been researching the topic for a decade before she published.（强调十年的持续积累）\n   - 过去完成时（had done）：强调动作在过去参照点之前已经【完成】，关注结果状态。例：She had finished the report before the deadline.（强调完成这一事实）\n   - 常见错误：将两者混用而不考虑是否需要强调持续性。例：误用 'She had worked there for years' 当需要强调持续过程时，应用 'She had been working there for years'。\n\n2. 将来完成时 vs. 将来完成进行时（及其过去形式）\n   - 将来完成时（will have done / would have done）：强调在未来某时间点之前动作的【完成结果】。例：By 2030, scientists will have discovered a cure.\n   - 将来完成进行时（will have been doing / would have been doing）：强调在未来某时间点之前动作的【持续时长与过程】。例：By next year, they will have been building the bridge for five years.\n   - 常见错误：在需要强调持续时长时错误使用将来完成时，导致语义不完整。\n\n3. 体的选择与叙事强调（Aspect for Emphasis）\n   - 进行体（was doing）在叙事中制造【前景背景对比】：背景持续动作用进行时，关键事件用简单过去时。例：She was writing her notes when the wall collapsed.\n   - 学术写作中时态序列须严格一致：主句时态决定从句的参照系，混乱的时态序列会造成逻辑歧义。\n\n常见错误提示：\n- 错误：'She has been working there since she graduated and then discovered the artifact.' （现在完成进行时与叙事过去时混搭）\n- 正确：'She had been working there since she graduated and then discovered the artifact.'","story":{"text":"Dr. Elena Vasquez had been working at the excavation site for nearly three years before she finally uncovered what would become the most significant find of her career. She had been painstakingly cataloguing fragments of pottery when her assistant called out that something unusual had appeared beneath the eastern wall. By the time the university's media team arrived the following morning, the team will have been — or rather, would have been — working through the night for over fourteen hours. Elena reflected that she had been pursuing this particular theory since her doctoral research, and the evidence she had accumulated over the decades now seemed to justify every difficult choice she had made. While junior researchers were documenting the chamber, Elena was composing her preliminary report, carefully choosing tenses to signal which discoveries had preceded others. She noted that the ceramic style had been evolving across distinct periods, each layer of sediment having deposited over centuries. As she wrote, she knew that by the time her paper was published, other scholars would have been debating the implications for months. The dig had transformed what everyone had previously believed about the civilisation, and Elena understood that the work she had been doing all these years had permanently altered the field.","title":"The Archaeologist's Discovery","highlights":["had been working","had been painstakingly cataloguing","would have been working","had been pursuing","had accumulated","were documenting","was composing","had preceded","had been evolving","would have been debating","had been doing"]},"questions":[{"options":["她在发现文物之前短暂地工作过一段时间","一个持续进行的动作在另一个过去动作发生之前已经延续了相当长的时间","她的工作与发现同时发生","她将来会继续工作"],"question":"故事中 'She had been working at the excavation site for nearly three years before she finally uncovered...' 这个结构强调了什么？","explanation":"过去完成进行时（had been working）强调一个动作在过去某个时间点之前已经持续进行了一段时间，突出时间的延续性和因果背景，区别于简单过去完成时对状态完成的强调。","correctIndex":1},{"options":["过去完成进行时；表示过去某个持续动作","将来完成进行时的过去形式（would have been doing）；表示在某个未来参照点之前某动作将已持续进行","过去进行时；表示与写作同时发生的动作","现在完成进行时；表示与现在相关的持续动作"],"question":"故事中 'by the time her paper was published, other scholars would have been debating the implications for months' 使用了哪个时态，它表达了什么含义？","explanation":"'would have been debating' 是将来完成进行时在过去语境（从过去视角看）中的形式，表示在'论文发表'这个未来参照点之前，辩论这一动作将已经持续进行了几个月，强调动作的持续性与截止时间点的关系。","correctIndex":1},{"options":["学术写作中时态选择无关紧要，只需保持一致即可","过去完成时在学术叙事中用于明确区分事件的先后顺序，具有语义功能","所有过去事件都应使用简单过去时表达","进行体只能用于描述正在发生的动作，不能用于学术写作"],"question":"Elena在撰写学术报告时'carefully choosing tenses to signal which discoveries had preceded others'，这说明了什么？","explanation":"在学术写作中，过去完成时（had preceded）不仅是语法要求，更是语义工具——它精确标记某一事件发生在另一参照过去时间点之前，帮助读者理解事件的时间逻辑与因果关系。","correctIndex":1}]}},"2":{"levels":{"1":[{"type":"choice","options":["must","should","would","shall"],"sentence":"The lights are still on in her office. She ___ be working late tonight.","subSkill":"epistemic_modals_must_should_may","explanation":"灯还亮着是直接证据，说话者据此得出\"几乎可以肯定\"的推断，用must表示高度确信的认识情态推测。","instruction":"选择正确选项完成句子。根据语境判断情态动词的语义。","correctIndex":0},{"type":"choice","options":["must have","should","might","could"],"sentence":"He studied for months, so he ___ passed the exam without any trouble.","subSkill":"modal_perfect_for_past_deduction","explanation":"准备了数月是充足证据，用\"must have + 过去分词\"对已发生的事情作出强力肯定推断，意为\"他肯定通过了\"。","instruction":"选择正确选项完成句子。注意情态动词对过去事件的推断。","correctIndex":0},{"type":"choice","options":["can have","must have","would have","shall have"],"sentence":"The path is wet and muddy. It ___ rained heavily last night.","subSkill":"modal_perfect_for_past_deduction","explanation":"小路泥泞是有力证据，据此推断昨晚必定下了大雨，用must have表示对过去事件基于证据的强推断。","instruction":"选择最符合语境的选项。","correctIndex":1},{"type":"choice","options":["is bound to","is likely to","ought to","may"],"sentence":"With her talent and preparation, she ___ win the competition.","subSkill":"semi_modals_be_bound_to_be_likely_to","explanation":"\"be bound to\"表示几乎必然会发生，强度高于\"be likely to\"，适用于根据才能和充分准备几乎可以断定的结果。","instruction":"选择正确选项。注意半情态动词的含义。","correctIndex":0},{"type":"choice","options":["is likely to","is bound to","must","shall"],"sentence":"The new policy ___ reduce traffic congestion significantly, according to the report.","subSkill":"semi_modals_be_bound_to_be_likely_to","explanation":"\"according to the report\"表示这是基于报告数据的推测，\"is likely to\"恰当地表达了较高但非绝对的可能性，比\"is bound to\"留有余地。","instruction":"选择最恰当的选项完成句子。","correctIndex":0},{"type":"choice","options":["will","would","shall","must"],"sentence":"The results suggest that further research ___ be necessary to confirm these findings.","subSkill":"modals_for_academic_hedging","explanation":"在学术写作中，用\"would\"代替\"will\"可以软化语气，表达一种谨慎的、非绝对的结论，这是学术语气缓和（hedging）的标准用法。","instruction":"选择最合适的学术表达。","correctIndex":1},{"type":"choice","options":["might have","should have","could have","would have"],"sentence":"She ___ arrived by now — her train was due an hour ago.","subSkill":"contrast_between_similar_modals","explanation":"\"should have + 过去分词\"表示基于预期或计划推断某事此时应已发生，火车一小时前就该到了，所以她\"按理该已经到了\"，而非遗憾或批评含义。","instruction":"选择正确的选项，注意两个相近情态动词的区别。","correctIndex":1},{"type":"choice","options":["should have","must have","might have","could have"],"sentence":"You ___ told me about the meeting earlier! I completely missed it.","subSkill":"contrast_between_similar_modals","explanation":"\"should have + 过去分词\"表示过去本应做却未做的事情，带有批评或遗憾的含义。这里说话者在责怪对方没有提前告知。","instruction":"选择正确选项，区分情态动词的语义差别。","correctIndex":0}],"2":[{"type":"choice","options":["must have","might have","should have","would have"],"sentence":"I left my umbrella somewhere this morning. I ___ left it on the bus, but I am not entirely sure.","subSkill":"modal_perfect_for_past_deduction","explanation":"\"but I am not entirely sure\"明确表示不确定，因此应用\"might have\"而非\"must have\"。\"might have\"表示对过去事件的弱推断，承认多种可能性。","instruction":"选择最恰当的选项完成句子，注意认识情态的强度区别。","correctIndex":1},{"type":"choice","options":["can","could","will","shall"],"sentence":"The data indicates that early intervention ___ lead to better long-term outcomes for patients.","subSkill":"modals_for_academic_hedging","explanation":"在学术语境中，\"could\"比\"can\"或\"will\"更为谨慎，表达一种有条件的可能性而非确定结论，符合学术写作避免过度断言的规范。","instruction":"选择最恰当的选项，注意学术写作中的语气缓和。","correctIndex":1},{"type":"fill","sentence":"The door was wide open when we arrived. Someone (break) ___ in during the night.","subSkill":"modal_perfect_for_past_deduction","explanation":"门大开是有力证据，表示\"肯定是有人在夜间闯入了\"，用\"must have + 过去分词\"作强肯定推断，break的过去分词是broken。","instruction":"用括号内的动词和适当的情态动词完成句子，表示对过去事件的强肯定推断。","acceptableAnswers":["must have broken"]},{"type":"fill","sentence":"The project failed largely because we (consult) ___ the stakeholders beforehand.","subSkill":"contrast_between_similar_modals","explanation":"项目失败了，说明之前没有咨询利益相关者，而本来应该这样做，用\"should have + 过去分词\"表示过去本应做却未做的遗憾或批评。","instruction":"用括号内的动词和适当的情态动词完成句子，表示对过去未做之事的遗憾。","acceptableAnswers":["should have consulted"]},{"type":"fill","sentence":"Given the overwhelming evidence, the jury (find) ___ him guilty.","subSkill":"semi_modals_be_bound_to_be_likely_to","explanation":"压倒性的证据表明结果几乎是必然的，\"be bound to\"表示比\"be likely to\"更强的必然性。根据语境时态（现在或过去）均可接受。","instruction":"用括号内的动词和适当的情态动词完成句子，表示几乎确定会发生。","acceptableAnswers":["is bound to find","was bound to find"]},{"type":"fill","sentence":"It is almost certain that the experiment will yield inconsistent results under these conditions. (The experiment ___)","subSkill":"epistemic_modals_must_should_may","explanation":"\"It is almost certain that...\"对应认识情态\"must\"（强推测）或半情态\"be bound to\"（几乎必然），两者均可替换原句表达高度确信。","instruction":"用情态动词改写句子，保持原意。括号内给出改写的开头。","acceptableAnswers":["The experiment must yield inconsistent results under these conditions.","The experiment is bound to yield inconsistent results under these conditions."]},{"type":"choice","options":["must have / could","may have / might","should have / would","would have / must"],"sentence":"No one answered the phone all day. She ___ gone on a trip, or she ___ simply have been too busy to reply.","subSkill":"epistemic_modals_must_should_may","explanation":"两个空格都表达不确定的猜测（没有明确证据），应用弱推断情态。\"may have\"和\"might\"都表示对过去和现在情况的弱可能性推测，相互呼应，语义一致。","instruction":"选择最恰当的选项，区分\"may have\"和\"must have\"的语义强度。","correctIndex":1}],"3":[{"type":"fill","sentence":"Marcus was at a conference in Berlin all week. He (commit) ___ the crime here in London on Tuesday.","subSkill":"modal_perfect_for_past_deduction","explanation":"Marcus整周在柏林，逻辑上不可能在伦敦犯案，用\"could not have / cannot have + 过去分词\"表示对过去事件的否定推断，意为\"根据证据，这不可能发生\"。","instruction":"用括号内的动词和最恰当的情态动词完成句子，表示对过去的否定推断（逻辑上不可能）。","acceptableAnswers":["could not have committed","cannot have committed"]},{"type":"fill","sentence":"It was wrong that the committee did not inform the participants of the changes in advance. (The committee ___)","subSkill":"contrast_between_similar_modals","explanation":"\"ought to have + 过去分词\"与\"should have + 过去分词\"含义相近，均表示过去本应发生却未发生的事，带有批评或遗憾的含义。在正式书面语中\"ought to have\"更为正式。","instruction":"用情态动词改写句子，保持原意，使用\"ought to have\"。","acceptableAnswers":["The committee ought to have informed the participants of the changes in advance."]},{"type":"fill","sentence":"Increased urbanisation causes a rise in mental health issues among young adults. (Increased urbanisation ___)","subSkill":"modals_for_academic_hedging","explanation":"原句用\"causes\"作出绝对断言，不符合学术写作的审慎规范。加入\"may/might/could\"进行语气缓和（hedging），将因果关系表达为一种有据可查的可能性而非定论，这是C1学术写作的核心技能。","instruction":"用情态动词对以下句子进行学术化改写，使语气更加审慎，保留原句核心信息。","acceptableAnswers":["Increased urbanisation may cause a rise in mental health issues among young adults.","Increased urbanisation might cause a rise in mental health issues among young adults.","Increased urbanisation could cause a rise in mental health issues among young adults.","Increased urbanisation would appear to cause a rise in mental health issues among young adults."]}],"4":[{"type":"choice","options":["should","must","would","ought"],"sentence":"The lights are off and no one answers the door. They ___ have gone out for the evening.","subSkill":"epistemic_modals_must_should_may","explanation":"must在此表示基于充分证据的强烈逻辑推断（认识情态），意为\"一定是\"。should表示预期，would表示假设，ought单独使用不完整，均不如must准确。","instruction":"选择最符合语境的情态动词：句子表达的是根据证据对现在情况的强烈推断。","correctIndex":1},{"type":"choice","options":["must have","should have","may have","would have"],"sentence":"She knew every detail of the contract. She ___ read it very carefully beforehand.","subSkill":"modal_perfect_for_past_deduction","explanation":"must have + 过去分词用于对过去事件的强烈逻辑推断，意为\"她一定是仔细读过了\"。should have含批评意味，may have表示可能性较弱，would have表示虚拟条件，均不符合此处基于证据的推断语气。","instruction":"选择正确的情态完成式，表达对过去某一情况的有根据推测。","correctIndex":0},{"type":"choice","options":["must","will","may","shall"],"sentence":"These fluctuations in temperature ___ indicate a broader pattern of climate instability.","subSkill":"modals_for_academic_hedging","explanation":"学术写作中may用于表示开放性的可能性，避免过度肯定，体现学术谦逊（hedging）。must过于肯定，will表示必然，shall过于正式且语义不符。","instruction":"选择最适合学术写作语气的表达，用于提出一个尚待验证的可能性。","correctIndex":2},{"type":"choice","options":["must","should","would","could"],"sentence":"Given her years of experience in the field, she ___ find this task straightforward, yet she seems to be struggling.","subSkill":"contrast_between_similar_modals","explanation":"should在此表示基于预期或常理的推断，意为\"按理应该觉得容易\"，同时暗示现实与预期不符（yet she seems to be struggling）。must则表示强烈的逻辑确定性，与后半句的转折不协调。","instruction":"选择正确选项，区分must与should在认识情态中的语义差异。","correctIndex":1},{"type":"fill","sentence":"With such strong evidence against him, the defendant (be bound to) ___ lose the case.","subSkill":"semi_modals_be_bound_to_be_likely_to","explanation":"be bound to表示根据当前情况几乎确定会发生的事情，语气比may强，接近must的确定性。主语为第三人称单数现在时，故用is bound to。","instruction":"用括号中的半情态动词的正确形式填空，表示\"几乎可以肯定会发生\"。","acceptableAnswers":["is bound to"]},{"type":"fill","sentence":"The manuscript was found near the river bank. The author (may / leave) ___ it there intentionally.","subSkill":"modal_perfect_for_past_deduction","explanation":"may have + 过去分词用于对过去事件的非确定性推测，意为\"可能是故意放在那里的\"，体现认识情态中的可能性而非强烈确定性。","instruction":"用情态完成式填空，表达对过去行为的合理推测（可能性，非确定）。","acceptableAnswers":["may have left"]}],"5":[{"type":"fill","sentence":"It is probable that the new policy will reduce unemployment. → The new policy (be likely to) ___ unemployment.","subSkill":"semi_modals_be_bound_to_be_likely_to","explanation":"be likely to + 动词原形用于表示基于现有情况的较高可能性，与it is probable that在意义上等同，常见于半正式和学术语境，是情态意义的结构替换。","instruction":"关键词转换练习：将下句改写，保持意思不变，使用be likely to结构。用括号提示的结构填写空白处。","acceptableAnswers":["is likely to reduce"]},{"type":"fill","sentence":"I am certain that the researchers did not overlook such an obvious flaw. → The researchers ___ (overlook) ___ such an obvious flaw.","subSkill":"modal_perfect_for_past_deduction","explanation":"cannot have + 过去分词表示对过去某事的强烈否定推断，意为\"不可能忽略了\"。这是must have的否定等价形式，用于表示基于逻辑的否定确定性推断。","instruction":"关键词转换练习：用情态完成式改写句子，保持对过去事件的推断意义，用must或cannot视语境选择。","acceptableAnswers":["cannot have overlooked","can't have overlooked"]},{"type":"choice","options":["must have","should have","could have","would have"],"sentence":"The early data anomalies ___ resulted from a calibration error, though no definitive cause has been identified.","subSkill":"contrast_between_similar_modals","explanation":"could have + 过去分词表示过去某种情况在理论上是可能的原因之一，语气比must have更为审慎，且不含批评意味（排除should have）。句中no definitive cause has been identified明确排除了确定性推断，故could have最为恰当。","instruction":"选择最恰当的选项，区分could have与might have在认识情态中的细微差别。句子描述的是对过去某一替代可能性的审慎推断。","correctIndex":2},{"type":"fill","sentence":"Given the scale of the investment and the strength of the team, this project (be bound to) ___ a significant impact on the industry.","subSkill":"semi_modals_be_bound_to_be_likely_to","explanation":"is bound to + 动词原形表示根据现有有利条件，某事几乎必然发生，语气接近确定。此处have a significant impact是完整的动词短语，is bound to后接动词原形have。","instruction":"根据语境用适当的情态动词或半情态动词填空。句子描述一个几乎不可避免的未来结果，用be bound to结构。","acceptableAnswers":["is bound to have"]}]},"mission":{"title":"The Academic Report: A Mysterious Archaeological Discovery","scenario":"你的团队在山洞中发现了一批精美陶器，旁边有烧焦的木炭和一把锈迹斑斑的金属钥匙。放射性碳定年法显示这些文物距今约1,200年。附近没有其他居住遗迹。请就这些发现写一段学术分析，推断这批文物的来历、保存原因以及未来研究方向。","scaffolds":[{"hint":"用must have been 或 is likely to have been 表达基于证据的过去推断","prefix":"The presence of charcoal alongside the ceramics suggests that this site","suffix":"used for ritual or storage purposes.","example":"The presence of charcoal alongside the ceramics suggests that this site must have been used for ritual or storage purposes.","grammarCheck":"modal_perfect_for_past_deduction"},{"hint":"用could not have been 排除某种可能，或用must have been表达强推断（注意被动式）","prefix":"Given the absence of any surrounding settlement remains, the artefacts","suffix":"transported to this location deliberately.","example":"Given the absence of any surrounding settlement remains, the artefacts could not have originated locally; they must have been transported to this location deliberately.","grammarCheck":"modal_perfect_for_past_deduction"},{"hint":"前半句用would/could表学术语气缓和，后半句用are likely to/are bound to表示可能性强度","prefix":"Further isotopic analysis of the metal key","suffix":"shed light on the trade networks of the period, and the findings","example":"Further isotopic analysis of the metal key could shed light on the trade networks of the period, and the findings are likely to reshape our understanding of regional exchange in this era.","grammarCheck":"modals_for_academic_hedging"}],"description":"你是一位考古研究员，刚刚在一处偏远遗址发现了一批来历不明的文物。请根据所给情境，用C1级情态动词写一段学术分析报告片段，要求运用：对过去的推断（must have / may have / could not have）、半情态动词（be bound to / be likely to）以及学术语气缓和（would / could / might）。","grammarType":"epistemic_modals_must_should_may"},"discover":{"tip":"**C1情态动词：细微语义与认识情态**\n\n**核心对比：**\n\n1. **推测强度（现在/将来）**：must > should/ought to > may/might > could\n   - She *must* be in the archive. （几乎确定）\n   - She *should* be there by now. （基于预期，相当可能）\n   - She *may/might* be working late. （有可能，但不确定）\n   - She *could* be anywhere. （仅表逻辑上的可能性）\n\n2. **对过去的推断（modal + have + V-ed）**：\n   - *must have left* = 强推断（肯定）\n   - *may/might have discovered* = 弱推断（可能）\n   - *could not have gone* = 强推断（否定）\n   - *should have called* = 过去本应做却未做（带有批评/遗憾含义）\n\n3. **半情态动词**：\n   - *be bound to* = 几乎必然发生（强于\"likely\"）\n   - *be likely to* = 基于证据的较高可能性\n\n4. **学术语气缓和（Hedging）**：\n   - 用 *would/could/might* 替代 *will/can/may*，使论断更加谨慎。\n   - 例：\"This *could* represent a significant finding.\"（比\"This *will* represent...\"更符合学术规范）\n\n**常见错误：**\n- ❌ \"She must leave in a hurry yesterday.\" → ✅ \"She *must have left* in a hurry.\"（对过去推断必须用 must have + V-ed）\n- ❌ \"He should call her last night.\" → ✅ \"He *should have called* her last night.\"（对过去未完成之事的评价用 should have + V-ed）","story":{"text":"Professor Harlow had not been seen at the university for three days. Her colleague Dr. Reyes noted that her coat and bag were still in her office, so she must have left in a hurry. The lab door was locked from inside, which was strange. She could not have gone far without her keys. Dr. Reyes thought she might have discovered something extraordinary in her data and retreated somewhere to think. A note on the desk read that further testing would be required before any conclusions could be drawn. It was likely that she had simply lost track of time at the archive. She was bound to appear soon, as her department review was the following morning. Dr. Reyes should have called her the previous evening, but had forgotten. Still, there ought to be a simple explanation. The situation may well have arisen from her habit of working in isolated spaces. Whatever the reason, she would surely surface before long, and the findings, if confirmed, could represent one of the most significant breakthroughs the department had ever seen.","title":"The Vanishing Researcher","highlights":["must have left","could not have gone","might have discovered","would be required","was likely that","was bound to appear","should have called","ought to be","may well have arisen","could represent"]},"questions":[{"options":["A polite request","A strong logical deduction about a past event","A future obligation","A habitual action in the past"],"question":"Dr. Reyes concluded that Professor Harlow \"must have left in a hurry\" because her coat and bag were still in the office. What does \"must have\" express here?","explanation":"\"must have + 过去分词\"用于对过去事件作出有力的逻辑推断，表示说话者根据现有证据得出\"几乎可以肯定\"的结论，属于认识情态（epistemic modality）的典型用法。","correctIndex":1},{"options":["It is certain she did not go far, based on the evidence of her keys.","She was not allowed to go far.","She did not want to go far.","It is possible she went far, but we are not sure."],"question":"The story says she \"could not have gone far without her keys.\" Which sentence best paraphrases this meaning?","explanation":"\"could not have + 过去分词\"表示对过去情况的否定推断，意为\"根据逻辑/证据，这件事不可能发生\"。这里钥匙还在，所以推断她不可能走远。","correctIndex":0},{"options":["They express personal emotional feelings about the research.","They indicate past habits.","They soften the statement, creating academic hedging and tentative tone.","They describe future scheduled events with certainty."],"question":"The note stated that \"further testing would be required before any conclusions could be drawn.\" What function do \"would\" and \"could\" serve here?","explanation":"在学术写作中，\"would\"和\"could\"代替\"will\"和\"can\"用于语气缓和（hedging），表达一种谨慎、非绝对的语气，避免过度自信的断言，是C1学术写作的重要特征。","correctIndex":2}]}},"3":{"levels":{"1":[{"type":"choice","options":["prepare","preparing","prepared","to prepare"],"sentence":"The director had the annual report ___ before the board meeting.","subSkill":"causative_have_get_with_past_participle","explanation":"'have + 宾语 + 过去分词' 是使役结构，表示安排他人完成某事。the annual report 是被准备的对象（逻辑宾语），所以用过去分词 prepared，而不是主动形式。","instruction":"选择正确选项，完成使役结构句子。","correctIndex":2},{"type":"choice","options":["It is alleged","There is alleged","It alleges","This is alleged"],"sentence":"___ that the company had been mismanaging its funds for years.","subSkill":"passive_reporting_verbs_it_is_claimed","explanation":"非人称被动结构以 'It is + 过去分词（报道动词）' 开头，形式主语为 it，真正内容由 that 从句表达。'It is alleged that...' 意为'据称……'，是学术及正式书面语中的标准用法。","instruction":"选择正确的非人称被动结构。","correctIndex":0},{"type":"choice","options":["fix","fixing","to fix","fixed"],"sentence":"After the storm, the residents got their roofs ___.","subSkill":"causative_have_get_with_past_participle","explanation":"'get + 宾语 + 过去分词' 是使役结构，表示安排他人完成某事。their roofs 是被修缮的对象，因此用过去分词 fixed。get 在此与 have 同义，但语气上稍显非正式。","instruction":"选择正确的使役结构，表示委托专业人员完成工作。","correctIndex":3},{"type":"choice","options":["It is widely acknowledged","It widely acknowledges","There is widely acknowledged","It was widely acknowledging"],"sentence":"___ that urban pollution levels have risen sharply in the last decade.","subSkill":"impersonal_passive_in_academic_prose","explanation":"表示被广泛承认的事实，使用非人称被动结构 'It is widely acknowledged that...'。副词 widely 修饰过去分词 acknowledged，整体表达客观、正式的学术立场。","instruction":"选择适合填入学术句子的正确结构。","correctIndex":0},{"type":"choice","options":["to bring","to be brought","bringing","being brought"],"sentence":"The new legislation is expected ___ significant changes to the healthcare system.","subSkill":"passive_infinitive_and_gerund","explanation":"这里 the legislation 是主动带来变化的主体（legislation brings changes），所以用主动不定式 to bring，而非被动不定式。'be expected to do' 表示预期做某事，主语是动作的施动者。","instruction":"选择正确的被动不定式结构。","correctIndex":0},{"type":"choice","options":["had been destroyed","have been destroyed","were destroyed","are destroyed"],"sentence":"By the time the auditors arrived, all the financial records ___ already.","subSkill":"passive_with_complex_tenses","explanation":"'by the time + 过去式' 表示在过去某一时刻之前已发生的事，应使用过去完成时被动 'had been + 过去分词'。这表明记录被销毁的时间早于审计员到达的时间。","instruction":"选择正确的复杂时态被动语态。","correctIndex":0},{"type":"choice","options":["says","is said","said","is saying"],"sentence":"People say that she invented a revolutionary technique. → She ___ to have invented a revolutionary technique.","subSkill":"passive_reporting_verbs_it_is_claimed","explanation":"将 'People say that she invented...' 转换为以人物为主语的被动报道结构：'She is said to have invented...'，其中 to have invented 是完成不定式，表示发明行为发生在说话时间之前。","instruction":"选择正确选项，将主动报道句改为被动报道句。","correctIndex":1},{"type":"choice","options":["exclude","be excluded","being excluded","having excluded"],"sentence":"The professor objected to ___ from the research committee without explanation.","subSkill":"passive_infinitive_and_gerund","explanation":"'object to' 后面接动名词（-ing 形式）。教授是被排除的对象（逻辑上是被动关系），所以用被动动名词 'being excluded'，意为'反对被（人）排除在外'。","instruction":"选择正确的被动动名词结构。","correctIndex":2}],"2":[{"type":"choice","options":["It is suggested","People suggest","Someone suggests","They are suggesting"],"sentence":"___ that exposure to microplastics may affect human hormonal systems, though further research is needed.","subSkill":"impersonal_passive_in_academic_prose","explanation":"学术写作中需要用非人称被动结构表达不确定性或客观观点，'It is suggested that...' 比 'People suggest' 更正式、更客观，避免明确指出信息来源，符合学术语体规范。","instruction":"选择最符合学术语体的表达方式。","correctIndex":0},{"type":"choice","options":["authenticate","to authenticate","authenticating","authenticated"],"sentence":"The gallery owner had the painting ___ by a forensic art expert before putting it up for auction.","subSkill":"causative_have_get_with_past_participle","explanation":"'have + 宾语 + 过去分词' 中，宾语（the painting）与动词（authenticate）之间是被动关系（画作被鉴定），所以用过去分词 authenticated，表示画廊主人安排了鉴定工作。","instruction":"选择正确的结构，表示某人安排专业人士完成任务。","correctIndex":3},{"type":"fill","sentence":"The contract (sign) ___ by both parties before the deadline passed.","subSkill":"passive_with_complex_tenses","explanation":"'before the deadline passed' 表明签署发生在截止日期之前，即过去某一时点之前，应用过去完成时被动 'had been signed'。","instruction":"用括号内动词的正确被动形式填写空白处，注意时态语境。","acceptableAnswers":["had been signed"]},{"type":"fill","sentence":"The ancient manuscript (believe) ___ to contain a coded map of the lost city.","subSkill":"passive_reporting_verbs_it_is_claimed","explanation":"以主语（the manuscript）起头的被动报道结构：'主语 + is/are + 报道动词的过去分词 + to + 动词原形'。这等同于 'It is believed that the manuscript contains...'，表达客观传递的信息。","instruction":"用括号内动词的正确形式填写空白处，完成被动报道结构。","acceptableAnswers":["is believed"]},{"type":"choice","options":["to interview","to be interviewed","being interviewed","having interview"],"sentence":"After the scandal, the CEO avoided ___ by the press for several weeks.","subSkill":"passive_infinitive_and_gerund","explanation":"'avoid' 后面接动名词（-ing 形式），不接不定式。CEO 是被采访的对象（被动关系），所以用被动动名词 'being interviewed'，意为'避免接受采访'。","instruction":"选择正确的被动不定式或动名词，完成句子。","correctIndex":2},{"type":"fill","sentence":"The film studio got its entire soundtrack (re-record) ___ after the composer complained about the original mixing.","subSkill":"causative_have_get_with_past_participle","explanation":"'get + 宾语 + 过去分词' 是使役结构。soundtrack 是被重新录制的对象，因此用过去分词 re-recorded，表示制片公司委托他人完成了重新录制工作。","instruction":"用括号内动词的正确形式填写空白处，完成使役结构。","acceptableAnswers":["re-recorded"]},{"type":"fill","sentence":"People claim that the researcher falsified the data. → The researcher (claim) ___ to have falsified the data.","subSkill":"passive_reporting_verbs_it_is_claimed","explanation":"将 'People claim that...' 转换为以研究者为主语的被动结构：'The researcher is claimed to have falsified...'，其中完成不定式 to have falsified 表示行为发生在 claim 之前。","instruction":"按照括号提示，用正确的被动不定式形式改写句子。","acceptableAnswers":["is claimed"]},{"type":"choice","options":["will become","will have become","would become","has become"],"sentence":"By 2030, it is projected that renewable energy ___ the dominant source of electricity in most developed nations.","subSkill":"passive_with_complex_tenses","explanation":"'By 2030' 表示在未来某时刻之前已完成的状态，应用将来完成时 'will have become'。这与 'by + 过去时间 → 过去完成时' 的规律平行，只是时间参照点是未来。","instruction":"选择正确的复杂被动时态，完成学术语境句子。","correctIndex":1}],"3":[{"type":"fill","sentence":"It (establish) ___ that the policy (introduce) ___ without adequate consultation with local authorities.","subSkill":"passive_with_complex_tenses","explanation":"第一空用现在完成时被动 'has been established'，表示现在已经证实的结论；第二空用一般过去时被动 'was introduced'，表示过去某一具体时间发生的事件，两者时态对比体现了不同的时间关系。","instruction":"用括号内动词的正确被动形式填写两处空白。注意两句在时态上的对比。","acceptableAnswers":["has been established","was introduced"]},{"type":"fill","sentence":"The defendant denied (give) ___ access to the confidential files, insisting the system had been breached without her knowledge.","subSkill":"passive_infinitive_and_gerund","explanation":"'deny' 后接动名词。被告是被给予权限的对象（被动关系），且此行为发生在说话时间之前，因此用完成被动动名词 'having been given'，表示在过去某时被给予了权限。","instruction":"用括号内动词的正确形式填写空白处，完成被动不定式结构。","acceptableAnswers":["having been given"]},{"type":"fill","sentence":"Experts allege that the architect concealed structural flaws in the original design. → The architect (allege) ___ to (conceal) ___ structural flaws in the original design.","subSkill":"passive_reporting_verbs_it_is_claimed","explanation":"第一空：'is alleged' 是以 the architect 为主语的被动报道结构，对应原句中的 'Experts allege that'。第二空：因为隐瞒行为发生在陈述时间之前，用完成不定式 'to have concealed'，这里只填 'have concealed'（to 已在句中）。","instruction":"将主动报道句改写为以人物为主语的被动报道结构，填写空白处。","acceptableAnswers":["is alleged","have concealed"]},{"type":"fill","sentence":"By the time the inspection team arrived, the factory management had already got the faulty equipment (remove) ___ and the maintenance logs (update) ___.","subSkill":"causative_have_get_with_past_participle","explanation":"两处均使用 'get + 宾语 + 过去分词' 使役结构，宾语（faulty equipment / maintenance logs）与动词之间是被动关系，所以用过去分词 removed 和 updated。整句用过去完成时，表示在检查队到达之前已安排完成。","instruction":"用括号内词语的正确形式，完成这个结合使役结构与复杂时态的句子。","acceptableAnswers":["removed","updated"]}],"4":[{"type":"choice","options":["had been destroyed","have been destroyed","were being destroyed","would destroy"],"sentence":"By the time the audit team arrived, all the financial records ___ by the accountant.","subSkill":"passive_with_complex_tenses","explanation":"\"by the time...arrived\"表示在过去某时间点之前已完成的动作，需用过去完成时被动语态\"had been destroyed\"，表示记录在审计团队到达之前就已被销毁。","instruction":"选择正确的选项，完成句子。注意被动语态与完成时的结合。","correctIndex":0},{"type":"choice","options":["They are claiming","It has been suggested","People suggested","There is suggesting"],"sentence":"___ that prolonged exposure to microplastics may interfere with human hormonal systems.","subSkill":"impersonal_passive_in_academic_prose","explanation":"在学术写作中，非人称被动结构\"It has been suggested that...\"用于客观呈现观点，避免指向特定主体，现在完成时体现该观点是已有研究成果。","instruction":"选择正确的选项，完成学术报告句子。注意非人称被动结构的用法。","correctIndex":1},{"type":"choice","options":["get...to redesign","have...redesigned","make...redesigning","get...redesigning"],"sentence":"The CEO decided to ___ the entire software infrastructure ___ before the product launch.","subSkill":"causative_have_get_with_past_participle","explanation":"\"have + 宾语 + 过去分词\"是使役结构，表示安排他人完成某事，此处CEO安排别人重新设计基础架构，过去分词\"redesigned\"表示被动含义。","instruction":"选择正确的选项，完成句子。注意使役结构的正确形式。","correctIndex":1},{"type":"choice","options":["to exclude","to have been excluded","having excluded","to be excluding"],"sentence":"The whistleblower claimed ___ from the investigation by senior officials.","subSkill":"passive_infinitive_and_gerund","explanation":"\"to have been excluded\"是被动完成不定式，表示排除行为发生在\"claimed\"之前，且主语是动作的承受者，符合此处含义——举报人声称此前已被排除在调查之外。","instruction":"选择正确的选项，完成句子。注意被动不定式的用法。","correctIndex":1},{"type":"fill","sentence":"It (widely report) ___ that the government had concealed data relating to the environmental impact assessment.","subSkill":"passive_reporting_verbs_it_is_claimed","explanation":"\"It + 被动式 + that从句\"是标准的报告动词非人称被动结构，\"widely\"作为副词修饰整个被动结构；两种时态均可接受，取决于语境中报告是否与现在相关。","instruction":"用括号中动词的正确被动形式填空，注意报告动词的非人称被动结构。","acceptableAnswers":["has been widely reported","was widely reported"]},{"type":"fill","sentence":"After the break-in, the university authorities got all entry points (reinforce) ___ with electronic locks.","subSkill":"causative_have_get_with_past_participle","explanation":"\"get + 宾语 + 过去分词\"表示安排他人完成某事，宾语\"all entry points\"与动词\"reinforce\"是被动关系，因此用过去分词\"reinforced\"，表示入口被安装了电子锁。","instruction":"用适当形式填空，完成使役结构。括号中提供原形动词。","acceptableAnswers":["reinforced"]}],"5":[{"type":"fill","sentence":"The ancient manuscripts (believe) ___ to (store) ___ in the monastery for over three centuries before they were transferred to the national archive.","subSkill":"passive_reporting_verbs_it_is_claimed","explanation":"第一空：\"It is believed\"的倒装形式\"are believed to...\"，主语为文件，用现在时非人称被动；第二空：文件被存放是被动且发生在转移之前，故用完成被动不定式\"have been stored\"。","instruction":"用括号中动词的正确形式填空，完成这段学术语篇，注意语态、时态与语境的配合。","acceptableAnswers":["are believed","have been stored"]},{"type":"fill","sentence":"The researcher strongly objected to the committee (exclude) ___ her findings from the final report without consultation.","subSkill":"passive_infinitive_and_gerund","explanation":"\"object to\"后接动名词；此处committee是排除行为的施动者，findings是承受者，主句主语her与排除行为的承受者不同；\"excluding\"描述正在进行的动作，\"having excluded\"强调动作已完成，两者均可接受。","instruction":"根据括号中的提示，用正确的被动动名词形式改写划线部分，保持句意不变。","acceptableAnswers":["excluding","having excluded"]},{"type":"choice","options":["Researchers demonstrated","It has since been demonstrated","They have since demonstrated","Studies are demonstrating"],"sentence":"___ by subsequent studies that the initial model had significantly overestimated carbon absorption rates.","subSkill":"impersonal_passive_in_academic_prose","explanation":"\"It has been demonstrated that...\"是学术语篇中标准的非人称被动报告结构，\"since\"表示此结论在最初研究发布后已被证明，现在完成时体现与当前研究状态的关联，比主动句更客观正式。","instruction":"选择最符合学术写作规范的选项，完成句子。","correctIndex":1},{"type":"fill","sentence":"The painting (believe) ___ in the early twentieth century.","subSkill":"passive_reporting_verbs_it_is_claimed","explanation":"将\"Experts believe that + 从句\"转换为以宾语为主语的被动结构：\"The painting is believed to have been forged\"；因伪造行为发生在believe之前，用完成被动不定式\"to have been forged\"表示时间先后关系。","instruction":"这是关键词转换题。请根据括号内的提示词，改写句子，保持与原句相近的意思。原句：Experts believe that the painting was forged in the early twentieth century. 改写时以\"The painting\"开头，使用\"(believe)\"。","acceptableAnswers":["is believed to have been forged"]}]},"mission":{"title":"The Forgotten Archive","scenario":"背景：1912年，Alderton市立图书馆的全部藏书与档案神秘失踪，此后从未被找到。直到最近，你的团队在一座废弃仓库的地下室发现了一批密封箱子，里面似乎藏有相关线索。你需要以客观、正式的学术语气撰写初步报告摘要，既要传达已知信息，也要恰当表达尚未证实的推测。","scaffolds":[{"hint":"用非人称被动结构介绍历史背景，说明失踪事件的性质（如：deliberate removal / an administrative cover-up）","prefix":"It is now widely acknowledged that the disappearance of the Alderton Municipal Library collection in 1912","suffix":"","example":"It is now widely acknowledged that the disappearance of the Alderton Municipal Library collection in 1912 was not accidental but constituted a deliberate act of concealment.","grammarCheck":"impersonal_passive_in_academic_prose"},{"hint":"用两个使役结构（have + 宾语 + 过去分词 / get + 宾语 + 过去分词）描述团队安排的工作，如检验箱子和整理文件","prefix":"The research team has had the sealed crates","suffix":"and is now getting the recovered documents","example":"The research team has had the sealed crates examined by a forensic specialist and is now getting the recovered documents catalogued by archivists at the university.","grammarCheck":"causative_have_get_with_past_participle"},{"hint":"先用被动报道不定式结构陈述关于藏品的推测，再用非人称被动表达研究期望","prefix":"The collection is reported to","suffix":"It is hoped that further analysis will allow","example":"The collection is reported to have been deliberately hidden rather than destroyed. It is hoped that further analysis will allow the full history of the library to be reconstructed.","grammarCheck":"passive_reporting_verbs_it_is_claimed"}],"description":"你是一名为学术期刊撰稿的历史研究员。你刚刚发现了一批关于20世纪初一座失踪图书馆的档案文件。请用正式的学术书面语，写一篇简短的研究报告摘要（约100-120字），描述这批档案的发现经过、相关历史事件的背景，以及研究团队下一步的计划。要求自然地运用本单元的目标语法结构。","grammarType":"passive_reporting_verbs_it_is_claimed"},"discover":{"tip":"**被动语态的复杂时态与使役结构对比**\n\n**1. 多时态被动语态**\n英语被动语态可出现在各种时态中，C1阶段需要掌握较复杂的形式：\n- 完成式被动：The plans *had been approved* before construction began.\n- 不定式被动：The rivets *are reported to have been checked* by hand.\n- 动名词被动：She objected to *being excluded* from the meeting.\n规律：'be + 过去分词'构成被动，时态由 be 的形式决定。\n\n**2. 非人称被动（学术语体）**\n用 'It is + 报道动词（said/believed/claimed/acknowledged/assumed）+ that从句' 来客观传递信息：\n- It is said that she was a genius.\n- It is widely assumed that the law will change.\n也可转换为：She *is said to have been* a genius.\n\n**3. 使役结构 have/get + 宾语 + 过去分词**\n表示安排他人完成某事：\n- The council *had the bridge restored*. （have 更正式）\n- They *got the system upgraded* quickly. （get 稍口语，也用于书面语）\n\n**常见错误：**\n- ❌ It is believed that the bridge *designed* by Voss. → ❌（that从句必须是完整句）\n- ✅ It is believed that the bridge *was designed* by Voss.\n- ❌ They got the bridge *to repair*. → ❌（使役结构用过去分词，不用不定式）\n- ✅ They got the bridge *repaired*.","story":{"text":"The Harlow Bridge, which is said to have been designed by a forgotten engineer named Clara Voss, was completed in 1923 after years of difficult construction. It is believed that the original blueprints were destroyed in a fire, though some historians claim the documents were deliberately hidden. The bridge had been inspected numerous times before it was finally opened to the public, and every rivet is reported to have been checked by hand. Over the decades, the city had the bridge repaired three times and got the lighting system upgraded by a specialist firm in 1998. It is widely acknowledged that the bridge transformed the commercial district entirely. Today, visitors are expected to admire not only its engineering but also its elegant stonework. Proposals to have the structure demolished were firmly rejected in 2004 after a campaign led by local residents. Instead, the council got a full restoration completed within two years. It is now considered to be one of the finest examples of early twentieth-century civil engineering in the country, and it is generally assumed that Clara Voss deserves far greater recognition than she has ever been given.","title":"The Bridge That Changed a City","highlights":["is said to have been designed","it is believed that","is reported to have been checked","had the bridge repaired","got the lighting system upgraded","are expected to admire","to have the structure demolished","got a full restoration completed","it is widely acknowledged","is generally assumed"]},"questions":[{"options":["Causative have/get + past participle","Impersonal passive with a reporting verb","Passive infinitive after a modal","Future perfect passive"],"question":"In the story, 'It is believed that the original blueprints were destroyed' uses which grammatical structure?","explanation":"这句话用了非人称被动结构 'It is believed that...'，其主语是形式主语 it，真正的内容由 that 从句表达。这是学术语体中常见的报道动词被动结构，说话者用它来传达信息而不明确指出信息来源。","correctIndex":1},{"options":["The city repaired the bridge itself.","The city arranged for someone else to repair the bridge.","The bridge was repaired without the city's knowledge.","The city was forced to repair the bridge."],"question":"What does 'the city had the bridge repaired' tell us about the relationship between the city and the repair work?","explanation":"'have + 宾语 + 过去分词' 是使役结构，表示主语安排或委托他人完成某事，而不是主语亲自完成。这里 the city 没有亲自修桥，而是安排（委托）了相关人员进行修缮。","correctIndex":1},{"options":["Passive gerund used as subject","Causative have + object + past participle as a post-noun infinitive phrase","Impersonal passive with reporting verb","Future passive infinitive after a modal verb"],"question":"The phrase 'Proposals to have the structure demolished' contains which structure?","explanation":"'to have the structure demolished' 是不定式形式的使役结构（have + 宾语 + 过去分词），此处作后置定语修饰 Proposals，表示拆除该建筑的提议。这体现了使役结构在名词短语中的灵活运用。","correctIndex":1}]}},"4":{"discover":{"story":{"title":"The Bridge That Changed Everything","text":"The old bridge over the Riven gorge was finally completed in 1998. Had the engineers not solved the foundation problem in time, the entire project would have collapsed. But for their ingenuity, the remote village of Calla would still be cut off from the outside world today — a vivid example of how a past event shapes a present reality. Were the bridge to fall into disrepair now, thousands of commuters would lose their only route to the city. Suppose the local government had invested more heavily in maintenance over the years, the structure would be in far better condition at present. Should any cracks appear in the supporting pillars, engineers are required to report them within twenty-four hours — a rule introduced after a near-disaster in 2011. Provided that funding remains stable, the bridge authority plans to carry out a full renovation by 2026. The project manager noted that the 1998 construction would have taken twice as long but for the volunteer labour provided by Calla residents. Had a different design been chosen back then, the bridge might not be standing today, and the village would still be relying on a seasonal ferry. These intertwined conditions — past decisions echoing into the present — remind us that infrastructure is never merely concrete and steel; it is the accumulated result of choices made under pressure.","highlights":["Had the engineers not solved","But for their ingenuity","Were the bridge to fall","Suppose the local government had invested","Should any cracks appear","Provided that funding remains","but for the volunteer labour","Had a different design been chosen"]},"questions":[{"question":"Which sentence shows a MIXED conditional (a past condition affecting a present result)?","options":["Should any cracks appear, engineers must report them within twenty-four hours.","Had a different design been chosen back then, the bridge might not be standing today.","Provided that funding remains stable, the authority plans a full renovation.","Were the bridge to fall into disrepair now, thousands of commuters would lose their route."],"correctIndex":1,"explanation":"混合条件句将过去的条件（过去完成时 Had a different design been chosen）与现在的结果（情态动词 might not be standing today）结合起来，表示过去不同的选择将如何影响现在的状态。选项A是倒装条件句（should），选项C是真实条件句，选项D是虚拟现在/将来条件句（were to）。"},{"question":"What grammatical structure does 'But for their ingenuity, the village would still be cut off' use?","options":["An inverted conditional with 'had'","An implied conditional using 'but for' to replace 'if it had not been for'","A formal conditional using 'provided that'","A conditional with 'suppose' introducing a hypothetical"],"correctIndex":1,"explanation":"'But for + 名词短语'是隐含条件句，省略了显式的 if 从句，相当于 'If it had not been for their ingenuity'。它不使用 had/were/should 的倒装形式，而是用介词短语暗示条件关系，因此属于隐含条件（implied conditional）。"},{"question":"In formal writing, 'Should any cracks appear' is equivalent to which of the following?","options":["If any cracks would appear","If any cracks appeared","If any cracks should appear / If any cracks appear","If any cracks had appeared"],"correctIndex":2,"explanation":"倒装条件句 'Should any cracks appear' 是将 if 省略并将 should 提到主语之前，等同于 'If any cracks should appear' 或口语化的 'If any cracks appear'。它表示一种低概率或正式语境中的将来假设，而非过去事实（排除选项D）或带 would 的错误形式（排除选项A）。"}],"tip":"**C1条件句核心对比与常见错误**\n\n**1. 混合条件句（Mixed Conditionals）**\n过去条件 + 现在结果：If + had done → would/might + be doing (now)\n例：Had she studied harder, she would be a doctor today.\n常见错误：结果从句误用 would have been（那变成了纯第三类条件句，表示过去结果，不是现在状态）。\n\n**2. 倒装条件句（Inverted Conditionals）**\n省略 if，将助动词提前：\n- Had + 主语 + 过去分词（= If ... had done）\n- Were + 主语 + to + 动词原形（= If ... were to do，正式/低概率将来）\n- Should + 主语 + 动词原形（= If ... should do，正式建议/警示）\n常见错误：写成 'Had he would solve...' — 倒装后主句用情态动词，if 从句（现在是倒装部分）不用 would。\n\n**3. 隐含条件句（Implied Conditionals）**\n用介词短语替代 if 从句，条件隐含在上下文中：\n- But for + 名词（= If it had not been for）\n- Otherwise（= if not / if that were not the case）\n- Without + 名词（类似 but for）\n例：But for the rain, we would have finished. / We hurried; otherwise, we would have missed the train.\n常见错误：otherwise 后误用过去简单时作为主句动词（'otherwise we missed'），应保持情态结构。\n\n**4. 正式写作中的条件结构**\n'Provided (that)', 'Suppose (that)', 'On condition that' 引导条件从句，语气比 if 更正式或更具限制性，主句动词与 if 句型一致。"},"mission":{"title":"致未来委员会的政策备忘录","description":"你是一位城市规划顾问，需要向委员会提交一份正式的政策备忘录。备忘录分析过去决策对现在的影响，并就未来政策提出建议。全程使用书面英文，综合运用混合条件句、倒装条件句和隐含条件句，体现C1水平的正式书面语。","scenario":"城市委员会正在评估一个已搁置十年的绿色交通项目。你需要写三段话：第一段分析过去决策如何影响现在的处境（混合条件/隐含条件）；第二段提出正式政策建议（倒装条件/provided that）；第三段预警潜在风险（should/were to倒装）。","grammarType":"mixed_conditionals_past_to_present","scaffolds":[{"prefix":"Had the committee approved the green transit plan a decade ago,","suffix":"today.","hint":"用混合条件句描述过去决策对现在的影响，结果从句用 would + be/have（现在状态）","grammarCheck":"mixed_conditionals_past_to_present","example":"Had the committee approved the green transit plan a decade ago, the city would be far less dependent on private vehicles today."},{"prefix":"Provided that the council allocates sufficient funding this quarter,","suffix":"within eighteen months.","hint":"用 provided that 引导正式限定条件，主句描述真实将来结果，体现政策建议的正式语气","grammarCheck":"conditionals_in_formal_writing","example":"Provided that the council allocates sufficient funding this quarter, the first phase of the network could be operational within eighteen months."},{"prefix":"Should any significant cost overruns arise during construction,","suffix":"without delay.","hint":"用 should 倒装结构表示正式警示/规程要求，主句说明应采取的措施","grammarCheck":"inverted_conditionals_had_were_should","example":"Should any significant cost overruns arise during construction, the oversight committee must be informed without delay."}]},"levels":{"1":[{"type":"choice","instruction":"选择正确答案，完成这个混合条件句（过去条件，现在结果）。","sentence":"Had the company invested in better technology ten years ago, it ___ the market leader today.","options":["would have been","would be","will be","had been"],"correctIndex":1,"explanation":"混合条件句：过去条件（Had + 过去分词）搭配现在结果，结果从句用 would + 动词原形（would be），表示对现在状态的推断。would have been 表示对过去结果的推断，不符合'today'这一现在时间状语。","subSkill":"mixed_conditionals_past_to_present"},{"type":"choice","instruction":"选择正确的倒装条件句形式，使其与括号中的 if 句意思相同。","sentence":"(If the director should receive any complaints,) ___ any complaints, she must respond within two days.","options":["If the director receives","Should the director receive","Had the director received","Were the director to have received"],"correctIndex":1,"explanation":"Should + 主语 + 动词原形 是 'if + 主语 + should + 动词原形' 的倒装形式，用于正式语境中表示万一发生某事。Had + 过去分词 指过去假设，Were to do 指将来正式假设但结构不同，均不符合原句时态。","subSkill":"inverted_conditionals_had_were_should"},{"type":"choice","instruction":"选择最恰当的词语完成这个隐含条件句。","sentence":"___ the firefighters' quick response, the entire warehouse would have burned down.","options":["Provided","Should","But for","Suppose"],"correctIndex":2,"explanation":"'But for + 名词短语' 是隐含条件句，等同于 'If it had not been for the firefighters' quick response'，表示若非某事物则会有相反结果。Provided 和 Suppose 引导显式条件从句，Should 用于倒装条件，均不适合此处结构。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"type":"choice","instruction":"选择正确答案，完成这个倒装条件句。","sentence":"___ the old treaty still in force, the two nations would not be in conflict today.","options":["Had","Should","Were","Provided"],"correctIndex":2,"explanation":"此句表示对现在状态的虚拟（the treaty is NOT in force now），用 Were + 主语 + 形容词/名词结构，相当于 'If the old treaty were still in force'。Had 用于过去完成假设，Should 用于将来/万一情况，均不符合对现在状态的虚拟。","subSkill":"inverted_conditionals_had_were_should"},{"type":"choice","instruction":"以下哪个句子是正确的混合条件句？","sentence":"Choose the correct mixed conditional sentence.","options":["If she had taken the job, she would have been happier now.","Had she taken the job, she would be happier now.","Were she to take the job, she would have been happier.","Should she take the job, she would have been happier."],"correctIndex":1,"explanation":"混合条件句：Had she taken the job（过去假设，相当于 if 从句用过去完成时）+ would be happier now（现在结果，情态动词 + 原形）。选项A的结果从句用 would have been 是纯第三类条件句（过去结果），选项C和D的结果从句也用了 would have been，指向过去，均不是标准混合条件句。","subSkill":"mixed_conditionals_past_to_present"},{"type":"choice","instruction":"选择最恰当的词完成这个正式条件句。","sentence":"___ that all participants submit their forms before Friday, the committee will proceed with the vote.","options":["Suppose","But for","Otherwise","Provided"],"correctIndex":3,"explanation":"'Provided that + 从句' 表示'只要……就……'，是正式书面语中常见的条件结构，相当于 if and only if。Suppose 也可引导条件句但语气更像假设，But for 为介词短语结构，Otherwise 是副词，三者均不能直接引导 that 从句与主句构成此类正式条件关系。","subSkill":"conditionals_in_formal_writing"},{"type":"choice","instruction":"选择正确的词完成句子，使其表示'如果不是因为……'。","sentence":"We managed to finish the report on time. ___, we would have missed the deadline.","options":["But for that","Otherwise","Provided that","Were that"],"correctIndex":1,"explanation":"Otherwise 在此处用作副词，指'如果情况不是这样'（即如果我们没有按时完成），后面的结果从句使用情态动词 would have missed，构成隐含条件句。But for 后需跟名词短语，Provided that 引导条件从句，Were that 结构不完整，均不适合此处用法。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"type":"choice","instruction":"选择正确答案完成这个倒装条件句，使其等同于括号中的 if 句。","sentence":"(If the government had not intervened,) ___ the government not intervened, the bank would have failed.","options":["Should","Were","Had","Would"],"correctIndex":2,"explanation":"Had + 主语 + 过去分词 是 'if + 主语 + had + 过去分词' 的倒装形式，表示对过去事件的虚拟假设。Should 用于将来/万一情况，Were 用于现在虚拟或 were to 结构，Would 不用于条件从句的倒装。","subSkill":"inverted_conditionals_had_were_should"}],"2":[{"type":"choice","instruction":"选择正确答案完成这个混合条件句。","sentence":"Had the researchers published their findings a decade earlier, the treatment ___ widely available by now.","options":["would have been","would be","will have been","had been"],"correctIndex":1,"explanation":"混合条件句中，过去条件（Had + 过去分词）对应现在结果（would + be），'by now' 是现在时间参照点，说明结果是对当前状态的推断。would have been 表示过去结果（纯第三类），will have been 是将来完成时语气，had been 是过去完成时，均不符合现在结果的要求。","subSkill":"mixed_conditionals_past_to_present"},{"type":"fill","instruction":"将括号中的动词变成正确形式，完成这个倒装混合条件句。注意：条件部分指过去，结果部分指现在。","sentence":"Had the city planners (choose) ___ a different route, the highway (not / run) ___ through the nature reserve today.","acceptableAnswers":["chosen","would not run"],"explanation":"Had + 过去分词（chosen）构成过去虚拟条件的倒装形式；结果从句指现在（today），用 would + 动词原形（would not run），体现混合条件句的核心特征：过去假设影响现在状态。","subSkill":"mixed_conditionals_past_to_present"},{"type":"choice","instruction":"以下哪个句子在正式书面语中使用了正确的倒装条件结构？","sentence":"Choose the sentence with correct inverted conditional form for formal writing.","options":["Were any errors to be found, please report them immediately.","Should any errors would be found, please report them immediately.","Had any errors be found, please report them immediately.","If any errors should found, please report them immediately."],"correctIndex":0,"explanation":"Were + 主语 + to be done 是倒装条件句的正确结构，用于表达正式语境中的将来假设或指示。选项B中 should 后误加 would；选项C中 Had 后应用过去分词（been found）；选项D中 if 从句保留了 if 但省略了助动词的正确形式（should be found）。","subSkill":"inverted_conditionals_had_were_should"},{"type":"fill","instruction":"用 'but for' 改写下面的 if 句，保持意思不变。填写空白处缺失的部分。","sentence":"If it had not been for the translator's skill, the peace talks (fail) ___.","acceptableAnswers":["would have failed"],"explanation":"But for + 名词短语 等同于 'if it had not been for'，表示对过去事件的反事实假设，结果从句用 would have + 过去分词（would have failed）。注意题目已经将 if 从句转换为 But for 结构，要求填写符合过去虚拟语气的主句结果。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"type":"choice","instruction":"选择最适合正式合同或学术写作风格的条件句。","sentence":"Choose the most appropriate conditional for formal/academic writing.","options":["If the data would show a significant variance, the trial will be halted.","Should the data show a significant variance, the trial will be halted.","Suppose the data shows a significant variance, the trial would be halted.","Were the data showing a significant variance, the trial will be halted."],"correctIndex":1,"explanation":"Should + 主语 + 动词原形（Should the data show）是正式书面语中常见的倒装条件结构，用于规则、合同、学术写作，主句用将来时表示真实结果。选项A中 would show 在条件从句中不规范；选项C中 Suppose 语气偏假设性，且主句 would be halted 暗示不确定性与 if 不符；选项D中 were doing 结构语义不当。","subSkill":"conditionals_in_formal_writing"},{"type":"fill","instruction":"用 'should' 的倒装形式改写下面的 if 句，省略 if，将 should 提前。","sentence":"If any member of staff should need assistance, they are encouraged to contact HR directly. → ___ any member of staff need assistance, they are encouraged to contact HR directly.","acceptableAnswers":["Should"],"explanation":"将 'if + 主语 + should + 动词原形' 转换为倒装形式时，省略 if，将 should 移至句首，主语保持原位，动词原形不变。这是正式书面语（规章制度、合同等）中的标准倒装条件句。","subSkill":"inverted_conditionals_had_were_should"},{"type":"choice","instruction":"选择正确的词完成包含 'suppose' 的条件句。","sentence":"Suppose the new policy ___ without public consultation, there would be significant opposition.","options":["is introduced","were introduced","had introduced","will be introduced"],"correctIndex":1,"explanation":"'Suppose + 从句' 引导假设条件时，若主句用 would（表示非真实假设），则 suppose 从句用虚拟语气（were + 过去分词），相当于 'If the new policy were to be introduced without consultation'。is introduced 是真实条件，had introduced 时态不符，will be introduced 不用于虚拟假设。","subSkill":"conditional_like_structures_suppose_provided"},{"type":"fill","instruction":"在空白处填入一个合适的词，使句子成为正式的隐含条件句，意为'只要……'。","sentence":"___ that both parties agree to the terms, the contract will be signed on Monday.","acceptableAnswers":["Provided","Providing"],"explanation":"'Provided (that)' 或 'Providing (that)' 均可引导正式条件从句，意为'只要，在……条件下'，比 if 更具限制性和正式感，常见于法律文书、合同及学术写作。两者在书面语中均被接受。","subSkill":"conditionals_in_formal_writing"}],"3":[{"type":"fill","instruction":"将括号中的动词变成正确形式，完成混合条件句。","sentence":"Had the expedition team (secure) ___ better funding at the outset, they (not / be) ___ struggling to complete the final phase today.","acceptableAnswers":["secured","would not be"],"explanation":"混合条件句：Had + 过去分词（secured）表示过去虚拟条件；would + be + 现在分词（would not be struggling）表示对现在持续状态的推断，'today' 确认是现在时间参照。would not have been struggling 会指过去持续状态，与 today 不符。","subSkill":"mixed_conditionals_past_to_present"},{"type":"reorder","instruction":"将这些词语排列成一个正确的倒装混合条件句（过去条件，现在结果）。","words":["the","architect","original","approved","the","design","had","building","be","standing","would","still","the"],"correctSentence":"Had the architect approved the original design, the building would still be standing.","explanation":"倒装混合条件句结构：Had + 主语（the architect）+ 过去分词（approved）+ 其余条件内容，逗号后主句用 would + 副词 + 动词短语（would still be standing）表示现在结果。注意 had 提前到句首且无 if，是倒装的标志。","subSkill":"mixed_conditionals_past_to_present"},{"type":"fill","instruction":"用 'were...to' 的倒装结构改写下面的 if 句，保持意思不变。","sentence":"If the central bank were to raise interest rates sharply, inflation would likely fall within a year. → ___ the central bank ___ raise interest rates sharply, inflation would likely fall within a year.","acceptableAnswers":["Were","to"],"explanation":"'Were + 主语 + to + 动词原形' 是 'if + 主语 + were to + 动词原形' 的倒装形式，用于正式书面语中表示将来不太可能或假设性情况。省略 if，将 were 提至句首，to 保留在主语之后与动词原形连用。","subSkill":"inverted_conditionals_had_were_should"},{"type":"reorder","instruction":"将这些词语排列成一个正确的句子，使用 'but for' 表达隐含条件。","words":["but","for","the","interpreter's","intervention","the","negotiations","have","broken","would","down"],"correctSentence":"But for the interpreter's intervention, the negotiations would have broken down.","explanation":"But for + 名词短语（the interpreter's intervention）放在句首，逗号后主句用 would have + 过去分词（would have broken down）表示过去反事实结果，等同于 'If it had not been for the interpreter's intervention'。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"type":"fill","instruction":"用括号中的词语将句子改写为关键词转换题，保持原意。在空白处填写完整的转换结果。","sentence":"The subsidy was granted; as a result, the small farms are still operating today. (BUT FOR) → But for the subsidy, the small farms ___ today.","acceptableAnswers":["would not be operating","would not still be operating"],"explanation":"But for 引入过去的反事实条件（没有补贴），结果影响现在（today），因此主句用混合条件句的现在结果形式：would not be operating（would + not + 动词-ing 表示现在持续状态）。这同时体现了 but for 隐含条件与混合条件的结合。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"type":"reorder","instruction":"将这些词语排列成一个正确的正式倒装条件句，适合用于合同或规程文件。","words":["should","any","discrepancy","arise","during","the","audit","the","board","notified","be","must","immediately"],"correctSentence":"Should any discrepancy arise during the audit, the board must be notified immediately.","explanation":"Should + 主语（any discrepancy）+ 动词原形（arise）+ 状语（during the audit）构成正式倒装条件从句，省略 if；主句为带情态动词的被动结构（must be notified），体现正式书面语（规程、合同）中的典型语气。","subSkill":"conditionals_in_formal_writing"},{"type":"fill","instruction":"用 'suppose' 或 'provided that' 中更合适的一个完成句子，并将括号中的动词变成正确形式。选择的词语应体现对正式程序的限定条件。","sentence":"___ that the applicant (meet) ___ all eligibility criteria, the grant will be awarded without further review.","acceptableAnswers":["Provided","meets"],"explanation":"'Provided that' 用于正式限定条件，意为'只要满足……条件'，从句动词用一般现在时（meets）表示真实条件（不是虚拟）。Suppose 偏向假设性推断，与此处强调程序性要求的语境不符。grant will be awarded 是真实将来结果。","subSkill":"conditional_like_structures_suppose_provided"},{"type":"fill","instruction":"关键词转换：用括号中的词改写句子，保持原意，填写空白处。","sentence":"If the merger had been completed two years earlier, the company would not be facing bankruptcy now. (HAD) → ___ the merger ___ two years earlier, the company would not be facing bankruptcy now.","acceptableAnswers":["Had","been completed"],"explanation":"将 'if + 主语 + had + 过去分词' 转换为倒装形式：省略 if，将 Had 提至句首，主语（the merger）紧随其后，再接过去分词短语（been completed）。结果从句保持不变（would not be facing = 混合条件，现在状态）。","subSkill":"mixed_conditionals_past_to_present"}],"4":[{"type":"choice","instruction":"选择正确选项，完成这个混合条件句。句子描述：过去没有做某事，导致现在的状态。","sentence":"If she ___ the contract last year, the company would be in a much stronger position now.","options":["signed","had signed","would sign","has signed"],"correctIndex":1,"explanation":"混合条件句：条件从句描述过去未发生的事（去年未签合同），用过去完成时 had signed；主句描述对现在的影响，用 would + 动词原形。","subSkill":"mixed_conditionals_past_to_present"},{"type":"choice","instruction":"选择正确的倒装条件句形式，使其与原句意思相同。原句：If the budget had been approved, we would have launched the project.","sentence":"___ the budget approved, we would have launched the project.","options":["Had been","Were","Should","Did"],"correctIndex":0,"explanation":"倒装条件句中，将 had 提前并省略 if，结构为 Had + 主语 + 过去分词。此处 Had been the budget approved 是对虚拟过去情况的倒装表达。","subSkill":"inverted_conditionals_had_were_should"},{"type":"fill","instruction":"用括号中动词的正确形式填空，完成这个含 but for 的隐含条件句。","sentence":"But for the director's timely intervention, the merger (collapse) ___ completely.","acceptableAnswers":["would have collapsed"],"explanation":"but for 表示隐含条件，意为 if it had not been for（若不是……）。它暗示一个虚拟过去条件，所以主句用 would have + 过去分词，表示过去本会发生的结果。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"type":"error","instruction":"下列句子中有一个词语使用错误，找出并改正。","words":["Were","I","to","known","the","full","facts,","I","would","have","acted","differently."],"errorIndex":3,"correction":"know","explanation":"Were + 主语 + to + 动词原形 是正式倒装条件句的固定结构，表示将来或假设情况。动词应使用原形 know，而非过去分词 known。","subSkill":"inverted_conditionals_had_were_should"},{"type":"choice","instruction":"选择最合适的选项，完成正式书面语中的条件句。","sentence":"___ any applicant fail to submit the required documents by the deadline, their application will be automatically disqualified.","options":["If","Should","Were","Had"],"correctIndex":1,"explanation":"在正式书面语中，Should 用于倒装条件句，表示将来某种可能但不确定的情况，语气比 if 更正式。结构为 Should + 主语 + 动词原形。","subSkill":"conditionals_in_formal_writing"},{"type":"fill","instruction":"用适当的形式填空，完成混合条件句。注意：他过去没有学习法律，所以现在不是律师。","sentence":"If Marcus (study) ___ law at university, he (be) ___ a qualified lawyer today.","acceptableAnswers":["had studied","would be"],"explanation":"混合条件句：条件从句指过去未发生的事，用过去完成时 had studied；主句指对现在的影响，用 would + 动词原形 be。两个时间框架不同，这是混合条件句的核心特征。","subSkill":"mixed_conditionals_past_to_present"},{"type":"error","instruction":"下列句子中有一个词语使用错误，找出并改正。","words":["The","project","succeeded;","otherwise,","we","will","have","lost","all","the","funding."],"errorIndex":5,"correction":"would","explanation":"otherwise 此处表示隐含的虚拟过去条件（如果项目没有成功），主句应使用 would have lost 而非 will have lost，因为是对过去情况的假设，不是将来的推测。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"type":"choice","instruction":"选择正确选项，完成含 provided that 的正式条件句。","sentence":"The new policy will take effect ___ all senior managers have reviewed and approved the final draft.","options":["provided that","but for","had","were"],"correctIndex":0,"explanation":"provided that 意为只要……，表示条件，是正式书面语中常用的条件连接词，此处语义最准确。but for 表示若非，had 和 were 是倒装结构，不适合此句语境。","subSkill":"conditional_like_structures_suppose_provided"}],"5":[{"type":"fill","instruction":"用括号中动词的正确形式填空，完成这个倒装条件句（正式书面语）。","sentence":"___ (be) it not for the legal team's expertise, the settlement (reach, passive) ___ so quickly.","acceptableAnswers":["Were","would not have been reached"],"explanation":"Were it not for 是固定的正式倒装条件句，表示若不是……（对现在或一般情况的假设）。然而此处语境指过去已发生的事，所以主句用 would not have been reached（过去虚拟被动式）。","subSkill":"inverted_conditionals_had_were_should"},{"type":"reorder","instruction":"将以下词语排列成正确的混合条件句，描述：他年轻时没有移民，所以现在仍然住在家乡。","words":["now,","emigrated,","he","not","be","living","Had","he","would","here","be"],"correctSentence":"Had he emigrated, he would not be living here now.","explanation":"混合条件句倒装形式：Had + 主语 + 过去分词（条件从句，指过去），would + 动词原形（主句，指现在结果）。Had 提前取代 if，是正式倒装写法。","subSkill":"mixed_conditionals_past_to_present"},{"type":"fill","instruction":"根据括号中的提示，用一个含 but for 的隐含条件句改写下面的句子，保持意思不变。原句：If the lead engineer had not identified the flaw in time, the entire structure would have collapsed.","sentence":"But for the lead engineer's timely ___ of the flaw, the entire structure would have collapsed.","acceptableAnswers":["identification"],"explanation":"but for + 名词短语 是改写 if it had not been for 结构的正式方式。将动词 identified 转化为名词 identification，使句子结构更简洁，适合正式书面语。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"type":"error","instruction":"下列正式书面句子中有一处错误，找出并改正。","words":["Should","the","committee","to","reject","the","proposal,","a","new","round","of","negotiations","will","begin."],"errorIndex":3,"correction":"reject","explanation":"Should 用于倒装条件句时，结构为 Should + 主语 + 动词原形，不需要加 to。to reject 是不定式形式，不符合此结构。正确形式为 Should the committee reject。","subSkill":"inverted_conditionals_had_were_should"},{"type":"choice","instruction":"选择最合适的选项，完成这个正式语境中含 suppose 的条件句。","sentence":"Suppose the initial report ___ accurate — the entire hypothesis would need to be reconsidered.","options":["were not","had not been","was not being","would not be"],"correctIndex":1,"explanation":"suppose 此处引导虚拟条件句。根据语境（初步报告已经存在，现在回顾），条件指的是过去的假设，应用过去完成时 had not been，而非现在虚拟的 were not。","subSkill":"conditional_like_structures_suppose_provided"},{"type":"reorder","instruction":"将以下词语排列成一个正式的倒装条件句，表示：如果有任何投资者提出异议，委员会将重新审查该条款。","words":["any","Should","investor","raise","an","objection,","the","committee","will","review","clause","the"],"correctSentence":"Should any investor raise an objection, the committee will review the clause.","explanation":"Should + 主语 + 动词原形 是正式书面语中表示将来可能条件的倒装结构，语气比 if 更正式。主句用一般将来时表示真实可能的结果。","subSkill":"conditionals_in_formal_writing"},{"type":"fill","instruction":"用括号中动词的正确形式填空，完成混合条件句。注意条件发生在过去，结果影响现在。","sentence":"If the founders (choose) ___ a different business model back in 2005, this company (not, be) ___ a global leader today.","acceptableAnswers":["had chosen","would not be"],"explanation":"混合条件句：条件从句指2005年未发生的选择，用过去完成时 had chosen；主句指对今天现状的影响，用 would not be（would + 否定 + 原形）。两个时间层面的结合是混合条件句的标志。","subSkill":"mixed_conditionals_past_to_present"},{"type":"error","instruction":"下列句子中有一处错误，找出并改正。注意：这是一个含 provided 的正式条件句。","words":["Provided","that","all","parties","would","sign","the","agreement,","the","terms","will","become","binding","immediately."],"errorIndex":4,"correction":"sign","explanation":"provided that 引导条件从句时，从句动词使用一般现在时（sign）表示将来条件，而非 would sign。英语中条件从句不使用 would，主句才使用 will 表示将来结果。","subSkill":"conditional_like_structures_suppose_provided"}]}},"5":{"levels":{"1":[{"type":"choice","options":["many","much","very","quite"],"sentence":"The museum displayed eighty ancient artifacts, ___ of which dated back to the Bronze Age.","subSkill":"non_defining_relative_with_quantifiers_many_of_which","explanation":"'many of which' 是含量词非限制性关系从句的标准结构，量词 many 用于修饰可数名词复数 artifacts。much 用于不可数名词，very 和 quite 是副词，不能用于此结构。","instruction":"选择正确选项，完成含量词的非限制性关系从句。","correctIndex":0},{"type":"choice","options":["that","which","what","it"],"sentence":"The director cancelled the afternoon session, ___ disappointed many attendees.","subSkill":"sentential_relative_which_referring_to_clause","explanation":"此处 which 指代前面整件事（会议被取消），是句子性关系代词用法。that 不能用于非限制性从句，what 不能引导关系从句，it 不是关系代词。","instruction":"选择正确选项，完成句子性关系which的句子。","correctIndex":1},{"type":"choice","options":["reviewed","reviewing","that reviewing","which reviewing"],"sentence":"The documents ___ by the committee last week have now been published online.","subSkill":"reduced_relative_clauses_with_participles","explanation":"缩减关系从句省略了 'that were'，保留过去分词 'reviewed' 表示被动含义（文件被审查）。'reviewing' 是现在分词，表示主动进行中，语义不符。","instruction":"选择正确的缩减关系从句形式。","correctIndex":0},{"type":"choice","options":["Whoever","Whatever","Whichever","However"],"sentence":"___ arrives first should set up the equipment.","subSkill":"relative_clauses_with_whoever_whatever","explanation":"'Whoever' 相当于 'anyone who'，指代人，在此作句子主语，引导名词性关系从句。Whatever 指事物，Whichever 表示在特定范围内选择，However 引导让步状语从句。","instruction":"选择正确选项，完成 whoever 引导的从句。","correctIndex":0},{"type":"choice","options":["on","at","by","of"],"sentence":"This is the foundation ___ which the entire theory rests.","subSkill":"preposition_fronting_in_relative_clauses","explanation":"'rest on something' 是固定搭配，表示某事建立在某个基础上。介词前置时，on 移至 which 之前，构成 'on which the theory rests'，是正式书面语的标准结构。","instruction":"选择正确选项，完成介词前置的关系从句。","correctIndex":0},{"type":"choice","options":["of whom","of which","of them","of those"],"sentence":"The professor supervised thirty graduate students, the majority ___ were working on climate-related topics.","subSkill":"non_defining_relative_with_quantifiers_many_of_which","explanation":"'the majority of whom' 中 whom 指代前面的人（graduate students），作介词 of 的宾语，是正式书面语中含量词非限制性关系从句的正确形式。of which 用于物，of them / of those 不能引导关系从句。","instruction":"选择正确的量词短语，完成非限制性关系从句。","correctIndex":0},{"type":"choice","options":["whatever","whoever","whichever","wherever"],"sentence":"The committee will consider ___ proposal receives the highest public approval rating.","subSkill":"relative_clauses_with_whoever_whatever","explanation":"'whichever' 表示在若干特定方案中选择其一（从多个提案中选），修饰名词 proposal。whatever 泛指任何事物，whoever 指人，wherever 指地点。","instruction":"选择正确选项，完成 whatever 引导的从句。","correctIndex":2},{"type":"choice","options":["which","that","what","this"],"sentence":"She passed the advanced examination on her first attempt, ___ her colleagues found remarkable.","subSkill":"sentential_relative_which_referring_to_clause","explanation":"which 在此指代前面整件事（她一次通过考试），是句子性关系代词。非限制性关系从句不可用 that，what 不能引导这类从句，this 是指示代词而非关系代词。","instruction":"选择正确选项，完成句子性关系从句。","correctIndex":0}],"2":[{"type":"choice","options":["on which","which on","that","on that"],"sentence":"The methodology ___ the researchers relied produced consistent results across all trials.","subSkill":"preposition_fronting_in_relative_clauses","explanation":"'rely on' 是固定搭配，正式书面语中将介词 on 前置于关系代词 which 之前，构成 'on which the researchers relied'，使从句结构完整且正式。that 不能与介词前置连用。","instruction":"选择正确的介词前置形式，替换句中的非正式表达。","correctIndex":0},{"type":"fill","sentence":"The children (participate) ___ in the summer programme showed significant improvement in literacy skills.","subSkill":"reduced_relative_clauses_with_participles","explanation":"缩减关系从句省略了 'who were'，保留现在分词 'participating' 表示主动进行的动作（孩子们正在参与项目）。过去分词 'participated' 表被动，语义不符。","instruction":"用括号中的词填写缩减关系从句的正确分词形式。","acceptableAnswers":["participating"]},{"type":"choice","options":["fewer than half","less than half","hardly","scarcely"],"sentence":"The organisation received two hundred applications, ___ of which met the minimum eligibility criteria.","subSkill":"non_defining_relative_with_quantifiers_many_of_which","explanation":"'fewer than half of which' 是含量词非限制性关系从句，量词短语 'fewer than half' 修饰可数名词 applications。less than 用于不可数名词或数字，hardly 和 scarcely 是副词，不能作量词。","instruction":"选择正确选项，完成含量词的非限制性关系从句。","correctIndex":0},{"type":"fill","sentence":"___ is responsible for the project must submit weekly progress reports.","subSkill":"relative_clauses_with_whoever_whatever","explanation":"'Whoever' 相当于 'anyone who'，引导名词性关系从句作句子主语，表示任何担任该职责的人，不限定具体对象。Whatever 指事物，不指人，语义不符。","instruction":"用适当的关系词填空，使句子表达'无论谁负责这个项目，都必须提交每周报告'。","acceptableAnswers":["Whoever"]},{"type":"fill","sentence":"The government postponed the vote indefinitely. (This fact) ___ angered opposition leaders across all parties.","subSkill":"sentential_relative_which_referring_to_clause","explanation":"句子性关系 which 指代前面的整件事（政府无限期推迟投票），取代 'This fact' 将两个独立句子连接为一个带非限制性关系从句的句子，是书面语中常见的衔接手段。","instruction":"改写句子，用句子性关系which替换括号中的表达，保持意思不变。填入which所在的从句动词。","acceptableAnswers":["which"]},{"type":"choice","options":["The concept which the debate centred around remains unresolved.","The concept around which the debate centred remains unresolved.","The concept that around the debate centred remains unresolved.","The concept which around the debate centred remains unresolved."],"sentence":"___","subSkill":"preposition_fronting_in_relative_clauses","explanation":"正式书面语中，介词 'around' 应前置于关系代词 which 之前，构成 'around which the debate centred'。将介词悬挂在句末（centred around）是非正式用法；that 不与前置介词连用。","instruction":"以下哪个句子正确使用了介词前置的关系从句？","correctIndex":1},{"type":"fill","sentence":"The bridge (build) ___ in the nineteenth century still carries heavy traffic today.","subSkill":"reduced_relative_clauses_with_participles","explanation":"桥梁是被建造的，因此使用过去分词 'built' 表示被动含义，省略了 'that was'。现在分词 'building' 表示主动进行，语义完全不符。","instruction":"用括号中的词填写缩减关系从句的正确分词形式。","acceptableAnswers":["built"]},{"type":"fill","sentence":"The company hired fifty contractors, none of ___ held the required safety certification.","subSkill":"non_defining_relative_with_quantifiers_many_of_which","explanation":"'none of whom' 中，whom 指代前面的人（contractors），是含量词非限制性关系从句的正式形式。'none of which' 用于物，'none of them' 不能引导关系从句。","instruction":"用适当的量词短语和关系代词完成从句。句意：该公司雇用了五十名承包商，其中没有一人拥有所需的安全证书。","acceptableAnswers":["whom"]}],"3":[{"type":"fill","sentence":"The researcher identified several variables that the final outcome depended on. → The researcher identified several variables ___ ___ the final outcome depended.","subSkill":"preposition_fronting_in_relative_clauses","explanation":"'depend on' 是固定搭配，将介词 on 前置于关系代词 which 之前，构成正式书面语结构 'on which the final outcome depended'，避免了将介词悬挂在句末的非正式用法。","instruction":"改写句子，用介词前置的关系从句替换非正式表达，保持意思不变。填入介词和关系代词。","acceptableAnswers":["on","which"]},{"type":"reorder","words":["The","charity","received","donations","from","three","hundred","supporters,","many","of","whom","had","contributed","anonymously"],"subSkill":"non_defining_relative_with_quantifiers_many_of_which","explanation":"含量词非限制性关系从句的结构为：主句 + 逗号 + 量词（many）+ of + whom/which + 从句谓语。whom 指代人（supporters），置于 of 之后作介词宾语，整个短语作从句主语。","instruction":"将以下词语排列成正确的句子，构成含量词的非限制性关系从句。","correctSentence":"The charity received donations from three hundred supporters, many of whom had contributed anonymously."},{"type":"fill","sentence":"The lead scientist retracted the published paper entirely. This decision ___ considerable controversy within the academic community.","subSkill":"sentential_relative_which_referring_to_clause","explanation":"句子性关系 which 指代前面整件事（首席科学家完全撤回已发表的论文），合并后为 'The lead scientist retracted the published paper entirely, which caused considerable controversy...'。which 引导非限制性关系从句，对前面整个命题进行评论。","instruction":"将两个句子合并为一个句子，用句子性关系which连接，保持意思不变。填入which所引导的从句的谓语动词。","acceptableAnswers":["caused","sparked","generated","provoked","prompted"]},{"type":"reorder","words":["The","principles","on","which","the","legal","system","is","founded","have","remained","largely","unchanged","for","centuries"],"subSkill":"preposition_fronting_in_relative_clauses","explanation":"正式书面语中，'founded on' 的介词 on 前置于关系代词 which，构成 'the principles on which the legal system is founded'。主句主语是 'The principles'，谓语是 'have remained'，关系从句作后置定语修饰 principles。","instruction":"将以下词语排列成正确的句子，构成介词前置的关系从句。","correctSentence":"The principles on which the legal system is founded have remained largely unchanged for centuries."},{"type":"fill","sentence":"Researchers who are studying the long-term effects of the policy will present their findings next month. → Researchers ___ the long-term effects of the policy will present their findings next month.","subSkill":"reduced_relative_clauses_with_participles","explanation":"缩减关系从句省略 'who are'，保留现在分词 'studying' 表示主动进行的动作。原句主动语态（研究人员正在研究）对应现在分词，而非过去分词（过去分词表被动）。","instruction":"改写句子，用缩减关系从句（分词短语）替换画线的关系从句，使表达更简洁。","acceptableAnswers":["studying"]},{"type":"reorder","words":["Whatever","obstacles","the","team","encounters,","they","must","document","every","detail","systematically"],"subSkill":"relative_clauses_with_whoever_whatever","explanation":"'Whatever obstacles' 中 whatever 修饰名词 obstacles，引导让步性名词从句（相当于 no matter what obstacles）。从句置于句首时后跟逗号，主句陈述结果或要求。","instruction":"将以下词语排列成正确的句子，构成 whoever/whatever 引导的名词性关系从句。","correctSentence":"Whatever obstacles the team encounters, they must document every detail systematically."},{"type":"fill","sentence":"The university accepted sixty international students. The majority of them came from East Asian countries. → The university accepted sixty international students, the majority of ___ came from East Asian countries.","subSkill":"non_defining_relative_with_quantifiers_many_of_which","explanation":"'the majority of whom' 是含量词非限制性关系从句，whom 指代前面的人（international students），作介词 of 的宾语，整个短语 'the majority of whom' 作从句的主语，代替 'the majority of them'。","instruction":"用括号中提示的结构改写句子，保持意思不变。填入两个空格（量词 + 关系代词）。","acceptableAnswers":["whom"]},{"type":"reorder","words":["The","report","compiled","by","independent","auditors","revealed","serious","irregularities,","which","led","to","an","immediate","government","inquiry"],"subSkill":"sentential_relative_which_referring_to_clause","explanation":"'compiled by independent auditors' 是缩减关系从句（省略了 'that was'），作后置定语修饰 report；'which led to an immediate government inquiry' 是句子性关系从句，which 指代前面整件事（报告揭露了严重违规行为），说明其导致的后果。","instruction":"将以下词语排列成正确的句子，综合运用缩减关系从句和句子性关系which。","correctSentence":"The report compiled by independent auditors revealed serious irregularities, which led to an immediate government inquiry."}],"4":[{"type":"choice","options":["much","many","most","plenty"],"sentence":"The company hired twenty new engineers, ___ of whom had PhDs in robotics.","subSkill":"non_defining_relative_with_quantifiers_many_of_which","explanation":"many of whom 是含量词的非限制性关系从句的固定结构，用于指代前面提到的复数名词（twenty new engineers）中的一部分。much 修饰不可数名词，most of whom 意为\"大多数\"语义不符，plenty 不与 of whom 搭配。","instruction":"选择正确的选项，完成含量词的非限制性关系从句。","correctIndex":1},{"type":"choice","options":["that","which","whom","what"],"sentence":"The professor delivered a lecture on climate change, during ___ several students fell asleep.","subSkill":"preposition_fronting_in_relative_clauses","explanation":"介词前置结构要求使用 which（指代事物），不能使用 that。during which 意为\"在此期间\"，指代前面的 lecture。whom 指人，what 不能用在介词前置的关系从句中。","instruction":"选择正确的选项，完成介词前置的关系从句。","correctIndex":1},{"type":"choice","options":["that","what","which","it"],"sentence":"The factory reduced its carbon emissions by forty percent last year, ___ impressed the environmental regulators enormously.","subSkill":"sentential_relative_which_referring_to_clause","explanation":"当关系词指代前面整个句子所描述的事实或情况时，必须使用 which，而不是 that 或 what。这里 which 代指\"工厂去年减少了40%的碳排放\"这一整件事。","instruction":"选择正确的选项，使 which 指代整个句子内容。","correctIndex":2},{"type":"choice","options":["compiling","compiled","having compiled","to compile"],"sentence":"The report ___ by the independent auditors revealed serious financial irregularities.","subSkill":"reduced_relative_clauses_with_participles","explanation":"简化关系从句中，被动含义用过去分词表示。report 和 compile 之间是被动关系（报告被编写），所以用 compiled，相当于 which was compiled by the independent auditors。","instruction":"选择正确的分词形式，完成简化关系从句。","correctIndex":1},{"type":"error","words":["The","museum","owns","five","hundred","paintings,","much","of","which","have","never","been","publicly","displayed."],"subSkill":"non_defining_relative_with_quantifiers_many_of_which","correction":"many","errorIndex":6,"explanation":"paintings 是可数复数名词，表示其中一部分时应使用 many of which，而非 much of which。much 修饰不可数名词，many 修饰可数名词。","instruction":"下列句子中有一个语法错误，找出并改正。"},{"type":"error","words":["The","conference","lasted","three","days,","throughout","that","delegates","debated","global","trade","policy."],"subSkill":"preposition_fronting_in_relative_clauses","correction":"which","errorIndex":6,"explanation":"介词前置的关系从句中，介词后必须跟 which（指代事物），不能使用 that。throughout which 意为\"在整个会议期间\"，是正确的介词前置结构。","instruction":"下列句子中有一个语法错误，找出并改正。"},{"type":"error","words":["She","passed","all","her","exams","on","the","first","attempt,","that","surprised","even","her","most","optimistic","teachers."],"subSkill":"sentential_relative_which_referring_to_clause","correction":"which","errorIndex":9,"explanation":"当关系词指代前面整个句子的内容（她一次通过所有考试这件事）时，必须使用 which，不能使用 that。that 不能引导非限制性关系从句。","instruction":"下列句子中有一个语法错误，找出并改正。"},{"type":"fill","sentence":"The scientists (conduct) ___ the trial published their findings in a leading medical journal.","subSkill":"reduced_relative_clauses_with_participles","explanation":"简化关系从句中，主动、进行含义用现在分词表示。scientists 和 conduct 是主动关系（科学家们正在进行试验），所以用 conducting，相当于 who were conducting the trial。","instruction":"用括号中动词的适当分词形式填空，完成简化关系从句。","acceptableAnswers":["conducting"]}],"5":[{"type":"fill","sentence":"The negotiation process, at ___ both parties expressed frustration, eventually produced a binding agreement.","subSkill":"preposition_fronting_in_relative_clauses","explanation":"介词前置结构 at which 用于指代事物（the negotiation process），表示\"在谈判过程中\"。介词后不能使用 that 或 what，必须用 which。","instruction":"用适当的关系词填空，完成介词前置的关系从句。","acceptableAnswers":["which"]},{"type":"fill","sentence":"The university admitted three hundred international students, a small number ___ came from sub-Saharan Africa.","subSkill":"non_defining_relative_with_quantifiers_many_of_which","explanation":"含量词的非限制性关系从句结构为\"量词 + of whom/which\"，指代前面提到的人时用 of whom。a small number of whom 等于 a small number of them，将两个句子合并为一个非限制性从句。","instruction":"改写下列句子，保持意思不变，使用含量词的非限制性关系从句填入空白处。原句：The university admitted three hundred international students. A small number of them came from sub-Saharan Africa.","acceptableAnswers":["of whom"]},{"type":"reorder","words":["The","government","postponed","the","election,","which","angered","opposition","leaders","considerably."],"subSkill":"sentential_relative_which_referring_to_clause","explanation":"sentential relative which 放在逗号之后，指代前面整个句子的内容（政府推迟选举这件事），后接主句谓语 angered。which 不能替换为 that，且必须置于逗号后。","instruction":"将下列词语排列成正确的句子，注意 which 指代整句内容的用法。","correctSentence":"The government postponed the election, which angered opposition leaders considerably."},{"type":"error","words":["Whoever","submits","the","most","compelling","proposal","will","receives","the","research","grant."],"subSkill":"relative_clauses_with_whoever_whatever","correction":"receive","errorIndex":7,"explanation":"whoever 引导名词性关系从句，作主句主语，主句谓语动词应用原形 receive，而非第三人称单数形式 receives（助动词 will 后跟动词原形）。","instruction":"下列句子中有一个语法错误，找出并改正。"},{"type":"fill","sentence":"___ decision the board reaches tomorrow will have lasting consequences for the entire organisation.","subSkill":"relative_clauses_with_whoever_whatever","explanation":"whatever 修饰名词 decision，引导让步性名词关系从句，意为\"无论做出什么决定\"。whoever 指人，不能修饰名词 decision。whatever 在此作限定词，相当于 no matter what。","instruction":"用 whoever 或 whatever 填空，完成关系从句。","acceptableAnswers":["Whatever"]},{"type":"reorder","words":["The","documents","leaked","to","the","press","contained","details","about","the","merger."],"subSkill":"reduced_relative_clauses_with_participles","explanation":"leaked to the press 是简化关系从句（相当于 which were leaked to the press），作后置定语修饰 documents，用过去分词表示被动含义。主句谓语为 contained。","instruction":"将下列词语排列成正确的句子，注意介词前置及简化关系从句的综合运用。","correctSentence":"The documents leaked to the press contained details about the merger."},{"type":"fill","sentence":"The crisis, during ___ the government introduced emergency legislation, lasted six months.","subSkill":"preposition_fronting_in_relative_clauses","explanation":"将两个句子合并时，介词 during 前置于关系代词 which 之前，构成 during which 结构，指代 the crisis。介词前置是书面正式英语中的常见结构，比将介词置于从句末尾更正式。","instruction":"改写下列句子，保持意思不变，使用介词前置的关系从句填入空白处。原句：The crisis lasted six months. During the crisis, the government introduced emergency legislation.","acceptableAnswers":["which"]},{"type":"error","words":["The","archaeologists","discovered","over","two","hundred","artefacts,","several","of","which","were","dating","back","to","the","Bronze","Age."],"subSkill":"non_defining_relative_with_quantifiers_many_of_which","correction":"dated","errorIndex":11,"explanation":"several of which 引导非限制性定语从句，从句中应使用一般过去时 dated back to（追溯至）表示状态，而非进行时 were dating back to。date back to 通常不用进行时，因为它描述的是持续存在的历史属性而非正在进行的动作。","instruction":"下列句子中有一个语法错误，找出并改正。"}]},"mission":{"title":"Report: International Summit on Urban Sustainability","scenario":"峰会共吸引来自45个国家的代表参会，提交了120份政策提案，其中许多包含创新的碳减排方案。峰会最终通过了一项全球协议，这一成果令所有参与方感到振奋。请在报告中运用本单元所学的关系从句结构，描述峰会的规模、成果及其意义。","scaffolds":[{"hint":"在逗号后用含量词的非限制性关系从句，说明其中多少个国家的代表提交了提案（many of whom / several of whom）","prefix":"The summit attracted delegates from forty-five countries,","suffix":"had submitted detailed carbon reduction proposals.","example":"The summit attracted delegates from forty-five countries, many of whom had submitted detailed carbon reduction proposals.","grammarCheck":"non_defining_relative_with_quantifiers_many_of_which"},{"hint":"用句子性关系which指代前面整件事（通过协议这一成果），描述它带来的影响（which generated / which instilled）","prefix":"The conference ultimately adopted a binding global agreement,","suffix":"a renewed sense of collective responsibility among all participating nations.","example":"The conference ultimately adopted a binding global agreement, which generated a renewed sense of collective responsibility among all participating nations.","grammarCheck":"sentential_relative_which_referring_to_clause"},{"hint":"用 whoever 引导名词性关系从句作主语，表示任何满足条件的参与者（Whoever demonstrates... / Whoever presents...）","prefix":"","suffix":"will be invited to co-author the official follow-up policy framework.","example":"Whoever demonstrates measurable progress toward the agreed targets within the first review period will be invited to co-author the official follow-up policy framework.","grammarCheck":"relative_clauses_with_whoever_whatever"}],"description":"你是一位受雇于国际环保组织的英语报告撰写员。请用正式书面英语撰写一份关于城市可持续发展峰会的简短报告段落。报告需要准确、客观，并体现C1级高级关系从句的运用。","grammarType":"non_defining_relative_with_quantifiers_many_of_which"},"discover":{"tip":"本单元聚焦五种C1级高级关系从句结构，它们在书面语中频繁出现，需要仔细区分：\n\n【1】含量词的非限制性从句（many/some/several/none/the majority + of which）\n用于在非限制性从句中对前面名词的一部分进行说明。量词置于 of which 之前，整体作从句主语或宾语。\n✔ The team recruited twenty volunteers, none of whom had prior experience.\n✘ The team recruited twenty volunteers, whom none had prior experience. （语序错误）\n\n【2】介词前置（preposition + which/whom）\n正式书面语中，介词置于关系代词之前，而非悬挂在句末。\n✔ This is the sensor the data from which proved crucial. / ...from which the data proved crucial.\n✘ This is the sensor which the data from proved crucial. （介词位置导致结构混乱）\n\n【3】句子性关系which（sentential relative which）\nwhich 指代前面整个小句（命题），而非某个名词。常见于逗号之后。\n✔ She finished the report early, which surprised everyone. （which = 她提前完成报告这件事）\n注意：此结构不可用 that 替换，也不可将 which 误解为指代紧邻的名词。\n\n【4】缩减关系从句（participial reduction）\n当关系从句含有 be + 分词时，可省略关系代词和 be 动词，保留分词。\n主动含义用现在分词：delegates attending the conference（= who were attending）\n被动含义用过去分词：specimens collected last year（= that were collected）\n\n【5】whoever / whatever 引导的关系从句\nwhoever = anyone who，whatever = anything that，引导名词从句，在句中作主语或宾语。\n✔ Whoever submits the proposal first will be considered.\n✘ Whoever will submit the proposal first will be considered. （whoever 从句内部已含将来含义，不再加 will）","story":{"text":"Dr. Elena Vasquez led a marine research expedition to the Pacific Ocean, the findings of which transformed our understanding of deep-sea ecosystems. Her team collected over three hundred specimens, many of which had never been documented before. The expedition relied on a network of underwater sensors, the data from which revealed startling temperature anomalies. Elena presented her conclusions at an international conference, which impressed the scientific community enormously. The conference attracted delegates from forty countries, several of which immediately pledged funding for follow-up research. Elena announced that whoever wished to join the next expedition would need advanced diving certification. She also stated that whatever challenges the team encountered, they would document everything meticulously. The specimens collected during the voyage, now preserved in a Copenhagen laboratory, include creatures resembling translucent jellyfish and organisms bearing luminescent markings unlike anything previously recorded. Elena, known for her meticulous methodology, insists that the ocean still holds secrets the scope of which science has barely begun to grasp.","title":"The Research Expedition","highlights":["the findings of which","many of which","the data from which","which impressed","several of which","whoever","whatever","specimens collected","known for"]},"questions":[{"options":["The research team members","The three hundred specimens","The deep-sea ecosystems","The underwater sensors"],"question":"In the sentence 'Her team collected over three hundred specimens, many of which had never been documented before,' what does 'many of which' refer to?","explanation":"'many of which' 是含量词的非限制性关系从句，其中 which 指代前面的名词 'specimens'，表示这些标本中的许多从未被记录过。量词 many 限定了 which 所指代的数量范围。","correctIndex":1},{"options":["The international conference only","The scientific community","The entire act of Elena presenting her conclusions","Elena herself"],"question":"In the sentence 'Elena presented her conclusions at an international conference, which impressed the scientific community enormously,' what does 'which' refer to?","explanation":"'which' 在此处是句子性关系代词（sentential relative which），指代的不是某个名词，而是前面整个命题——Elena在会议上展示结论这件事本身——令科学界留下了深刻印象。","correctIndex":2},{"options":["The specimens which were collected during the voyage are now in Copenhagen.","The specimens collected during the voyage are now in Copenhagen.","The specimens that collecting during the voyage are now in Copenhagen.","The specimens who were collected during the voyage are now in Copenhagen."],"question":"Which sentence correctly uses a reduced relative clause with a participle?","explanation":"缩减关系从句（reduced relative clause）省略了关系代词和 be 动词，直接用过去分词 'collected' 修饰名词。'specimens collected' = 'specimens that were collected'，是C1级常见的简洁书面表达方式。","correctIndex":1}]}},"6":{"discover":{"story":{"title":"The Last Expedition","text":"The research team arrived at the base camp exhausted, having trekked for three days through dense jungle. Their equipment secured to the sledges and their supplies carefully rationed, they prepared for the final ascent. The lead scientist, driven by years of dedication, refused to abandon the mission despite the worsening weather. Checking the instruments one final time, she confirmed that the readings were stable, thus giving the team confidence to proceed. Having reviewed all the data overnight, the scientists decided that conditions were acceptable. The younger researchers, their notebooks filled with observations, stood ready to document every detail. Weather permitting, they planned to reach the summit by noon. Battered by strong winds but undeterred by the cold, the team pushed forward, eventually discovering a geological formation that would reshape decades of theory. The discovery made, they descended carefully, their faces showing both relief and triumph.","highlights":["having trekked","secured","driven by","Checking","thus giving","Having reviewed","their notebooks filled","Weather permitting","Battered by","The discovery made","their faces showing"]},"questions":[{"question":"\"Having trekked for three days\" 表达的是什么逻辑关系？","options":["与主句动作同时发生","发生在主句动作之前，是主句的原因或背景","表示假设条件","表示让步关系"],"correctIndex":1,"explanation":"完成式分词短语 having + 过去分词 表示该动作发生在主句动作之前，常用来说明原因或先发生的背景事件。团队到达时精疲力竭，正是因为之前已经跋涉了三天。"},{"question":"\"Their notebooks filled with observations\" 属于哪种结构？","options":["普通过去分词短语修饰主语","独立主格结构（absolute participial construction）","悬垂分词（dangling participle）","完成式分词短语"],"correctIndex":1,"explanation":"独立主格结构由\"名词/代词 + 分词\"构成，其逻辑主语（their notebooks）与主句主语（the younger researchers）不同，整个短语作状语，是书面语中压缩信息的典型方式。"},{"question":"\"Weather permitting\" 在句中表达什么含义？","options":["天气很好，所以他们出发了","假设天气允许的话（条件）","尽管天气不好（让步）","天气变好之后（时间）"],"correctIndex":1,"explanation":"\"Weather permitting\" 是固定的独立主格结构，逻辑主语是 weather，分词是 permitting，整体表示\"如果天气允许\"，属于条件状语，相当于 if weather permits。"}],"tip":"【分词短语与独立主格结构：核心对比与常见错误】\n\n目标结构共五类：\n1. 现在分词短语（原因/结果）：逻辑主语必须与主句主语一致。例：Checking the data, she found an error. （她检查数据时发现了错误。）结果用 thus/thereby + 现在分词：She worked hard, thus earning a promotion.\n2. 过去分词短语（条件/让步）：被动含义。例：Battered by winds, the team pressed on.（尽管被狂风吹打，团队仍前行。）Given more time, he would have finished.（如果有更多时间……）\n3. 完成式分词 having done：强调先于主句完成。例：Having reviewed the data, they made a decision.（已经审阅完数据之后，他们做出了决定。）\n4. 独立主格结构（名词 + 分词）：逻辑主语与主句主语不同。例：The mission complete, the crew returned.（任务完成后，团队返回。）Their supplies rationed, they set off.（物资配给好之后，他们出发了。）\n5. 固定独立主格：Weather permitting / All things considered / Time allowing 等。\n\n常见错误：\n- 悬垂分词（dangling participle）：分词的逻辑主语与主句主语不一致。错误：Walking down the street, the rain started.（雨不能走路）正确：Walking down the street, she got caught in the rain.\n- 混淆 having done 与 being done：having done 强调动作先于主句完成；being done 表示与主句同时进行的被动动作。"},"mission":{"title":"The Report That Matters","description":"你是一家国际智库的研究员，需要为即将召开的气候峰会撰写一份简短的书面报告摘要。摘要要求语言正式、简洁，信息密度高，需使用分词短语与独立主格结构来压缩背景信息、原因和结果，避免悬垂分词。","scenario":"峰会将于下周举行。你的摘要需涵盖：研究团队已完成的工作、数据指向的趋势、以及对政策制定者的建议。请用3-4句书面英语完成摘要，每句至少使用一种目标语法结构。","grammarType":"absolute_participial_constructions","scaffolds":[{"prefix":"Having analysed data from over 50 countries,","suffix":"","hint":"用完成式分词短语开头，说明研究团队在提出结论之前已完成的工作。","grammarCheck":"perfect_participle_having_done","example":"Having analysed data from over 50 countries, the team identified a consistent pattern of rising temperatures."},{"prefix":"","suffix":", thus placing unprecedented pressure on existing policy frameworks.","hint":"用现在分词短语（thus + 现在分词）结尾，表达前文趋势所带来的结果。","grammarCheck":"present_participle_clauses_for_result_reason","example":"The findings confirmed a 1.8-degree increase over the past decade, thus placing unprecedented pressure on existing policy frameworks."},{"prefix":"All available evidence considered,","suffix":"","hint":"用固定独立主格结构开头，引出基于全面证据的政策建议，注意后面主句的主语必须是做出建议的行为者（如 the report / the authors）。","grammarCheck":"absolute_participial_constructions","example":"All available evidence considered, the authors recommend an immediate reduction in carbon emissions targets at the national level."}]},"levels":{"1":[{"type":"choice","instruction":"选择正确的分词短语，完成句子。注意分词的逻辑主语。","sentence":"___ the report carefully, the manager approved the proposal.","options":["Having read","Having been read","Read","Being reading"],"correctIndex":0,"explanation":"主句主语 the manager 主动阅读了报告，且此动作先于批准提案，因此用完成式主动分词 having read。having been read 表被动，与语义不符。","subSkill":"perfect_participle_having_done"},{"type":"choice","instruction":"选择正确的选项，使句子表达让步或条件关系。","sentence":"___ by the economic crisis, many small businesses were forced to close.","options":["Affecting","Having affected","Affected","Being affect"],"correctIndex":2,"explanation":"主语 many small businesses 是被影响的对象（被动关系），且表示让步/原因背景，应用过去分词 affected（等同于 although they were affected by...）。","subSkill":"past_participle_clauses_for_condition_concession"},{"type":"choice","instruction":"判断哪个句子使用了正确的独立主格结构。","sentence":"Which sentence is grammatically correct?","options":["Their work finishing, the volunteers went home.","Their work finished, the volunteers went home.","Having finished their work, the volunteers went home to.","Finishing their work, the volunteers went home."],"correctIndex":1,"explanation":"独立主格结构中，work 是被完成的对象，应用过去分词 finished（their work finished = after their work was finished）。选项A中 finishing 语义不符（工作不能自己完成自己）。选项C有多余的 to。选项D的分词主语应与主句主语一致，此处可以，但独立主格更准确地表达work已完成这一背景。","subSkill":"absolute_participial_constructions"},{"type":"choice","instruction":"选择正确的现在分词短语，表达结果关系。","sentence":"The new bridge was completed ahead of schedule, ___ the city government considerable praise.","options":["earned","thus earning","having earned","thus earned"],"correctIndex":1,"explanation":"thus/thereby + 现在分词 表示前句行为导致的结果。此处 thus earning 说明提前完工的结果是赢得了赞誉。过去分词 thus earned 语义上表被动，不符合逻辑（赞誉不能被挣走）。","subSkill":"present_participle_clauses_for_result_reason"},{"type":"choice","instruction":"找出含有悬垂分词错误的句子。","sentence":"Which sentence contains a dangling participle?","options":["Exhausted by the journey, the hikers rested by the river.","Having studied abroad, her perspective broadened significantly.","Battered by criticism, the author revised the manuscript.","Having completed the survey, the researchers published their findings."],"correctIndex":1,"explanation":"选项B中，分词短语 having studied abroad 的逻辑主语应是句子主语，但主句主语是 her perspective（视野），视野不能出国留学。正确写法：Having studied abroad, she broadened her perspective significantly.","subSkill":"dangling_participle_avoidance"},{"type":"choice","instruction":"选择最能准确表达\"在所有因素都被考虑之后\"这一含义的结构。","sentence":"___, the committee decided to postpone the vote.","options":["All factors were considered","All factors considering","All factors considered","Having considered all factors"],"correctIndex":2,"explanation":"all factors considered 是固定独立主格结构（= after all factors had been considered），因素是被考虑的，用过去分词 considered。选项D也语法正确但逻辑主语变为主句的 the committee，两种结构含义略有不同，独立主格更书面、更简洁。","subSkill":"absolute_participial_constructions"},{"type":"choice","instruction":"选择正确的完成式分词，填入空格。","sentence":"___ the consequences of failure, the engineers double-checked every calculation.","options":["Knowing","Having known","Known","Being known"],"correctIndex":1,"explanation":"工程师了解后果这一认知先于他们反复核查计算，因此用完成式分词 having known。若用 knowing，则表示了解与核查同时发生，弱化了先后关系。此处强调正是因为事先了解了后果，才采取了后续行动。","subSkill":"perfect_participle_having_done"},{"type":"choice","instruction":"选择正确的分词短语，表达条件含义。","sentence":"___ properly, this medication can significantly reduce recovery time.","options":["Using","Used","Having used","Being using"],"correctIndex":1,"explanation":"this medication 是被使用的对象（被动），且表示条件关系（= if it is used properly），应用过去分词 used。这是过去分词短语表条件的典型用法，常见于科学、医学书面文体。","subSkill":"past_participle_clauses_for_condition_concession"}],"2":[{"type":"choice","instruction":"选择最符合书面语规范、且逻辑正确的句子。","sentence":"Which sentence best uses a participial phrase to express reason?","options":["Because she had lived in Tokyo for a decade, understanding the culture was easy for her.","Having lived in Tokyo for a decade, she understood the culture deeply.","She lived in Tokyo for a decade, so the culture was understood by her.","Living in Tokyo, the culture had been understood by her for a decade."],"correctIndex":1,"explanation":"选项B使用完成式分词 having lived，逻辑主语与主句主语一致（she），且分词动作先于主句，简洁地表达了原因关系，符合书面语C1级要求。选项D的逻辑主语是 she，但主句主语变成了 the culture，造成悬垂分词。","subSkill":"perfect_participle_having_done"},{"type":"fill","instruction":"用括号内动词的正确分词形式填空，使句子表达结果关系（现在分词短语）。","sentence":"The company launched an aggressive marketing campaign, (attract) ___ thousands of new customers within weeks.","acceptableAnswers":["attracting"],"explanation":"thus/thereby 可省略，用现在分词 attracting 表示前一动作（发起营销活动）所产生的结果（吸引了数千名新客户）。主语 the company 是 attract 的逻辑主语，两者主动关系一致。","subSkill":"present_participle_clauses_for_result_reason"},{"type":"fill","instruction":"用括号内动词的正确完成式分词形式填空。","sentence":"(complete) ___ her doctoral research, Dr. Chen submitted the final thesis to the faculty board.","acceptableAnswers":["Having completed"],"explanation":"提交论文之前，博士研究已经完成，两个动作有明确的先后关系，因此用完成式分词 having completed。若只用 completing，则暗示两个动作同时进行，与语义不符。","subSkill":"perfect_participle_having_done"},{"type":"choice","instruction":"选择正确的独立主格结构，填入空格。","sentence":"___, the rescue team made one final attempt to locate the missing climbers.","options":["Daylight fading","Daylight was fading","Daylight faded","Daylight having fade"],"correctIndex":0,"explanation":"独立主格结构中，daylight 是逻辑主语，fading 表示与主句同时进行的状态（光线正在消逝），用现在分词。faded 也可以，但强调已经消逝完。此处光线正在消退而团队仍在努力，现在分词更符合语境。having fade 形式错误。","subSkill":"absolute_participial_constructions"},{"type":"fill","instruction":"改写句子，用过去分词短语替换从句，保持原意不变。将改写后的分词短语填入空格。","sentence":"Although he was discouraged by the negative reviews, Marcus continued to write every day. Rewrite the underlined part: ___ by the negative reviews, Marcus continued to write every day.","acceptableAnswers":["Discouraged"],"explanation":"although he was discouraged 表让步，可用过去分词短语 discouraged by... 替换，因为 Marcus 是被打击的对象（被动），且过去分词短语开头置于句首表让步。这是C1书面语中压缩让步状语从句的标准手法。","subSkill":"past_participle_clauses_for_condition_concession"},{"type":"choice","instruction":"找出以下选项中唯一没有悬垂分词错误的句子。","sentence":"Select the sentence WITHOUT a dangling participle error.","options":["Walking through the museum, the paintings seemed to come alive.","Having examined the evidence, the verdict was announced by the judge.","Frightened by the storm, the children hid under the blankets.","Arriving at the station, the train had already departed."],"correctIndex":2,"explanation":"选项C中，frightened 的逻辑主语是 the children，与主句主语一致，且 children 是被吓到的对象，用过去分词正确。选项A（paintings 不能走路）、B（verdict 不能检查证据）、D（speaker 不是火车）均为悬垂分词。","subSkill":"dangling_participle_avoidance"},{"type":"fill","instruction":"用括号内词语构建独立主格结构，填入空格（注意名词与分词的关系）。","sentence":"___ (the / negotiations / stall), both parties agreed to bring in a professional mediator.","acceptableAnswers":["The negotiations having stalled"],"explanation":"谈判陷入僵局发生在双方同意引入调解人之前，因此用完成式独立主格结构：the negotiations having stalled（逻辑主语 the negotiations + 完成式分词 having stalled）。这比 because the negotiations had stalled 更简洁，适合书面正式文体。","subSkill":"absolute_participial_constructions"},{"type":"fill","instruction":"改写以下句子，用 having done 结构替换时间从句，保持原意。填写分词短语部分。","sentence":"After she had spent three years in the field, the anthropologist returned to write her findings. Rewrite: ___ three years in the field, the anthropologist returned to write her findings.","acceptableAnswers":["Having spent"],"explanation":"after she had spent 表示先于主句完成的动作，可用 having spent 替换，使句子更紧凑。逻辑主语是 the anthropologist（她），与主句主语一致，动作为主动，故用完成式主动分词。","subSkill":"perfect_participle_having_done"}],"3":[{"type":"fill","instruction":"用括号中的词构建完整的独立主格结构，填入两个空格（每空一词或一组词）。","sentence":"___ (their / funding / cut) and ___ (their / key / researcher / resign), the laboratory was forced to suspend all ongoing trials.","acceptableAnswers":["Their funding cut","their key researcher having resigned"],"explanation":"第一个独立主格：funding 是被削减的对象，用过去分词 cut（their funding cut）。第二个：辞职发生在暂停试验之前，且 researcher 是主动辞职，用完成式独立主格 their key researcher having resigned，强调该动作在主句动作之前已发生。","subSkill":"absolute_participial_constructions"},{"type":"reorder","instruction":"将以下单词重新排列，组成一个使用完成式分词短语的正确句子。","words":["the","senator","having","served","three","consecutive","terms","announced","her","retirement"],"correctSentence":"Having served three consecutive terms, the senator announced her retirement.","explanation":"完成式分词短语 having served three consecutive terms 置于句首，逻辑主语为句子主语 the senator，表示在宣布退休之前已连任三届，该结构在书面语中代替 after she had served three consecutive terms，更简洁正式。","subSkill":"perfect_participle_having_done"},{"type":"fill","instruction":"改写句子：用现在分词短语表达结果，替换 and as a result 结构。保持原意，只填写分词短语部分（置于句末）。","sentence":"The documentary exposed widespread corruption in the industry, and as a result it prompted a government inquiry. Rewrite: The documentary exposed widespread corruption in the industry, ___ a government inquiry.","acceptableAnswers":["thereby prompting","thus prompting"],"explanation":"thereby/thus + 现在分词 将 and as a result it prompted 压缩为简洁的结果状语短语，逻辑主语是主句主语 the documentary，为主动关系，用现在分词 prompting。这是C1书面语中表达因果链的地道手法。","subSkill":"present_participle_clauses_for_result_reason"},{"type":"reorder","instruction":"将以下单词重新排列，组成一个含有过去分词让步状语的正确句子。","words":["battered","by","decades","of","neglect","the","ancient","theatre","retained","its","extraordinary","grandeur"],"correctSentence":"Battered by decades of neglect, the ancient theatre retained its extraordinary grandeur.","explanation":"过去分词短语 battered by decades of neglect 置于句首，逻辑主语为 the ancient theatre（被忽视的对象），表示让步关系（= although it had been battered by...）。主句说剧场仍保留了壮观，与让步语义对比鲜明。","subSkill":"past_participle_clauses_for_condition_concession"},{"type":"fill","instruction":"找出并改正以下句子中的悬垂分词错误。在空格中填写正确的主句主语（一个词）。","sentence":"Having analysed the soil samples for weeks, the results were finally published. Correction: Having analysed the soil samples for weeks, the ___ finally published the results.","acceptableAnswers":["researchers","scientists","team","analysts"],"explanation":"原句中 having analysed 的逻辑主语应与主句主语一致，但主句主语是 the results（结果），而结果不能分析土壤样本，构成悬垂分词。改正方法：将主句主语改为能执行分析动作的人（如 researchers / scientists / team），使分词有明确且合理的逻辑主语。","subSkill":"dangling_participle_avoidance"},{"type":"reorder","instruction":"将以下单词重新排列，组成含有独立主格结构的正确句子。","words":["the","formalities","concluded","delegates","from","both","sides","shook","hands","and","posed","for","photographs"],"correctSentence":"The formalities concluded, delegates from both sides shook hands and posed for photographs.","explanation":"the formalities concluded 是独立主格结构，逻辑主语 the formalities 与主句主语 delegates 不同。concluded 为过去分词，表示礼节性程序已经结束（被动完成状态），之后代表们握手合影。整句属于正式书面报道文体的典型句式。","subSkill":"absolute_participial_constructions"},{"type":"fill","instruction":"综合运用：用括号中的提示将两个句子合并为一个句子，使用独立主格或完成式分词结构。填写缺失的分词结构部分（不超过6个词）。","sentence":"The peace talks had broken down. The international community was left with few options. Combine using an absolute construction: ___, the international community was left with few options.","acceptableAnswers":["The peace talks having broken down"],"explanation":"和平谈判破裂发生在国际社会陷入困境之前，两个句子的主语不同（the peace talks / the international community），因此使用独立主格结构，且为完成式（having broken down）强调先发性。整体结构为：the peace talks having broken down + 主句，是书面正式语体中精炼信息的高级手法。","subSkill":"absolute_participial_constructions"},{"type":"fill","instruction":"改写句子，用适当的分词结构（having done 或过去分词）替换从句，使语言更简洁正式。填写分词短语部分（不超过5个词）。","sentence":"Because she had been trained in both law and economics, the minister was uniquely qualified to lead the reform. Rewrite: ___ in both law and economics, the minister was uniquely qualified to lead the reform.","acceptableAnswers":["Trained","Having been trained"],"explanation":"because she had been trained 表示原因，且 minister 是被培训的对象（被动）。可用过去分词 trained 直接替换（更简洁），或用 having been trained 强调先于主句完成（更明确时序）。两者均符合C1书面语规范，在此语境中均可接受。","subSkill":"past_participle_clauses_for_condition_concession"}],"4":[{"type":"choice","instruction":"选择正确的分词短语填入空白处，使句子语法正确且逻辑通顺。","sentence":"___ all the evidence carefully, the committee finally reached a unanimous decision.","options":["Having reviewed","Being reviewed","Reviewed","To have reviewed"],"correctIndex":0,"explanation":"主语 the committee 在裁决之前已完成审查证据的动作，用完成式分词 having reviewed 表示该动作先于主句动作发生，体现时间上的先后关系。","subSkill":"perfect_participle_having_done"},{"type":"choice","instruction":"选择正确的分词形式，注意主句主语与分词动作的逻辑关系。","sentence":"___ in haste, the report contained several factual errors that misled readers.","options":["Having written","Written","Writing","Being written"],"correctIndex":1,"explanation":"the report 是被写的对象，与动词 write 构成被动关系，因此用过去分词 written 引导表示原因的状语从句，说明报告出错的原因是仓促撰写所致。","subSkill":"past_participle_clauses_for_condition_concession"},{"type":"choice","instruction":"选择最准确的独立主格结构完成下列句子。","sentence":"___, the rescue team pressed on through the storm without stopping.","options":["Their supplies running low","Their supplies ran low","Running low their supplies","Having their supplies run low"],"correctIndex":0,"explanation":"独立主格结构由名词短语加分词构成，their supplies 是独立主格的逻辑主语，running low 是现在分词作表语，整体表示背景条件，与主句主语 the rescue team 不同，因此不能用普通分词短语。","subSkill":"absolute_participial_constructions"},{"type":"error","instruction":"下列句子中有一个词语使用错误，找出错误并改正。","words":["Having","been","submitted","the","application",",","the","deadline","passed","before","a","reply","arrived"],"errorIndex":7,"correction":"Having submitted the application, the applicant waited, but the deadline passed before a reply arrived.","explanation":"原句的悬垂分词问题在于：having been submitted 的逻辑主语应是提交申请的人，但主句主语是 the deadline，造成逻辑矛盾。正确写法需确保分词短语的逻辑主语与主句主语一致。","subSkill":"dangling_participle_avoidance"},{"type":"fill","instruction":"用括号内动词的正确分词形式填空，注意时态和语态。","sentence":"(Grant) ___ approval by the board last Monday, the project team began hiring contractors the very next day.","acceptableAnswers":["Granted"],"explanation":"the project team 是被批准的对象，与 grant 构成被动关系，用过去分词 granted 引导表示条件或原因的状语从句，说明正是因为获得批准，团队才得以立即行动。","subSkill":"past_participle_clauses_for_condition_concession"},{"type":"fill","instruction":"用括号内动词的正确完成分词形式填空，体现动作的先后顺序。","sentence":"(Live) ___ abroad for over a decade, she found it surprisingly difficult to readjust to life back home.","acceptableAnswers":["Having lived"],"explanation":"在国外居住是回国之前已经完成的较长经历，用完成式分词 having lived 准确表达该经历先于主句动作发生，也解释了为何重新适应困难。","subSkill":"perfect_participle_having_done"},{"type":"error","instruction":"下列句子中有一处分词使用错误，找出并改正。","words":["Walking","along","the","riverbank",",","a","rare","bird","was","spotted","by","the","researchers"],"errorIndex":0,"correction":"Walking along the riverbank, the researchers spotted a rare bird.","explanation":"walking along the riverbank 的逻辑主语必须与主句主语一致。原句主句主语是 a rare bird，暗示鸟在河边散步，逻辑荒谬。应将主句改为主动式，使 the researchers 成为主句主语，与分词短语的逻辑主语吻合。","subSkill":"dangling_participle_avoidance"},{"type":"fill","instruction":"用括号内动词的现在分词形式填空，使分词短语表达结果关系。","sentence":"The factory released untreated chemicals into the river, (cause) ___ widespread damage to the local ecosystem.","acceptableAnswers":["causing"],"explanation":"工厂排放化学物质是原因，生态破坏是随之而来的结果。用现在分词 causing 引导表示结果的分词短语，比 which caused 更简洁，符合书面语压缩信息的惯例。","subSkill":"present_participle_clauses_for_result_reason"}],"5":[{"type":"reorder","instruction":"将下列词语重新排列，组成一个含有独立主格结构的正确句子。","words":["the","negotiations","having","collapsed",",","both","governments","suspended","diplomatic","ties","indefinitely"],"correctSentence":"The negotiations having collapsed, both governments suspended diplomatic ties indefinitely.","explanation":"独立主格结构 the negotiations having collapsed 由名词短语加完成分词构成，其逻辑主语 the negotiations 与主句主语 both governments 不同，表示导致外交关系中断的背景原因，完成分词体现谈判破裂先于外交暂停发生。","subSkill":"absolute_participial_constructions"},{"type":"fill","instruction":"用括号内动词的适当分词形式填空（注意：句子含有两处空白，依次填入）。","sentence":"(Exhaust) ___ by the long negotiations and (offer) ___ no further concessions, the lead negotiator finally walked out of the talks.","acceptableAnswers":["Exhausted","offered"],"explanation":"第一空：the lead negotiator 是被耗尽精力的对象，用过去分词 exhausted 表示被动的状态原因。第二空：negotiator 是被提供让步的对象，用过去分词 offered 构成表示条件或让步的分词短语，两个分词短语并列修饰主句主语。","subSkill":"past_participle_clauses_for_condition_concession"},{"type":"fill","instruction":"保持原句意思不变，用分词短语改写划线部分，将整句写在空白处。","sentence":"Because she had studied the local dialect for three years, she was able to conduct the interviews without an interpreter. Rewrite beginning: ___ for three years, she was able to conduct the interviews without an interpreter.","acceptableAnswers":["Having studied the local dialect"],"explanation":"原句中 because she had studied 表示在主句动作之前已完成的原因，改写时用完成式分词短语 having studied the local dialect 替代，保留时间先后关系和原因含义，同时使句子更为简洁，适合书面语。","subSkill":"perfect_participle_having_done"},{"type":"error","instruction":"下列句子含有一处分词或独立主格使用错误，找出错误词并给出改正后的形式。","words":["The","president","having","been","re-elected",",","celebrating","his","victory","was","held","in","the","capital","that","evening"],"errorIndex":7,"correction":"The president having been re-elected, a celebration of his victory was held in the capital that evening.","explanation":"主句的真正主语应是庆祝活动本身，而非模糊的动名词短语。将主句改为 a celebration of his victory was held 使结构清晰：独立主格 the president having been re-elected 提供背景，主句陈述随之发生的事件，两者逻辑主语各自独立，结构合法。","subSkill":"absolute_participial_constructions"},{"type":"choice","instruction":"选择最恰当的分词短语，使句子在语法和逻辑上均正确。","sentence":"___ the same mistake twice in a month, the intern was placed on a formal performance review.","options":["Having made","Making","Been making","Made"],"correctIndex":0,"explanation":"实习生犯错在先，被列入绩效审查在后，两个动作有明确的先后顺序，因此用完成式分词 having made 表达前一动作已完成；若用 making 则仅表示同时发生的原因，无法体现时序；made 作为过去分词需要被动含义，而 make a mistake 的主语是实习生本人，为主动关系，故不适用。","subSkill":"perfect_participle_having_done"},{"type":"reorder","instruction":"将下列词语排列成含有现在分词结果状语的正确句子。","words":["the","new","policy","drastically","cut","funding","for","rural","schools",",","leaving","thousands","of","students","without","adequate","resources"],"correctSentence":"The new policy drastically cut funding for rural schools, leaving thousands of students without adequate resources.","explanation":"现在分词短语 leaving thousands of students without adequate resources 置于句末，表示削减资金这一行为所导致的直接结果，分词的逻辑主语与主句主语 the new policy 一致，结构合法，是书面语中表达因果连贯的常见手段。","subSkill":"present_participle_clauses_for_result_reason"},{"type":"fill","instruction":"保持原句意思不变，用独立主格结构改写划线部分，将整句写在空白处。","sentence":"Because the last train had already departed, we had no choice but to book a hotel for the night. Rewrite beginning: ___, we had no choice but to book a hotel for the night.","acceptableAnswers":["The last train having already departed"],"explanation":"原句中 because the last train had already departed 是原因状语从句，其主语 the last train 与主句主语 we 不同，因此不能用普通分词短语，须改为独立主格结构 the last train having already departed，用完成分词体现火车离开先于我们作决定发生。","subSkill":"absolute_participial_constructions"},{"type":"error","instruction":"下列句子中分词短语存在悬垂分词错误，找出错误词并给出改正建议。","words":["Considered","one","of","the","finest","novels","of","the","century",",","critics","praised","the","book","unanimously"],"errorIndex":0,"correction":"Considered one of the finest novels of the century, the book was praised unanimously by critics.","explanation":"considered one of the finest novels of the century 的逻辑主语应是被如此评价的 the book，但原句主句主语是 critics，导致悬垂分词错误，暗示评论家被认为是最佳小说之一，逻辑荒谬。将主句改为被动式并以 the book 为主语，使分词短语的逻辑主语与主句主语一致。","subSkill":"dangling_participle_avoidance"}]}},"7":{"levels":{"1":[{"type":"choice","options":["is working","was working","has been working","will be working"],"sentence":"Direct: 'I am working on the report.' → She told her manager that she ___ on the report.","subSkill":"backshift_in_complex_reported_speech","explanation":"引导动词 told 是过去时，因此从句时态需要回移。现在进行时 'am working' 回移为过去进行时 'was working'。","instruction":"选择正确答案完成间接引语句子。注意时态回移规则。","correctIndex":1},{"type":"choice","options":["suggested","urged","claimed","recommended"],"sentence":"The lawyer stated in court that the defendant ___ nothing to do with the crime.","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest","explanation":"claimed 表示声称某事为真（尤其是尚未证实的事），符合法庭上辩护的语境。suggested 表示建议；urged 表示强烈要求；recommended 表示推荐，均不适合此处。","instruction":"选择最恰当的报告动词完成句子，注意报告动词的准确含义。","correctIndex":2},{"type":"choice","options":["did she want","she had wanted","she wants","had she wanted"],"sentence":"The interviewer asked the candidate why ___ the position.","subSkill":"reporting_questions_and_imperatives","explanation":"间接疑问句使用陈述语序，不倒装。引导动词 asked 是过去时，所以 wants 回移为 had wanted（现在时→过去完成时）。'did she want' 使用了疑问语序，错误。","instruction":"选择正确答案。注意报告疑问句的语序规则。","correctIndex":1},{"type":"choice","options":["were","had been","are","would be"],"sentence":"The biology teacher explained that cells ___ the basic unit of all living organisms.","subSkill":"no_backshift_for_general_truths","explanation":"细胞是生命体基本单位是普遍的科学真理，始终成立。描述普遍真理时，即使引导动词是过去时（explained），从句时态也可以不回移，保持一般现在时 are。","instruction":"选择正确答案。判断此句是否需要时态回移。","correctIndex":2},{"type":"choice","options":["must","had to","should have","would have to"],"sentence":"Direct: 'You must submit the application by Friday.' → The advisor told the student that she ___ submit the application by Friday.","subSkill":"backshift_in_complex_reported_speech","explanation":"must 在间接引语时态回移中变为 had to。原句中的 must 表示义务，回移后用 had to 表示过去的义务要求。","instruction":"选择正确答案完成间接引语。注意情态动词的回移规则。","correctIndex":1},{"type":"choice","options":["is","was","be","being"],"sentence":"The committee suggested that the budget ___ reviewed before the final vote.","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest","explanation":"suggest + that 从句在正式书面语中常使用虚拟语气（subjunctive mood），即 that 从句用动词原形，不随主语或时态变化。所以用 be 而非 is 或 was。","instruction":"选择正确答案。注意 suggest 的正确句式搭配。","correctIndex":2},{"type":"choice","options":["that they leave","to leave","leaving","should leave"],"sentence":"The fire marshal ordered everyone ___ the building immediately.","subSkill":"reporting_questions_and_imperatives","explanation":"报告祈使句（命令/要求）使用 order / urge / tell / ask + 宾语 + to do 结构。因此用 'ordered everyone to leave'，而不用 that 从句。","instruction":"选择正确答案完成报告祈使句。","correctIndex":1},{"type":"choice","options":["is arguing","argued","had argued","argues"],"sentence":"Smith (2019) ___ that globalisation has fundamentally altered patterns of inequality across developed nations.","subSkill":"academic_reporting_with_that_clauses","explanation":"在学术写作中，引用已发表文献中的观点时，通常使用一般现在时（historical present），因为该研究成果仍然存在于文本中并持续有效。argues 是标准的学术引用用法。","instruction":"选择正确答案完成学术转述句。","correctIndex":3}],"2":[{"type":"choice","options":["has already sent","already sent","had already sent","would already send"],"sentence":"Direct: 'I have already sent the documents.' → He confirmed that he ___ the documents.","subSkill":"backshift_in_complex_reported_speech","explanation":"原句中的现在完成时 'have sent' 在时态回移后变为过去完成时 'had sent'。引导动词 confirmed 是过去时，触发回移。","instruction":"选择正确答案。注意过去完成时在间接引语中的使用。","correctIndex":2},{"type":"fill","sentence":"The professor warned that if students (not submit) ___ their essays on time, they (receive) ___ a grade penalty.","subSkill":"backshift_in_complex_reported_speech","explanation":"原条件句为一般现在时 + will，回移后变为过去时 + would。'do not submit' → 'did not submit'；'will receive' → 'would receive'。","instruction":"用括号内动词的正确形式填空，注意时态回移。","acceptableAnswers":["did not submit","would receive"]},{"type":"choice","options":["suggested","recommended","alleged","urged"],"sentence":"The opposition leader ___ that the prime minister had deliberately misled parliament, calling for an immediate inquiry.","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest","explanation":"alleged 表示在未经证实的情况下指控某人做了某事，带有正式、法律色彩，最符合政治指控的语境。suggested 语气太弱；recommended 表示推荐；urged 表示敦促，均不符合此处含义。","instruction":"选择最恰当的报告动词，注意语义差异。","correctIndex":2},{"type":"fill","sentence":"The reviewer asked whether the results (publish) ___.","subSkill":"reporting_questions_and_imperatives","explanation":"原句为现在完成时被动语态 'have been published'，回移后变为过去完成时被动 'had been published'。间接疑问句用 whether 引导，保持陈述语序。","instruction":"将下列直接问句改写为间接问句，填入空白处。Direct: 'Have the results been published yet?' The reviewer asked whether the results (publish) ___.","acceptableAnswers":["had been published"]},{"type":"choice","options":["separated","had separated","separates","would separate"],"sentence":"Newton demonstrated that light ___ into its component colours when it passes through a prism.","subSkill":"no_backshift_for_general_truths","explanation":"光通过棱镜分解为各色光是永恒的物理事实，不因时间改变。因此即使引导动词 demonstrated 是过去时，描述科学真理的从句仍用一般现在时 separates，不需要回移。","instruction":"选择正确答案。判断以下句子中是否需要时态回移。","correctIndex":2},{"type":"fill","sentence":"The CEO urged all department heads (attend) ___ the emergency meeting without delay.","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest","explanation":"urge + 宾语 + to do 是固定句式。urge 不能接 that 从句加虚拟语气（或接受程度极低），其标准用法是 urge someone to do something。","instruction":"用正确形式填空，完成带有不同句式搭配的报告动词句子。","acceptableAnswers":["to attend"]},{"type":"choice","options":["are demonstrating","have been demonstrated","demonstrate","demonstrated that was"],"sentence":"Chen and Liu (2021) ___ that early childhood nutrition has a lasting impact on cognitive development.","subSkill":"academic_reporting_with_that_clauses","explanation":"学术写作引用在世/已发表作者的现有研究时，通常使用一般现在时（academic present tense），表示该发现持续有效。demonstrate + that 从句是标准学术报告结构。","instruction":"选择正确选项完成学术转述句，注意 that 从句的规范用法。","correctIndex":2},{"type":"fill","sentence":"The mentor advised the researcher (reconsider) ___.","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest","explanation":"advise + 宾语 + to do 是标准句式。这是一道关键词转换题：直接引语中的 should reconsider 转换为间接引语时，使用 advised someone to reconsider，体现了报告动词句式的灵活运用。","instruction":"改写句子保持原意，用所给词开头填写完整的间接引语结构。括号内为填写内容。Direct: 'You should reconsider your approach,' the mentor told the researcher. → The mentor advised the researcher (reconsider) ___.","acceptableAnswers":["to reconsider her approach","to reconsider their approach","to reconsider the approach"]}],"3":[{"type":"fill","sentence":"The witness testified that she (see) ___ the suspect near the building the night before and that he (carry) ___ a large bag.","subSkill":"backshift_in_complex_reported_speech","explanation":"证人在过去（testified）描述更早发生的事（那天晚上），因此两个动词都需要回移至过去完成时。saw → had seen；was carrying → had been carrying（过去进行时→过去完成进行时）。","instruction":"用括号内动词的正确形式填空。注意多层时态回移的复杂情况。","acceptableAnswers":["had seen","had been carrying"]},{"type":"fill","sentence":"The think tank ___ that a new regulatory body ___ established immediately.","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest","explanation":"recommend + that + 主语 + 动词原形（虚拟语气）是正式书面语的标准结构。'should be established' 也可接受，但纯虚拟语气形式 'be established' 更符合正式/学术写作规范。","instruction":"改写句子保持原意，用所给报告动词填写 that 从句结构，注意虚拟语气。Direct: 'The government should establish a new regulatory body immediately.' The think tank ___ (recommend) a new regulatory body ___ established immediately.","acceptableAnswers":["recommended","be"]},{"type":"fill","sentence":"In her keynote address, the economist argued that inequality (widen) ___ significantly over the past two decades and warned that this trend (threaten) ___ social cohesion if left unaddressed.","subSkill":"backshift_in_complex_reported_speech","explanation":"第一空：argued（过去时）触发回移，现在完成时 has widened → 过去完成时 had widened，表示在演讲时间点之前已完成的变化。第二空：warned 触发回移，will threaten → would threaten，表示对未来的预警。","instruction":"综合填空：阅读情境后，用括号中的动词或词组正确形式完成间接引语段落。","acceptableAnswers":["had widened","would threaten"]},{"type":"fill","sentence":"Harrison (2018) ___ that digital literacy ___ for civic participation.","subSkill":"academic_reporting_with_that_clauses","explanation":"学术改写中，'According to X' 结构可转换为 'X argues/contends/maintains + that 从句'。由于是描述持续有效的学术观点，报告动词用一般现在时 argues，从句中的 is essential 也保持现在时，无需回移。","instruction":"关键词转换题：改写句子，保持原意不变，使用 that 从句完成转述。Original: According to Harrison (2018), digital literacy is essential for civic participation. → Harrison (2018) ___ that digital literacy ___ for civic participation.","acceptableAnswers":["argues","is essential"]},{"type":"fill","sentence":"During the seminar, a student asked whether the findings (apply) ___ to non-Western contexts, and the presenter acknowledged that further cross-cultural research (need) ___.","subSkill":"backshift_in_complex_reported_speech","explanation":"第一空：原问句可能是 'Can the findings be applied...?' — can 回移为 could，被动保留，得 could be applied。第二空：presenter acknowledged（过去时），从句表示当时仍然需要，need 回移为 was needed（被动更符合学术风格）。两处均体现正式学术书面语规范。","instruction":"综合题：改写以下对话为学术间接引语段落，填入两处空白。During the seminar, a student asked whether the findings (apply) ___ to non-Western contexts, and the presenter acknowledged that further cross-cultural research (need) ___.","acceptableAnswers":["could be applied","was needed"]}],"4":[{"type":"choice","options":["suggested to","argued","insisted on","proposed that"],"sentence":"The professor ___ that the experiment had been conducted under controlled conditions.","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest","explanation":"argue that + 从句 是学术写作中表达观点的标准搭配，意为\"论证……\"。suggested to 后需接人，insisted on 后接动名词，proposed that 在此语境下语气过弱。","instruction":"选择正确的报告动词及其搭配形式，完成下列句子。","correctIndex":1},{"type":"choice","options":["support","will support","supported","have supported"],"sentence":"The researcher claimed that the results ___ the original hypothesis.","subSkill":"backshift_in_complex_reported_speech","explanation":"主句谓语 claimed 为一般过去时，间接引语中时态需回移：原文中的一般现在时 support 回移为一般过去时 supported。","instruction":"根据时态回移规则，选择正确的从句形式。","correctIndex":2},{"type":"choice","options":["boiled","had boiled","boils","would boil"],"sentence":"The textbook stated that water ___ at 100 degrees Celsius at sea level.","subSkill":"no_backshift_for_general_truths","explanation":"water boils at 100 degrees Celsius 是客观科学真理，转述时不需要时态回移，保持一般现在时 boils。","instruction":"判断以下哪个句子正确地转述了一个一般真理，无需时态回移。","correctIndex":2},{"type":"fill","sentence":"The committee chair reported that the budget proposal (submit) ___ to the board the previous week.","subSkill":"backshift_in_complex_reported_speech","explanation":"原文中的动作（提交预算）发生在报告时间之前，因此在间接引语中需用过去完成时 had been submitted，且为被动语态。","instruction":"用括号内动词的正确形式填空，注意时态回移规则。","acceptableAnswers":["had been submitted"]},{"type":"fill","sentence":"Several economists ___ that the current inflation rate might stabilize within six months. (他们的态度是提出这一可能性，而非断言)","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest","explanation":"suggest that 表示提出某种可能性，语气较为谨慎，符合题目中的交际意图。argue that 也可接受，因为论证本身不等于断言。claim 或 assert 语气过强，不符合要求。","instruction":"用合适的报告动词填空，使句子符合学术写作规范。括号内给出了原文的交际意图。","acceptableAnswers":["suggested","argued"]},{"type":"fill","sentence":"Direct: Does urban sprawl affect biodiversity? The journalist asked whether urban sprawl ___ biodiversity.","subSkill":"reporting_questions_and_imperatives","explanation":"将一般现在时的直接疑问句转为间接引语时，动词需回移为一般过去时，且疑问句语序改为陈述句语序。","instruction":"将直接疑问句改写为间接疑问句，填入合适的内容。","acceptableAnswers":["affected"]}],"5":[{"type":"fill","sentence":"The supervisor (tell) ___ the intern that the report (need) ___ to be revised before submission.","subSkill":"backshift_in_complex_reported_speech","explanation":"主句谓语用一般过去时 told；从句中 need 表示在告知时刻同时存在的需求，时态回移为一般过去时 needed。","instruction":"用括号内动词的正确形式填空，句中有两个空，分别对应两个括号。","acceptableAnswers":["told","needed"]},{"type":"fill","sentence":"Original: The minister said that the policy would be reviewed annually. Rewrite using PLEDGE: The minister ___ to review the policy annually.","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest","explanation":"pledge to do sth 意为\"承诺做某事\"，与原句中 said that...would 所表达的承诺含义相同，但 pledge 后接不定式而非 that 从句，改写后时态保持一致。","instruction":"关键词转换：保持句意不变，用括号中的动词改写句子，完成下方句子。","acceptableAnswers":["pledged"]},{"type":"choice","options":["said they cannot confirm that the data is reliable","acknowledged that the data could not be confirmed as reliable","told that they did not confirm the reliability","suggested to say that the data is not reliable"],"sentence":"Original statement by a researcher: We cannot confirm that the data is reliable. Academic report: The researcher ___.","subSkill":"academic_reporting_with_that_clauses","explanation":"acknowledge that 是学术写作中用于报告研究者承认局限性的标准动词，时态回移正确（could not），且语义准确。选项A时态未回移，选项C中 told 缺少宾语且搭配错误，选项D搭配不符合英语规范。","instruction":"选择最符合学术转述规范的改写方式。","correctIndex":1},{"type":"fill","sentence":"Original: The editor said to the writer: Please restructure the conclusion. Rewrite using URGE: The editor ___ the writer ___ the conclusion.","subSkill":"reporting_questions_and_imperatives","explanation":"urge sb to do sth 是报告祈使句的标准学术写作方式，意为\"催促/强烈建议某人做某事\"，能准确传达编辑的语气强度。","instruction":"关键词转换：用括号内的报告动词改写句子，保持原意，注意动词搭配模式。","acceptableAnswers":["urged","to restructure"]}]},"mission":{"title":"学术会议纪要","scenario":"上周，你参加了一场题为 'The Future of Urban Education' 的国际研讨会。会议上，三位学者分别发表了观点：Dr. Morrison 指出城市学校的资源分配严重不平等；Professor Tan 建议各国政府立即增加对低收入地区学校的财政投入；一位与会者质疑现有的评估模式是否真正反映了学生的学习成果。请根据以上内容，写出三句正式的会议纪要句子，每句对应一位发言者。","scaffolds":[{"hint":"使用时态回移，将 'is distributed unequally' 转换为间接引语形式，并加入 'had been' 或 'was' 等过去时态。","prefix":"Dr. Morrison argued that","suffix":"significantly across urban schools.","example":"Dr. Morrison argued that resources were being distributed highly unequally across urban schools.","grammarCheck":"backshift_in_complex_reported_speech"},{"hint":"recommend + that 从句，注意使用虚拟语气（动词原形）或 should + 动词原形；主语可以用 governments 或 policymakers。","prefix":"Professor Tan recommended that","suffix":"in underfunded areas without delay.","example":"Professor Tan recommended that governments increase financial investment in underfunded areas without delay.","grammarCheck":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"hint":"报告疑问句使用 whether 引导陈述语序；注意将 'truly reflect' 回移为适当的过去时形式，搭配 'genuine measure' 或 'accurate picture' 等学术词汇。","prefix":"One delegate questioned whether existing assessment models","suffix":"of student learning.","example":"One delegate questioned whether existing assessment models truly captured an accurate picture of student learning.","grammarCheck":"reporting_questions_and_imperatives"}],"description":"在这项任务中，你将扮演一名学术期刊的编辑助理，负责将一场研讨会上各位学者的发言整理成正式的书面会议纪要。你需要运用本单元学习的间接引语时态回移、多样化报告动词以及学术转述规范，将直接引语准确转换为正式书面英语。","grammarType":"backshift_in_complex_reported_speech"},"discover":{"tip":"【核心语法：间接引语的时态回移与报告动词用法】\n\n**一、时态回移规则**\n当引导动词为过去时（said, argued, claimed 等），从句时态通常向过去推移一格：\n- 一般现在时 → 一般过去时：'I am tired.' → She said she was tired.\n- 现在进行时 → 过去进行时：'It is raining.' → He said it was raining.\n- 一般过去时 → 过去完成时：'I finished it.' → She said she had finished it.\n- 现在完成时 → 过去完成时：'I have seen it.' → He said he had seen it.\n- will → would；can → could；may → might；must → had to\n\n**二、不回移的情况**\n描述普遍真理、科学定律或仍然成立的事实时，时态可不回移：\n- She pointed out that the Earth orbits the Sun.（科学事实，不用 orbited）\n\n**三、报告动词的句式模式**\n不同报告动词搭配不同句式，不能混用：\n- argue / claim / suggest / note / warn + that 从句\n- urge / advise / warn / ask + 宾语 + to do\n- suggest / recommend + that 从句（常用虚拟语气：should + 动词原形，或直接用动词原形）\n- ask / wonder + whether / if / wh- 从句（报告疑问句，需用陈述语序）\n\n**常见错误：**\n1. 错误：She suggested me to leave. ✗ → 正确：She suggested that I should leave. / She urged me to leave. ✓（suggest 不直接接宾语 + to do）\n2. 错误：He asked where was she going. ✗ → 正确：He asked where she was going. ✓（间接疑问句用陈述语序，不倒装）","story":{"text":"At the international conference last month, several leading scientists presented their findings on climate change. Dr. Patel argued that rising sea levels were accelerating at an unprecedented rate and warned that coastal cities would face severe flooding within decades. She suggested that governments should invest immediately in renewable energy infrastructure. When a journalist asked whether the current policies were sufficient, Dr. Patel replied that they were wholly inadequate. A skeptical delegate claimed that the data had been misinterpreted and insisted that the models used were flawed. However, Dr. Patel pointed out that water expands when it is heated, which explained the measurements. The conference chair urged all delegates to read the full report before drawing conclusions. A young researcher noted that Einstein had once said that imagination was more important than knowledge, implying that bold new thinking was needed. By the end of the day, most delegates agreed that immediate action was necessary and recommended that a global fund be established to address the crisis.","title":"The Climate Debate","highlights":["argued that","warned that","suggested that","claimed that","insisted that","pointed out that","urged","recommended that","were accelerating","would face","had been misinterpreted","is heated"]},"questions":[{"options":["因为海平面实际上已经停止上升了","因为间接引语中时态需要向过去回移，原句的一般现在时变为一般过去时","因为 'argued' 后面只能用过去时","因为这是一个假设性陈述，所以用虚拟语气"],"question":"故事中 Dr. Patel 说海平面正在上升，间接引语变为 'rising sea levels were accelerating'。为什么动词从 'are' 变成了 'were'？","explanation":"间接引语的核心规则是时态回移（backshift）：当引导动词（如 argued）是过去时，从句中的时态通常向过去移动一格。现在进行时变为过去进行时，因此 'are accelerating' 变为 'were accelerating'。","correctIndex":1},{"options":["因为 'point out' 后面不需要时态回移","因为这是一个被普遍认可的科学真理，描述永恒事实时通常不进行时态回移","因为这是错误的写法，应该写 'expanded'","因为 'when' 引导的从句永远用现在时"],"question":"故事中写道 'pointed out that water expands when it is heated'，而没有将 'expands' 回移为 'expanded'。这是为什么？","explanation":"对于普遍真理或科学定律，即使在间接引语中也通常不进行时态回移，因为这些事实在过去、现在和将来都成立。水受热膨胀是物理定律，所以保持 'expands' 和 'is heated'。","correctIndex":1},{"options":["因为 'said' 在正式写作中是禁止使用的","因为不同的报告动词传达说话者的态度和意图，使转述更准确、更符合学术写作规范","因为这些动词后面不需要使用 'that' 从句","因为 'said' 只能用于直接引语"],"question":"故事中使用了多个报告动词：argued, suggested, claimed, urged, recommended。为什么作者不一直用 'said'？","explanation":"在学术写作中，多样化的报告动词（如 argue, claim, suggest, urge, recommend）能够精准传达原说话者的立场、语气和意图。相比之下，反复使用 'said' 显得单调，且无法区分陈述事实、提出建议、表示质疑等不同功能。","correctIndex":1}]}},"8":{"levels":{"1":[{"type":"choice","options":["to send","sending","to have sent","send"],"sentence":"I remember ___ the report to my manager last Friday — she confirmed receipt.","subSkill":"verbs_taking_both_with_meaning_change","explanation":"remember + 动名词（sending）表示回忆起一件已经发生的事。这里说上周五已经发送了，是对过去事件的记忆。remember + 不定式则表示记得去做将来的事。","instruction":"选择正确的选项完成句子，注意动词后接动名词还是不定式会影响句意。","correctIndex":1},{"type":"choice","options":["tried to restart","tried restarting","had tried restart","was tried to restart"],"sentence":"The technician ___ restarting the server, and the error message disappeared.","subSkill":"verbs_taking_both_with_meaning_change","explanation":"try + 动名词（restarting）表示将某件事作为一种解决手段来尝试——这里重启服务器是一种尝试性方法，而且成功了（错误消息消失了）。try + 不定式强调努力去做，不带实验含义。","instruction":"选择正确的选项。注意 try 接不同形式时意义不同。","correctIndex":1},{"type":"choice","options":["studying","to study","study","having studied"],"sentence":"After finishing her undergraduate degree, she went on ___ a PhD at Cambridge.","subSkill":"verbs_taking_both_with_meaning_change","explanation":"go on + 不定式（to study）表示完成一件事之后接着去做另一件不同的事。这里完成本科之后继续攻读博士，是顺序性的不同行动。go on + 动名词则表示继续做同一件事。","instruction":"选择正确的选项，注意 go on 接动名词或不定式的语义区别。","correctIndex":1},{"type":"choice","options":["To keeping","Keep","Keeping","For keep"],"sentence":"___ accurate records is essential in any research context.","subSkill":"gerunds_as_subjects_in_formal_writing","explanation":"动名词短语（Keeping accurate records）用作句子主语，在正式书面语和学术写作中非常常见，语气比 'It is essential to keep...' 更正式。主语为动名词短语时，谓语动词用单数（is）。","instruction":"选择最符合正式书面语规范的主语结构。","correctIndex":2},{"type":"choice","options":["to access","to be accessed","to have been accessed","having been accessed"],"sentence":"The documents appear ___ without proper authorization — the security team is investigating.","subSkill":"perfect_and_passive_infinitives","explanation":"appear + 不定式表示外表或推断。此处文件的被访问发生在主句动作之前，且主语（documents）是被动承受者，因此需要完成式被动不定式（to have been accessed）。","instruction":"选择正确的完成式或被动式不定式形式。","correctIndex":2},{"type":"choice","options":["informing","to inform","having informed","inform"],"sentence":"We regret ___ you that your application has been unsuccessful.","subSkill":"verbs_taking_both_with_meaning_change","explanation":"regret + 不定式（to inform）是一种正式礼貌用语，表示遗憾地（即将）告知对方某事，是向前指向的。regret + 动名词则表示对过去所做的事感到遗憾。","instruction":"选择正确选项。注意 regret 接动名词与不定式时意义完全不同。","correctIndex":1},{"type":"choice","options":["extend","to extend","having extended","extending"],"sentence":"The committee discussed the possibility of ___ the project deadline by two weeks.","subSkill":"complex_noun_phrase_with_gerund","explanation":"介词（of）后面必须接动名词（extending），不能接不定式。'the possibility of extending' 构成一个以动名词为核心的复合名词短语，这是英语中的固定语法规则。","instruction":"选择最自然、正确的复合名词短语结构。","correctIndex":3},{"type":"choice","options":["to implement","to be implemented","implementing","to have implemented"],"sentence":"The new policy is expected ___ next month following parliamentary approval.","subSkill":"perfect_and_passive_infinitives","explanation":"主语 'policy' 是被实施的对象（被动关系），因此需要被动式不定式（to be implemented）。若用 to implement，则表示主语主动去实施，逻辑不通。","instruction":"选择正确选项完成句子，注意被动式不定式的构成。","correctIndex":1}],"2":[{"type":"choice","options":["to forget","to be forgetting","to have forgotten","to have been forgotten"],"sentence":"The professor seems ___ the deadline — she has already submitted her chapter.","subSkill":"perfect_and_passive_infinitives","explanation":"此处需要完成式不定式（to have forgotten），因为'忘记'这一动作发生在 seems 所指的现在时刻之前——她已经提交了，说明她之前就忘了截止日期。","instruction":"选择最准确的选项，注意句意所需的时态和语态。","correctIndex":2},{"type":"choice","options":["to champion","championing","having championed","champion"],"sentence":"He went on ___ the very technique he had once dismissed as simplistic.","subSkill":"verbs_taking_both_with_meaning_change","explanation":"go on + 不定式（to champion）表示在前一阶段（批评该技巧）结束后，转而去做一件不同的事（为其辩护）。若用 go on championing，则表示一直持续做同一件事，与句意矛盾。","instruction":"选择最符合句意的选项。上下文：作者原来一直批评某种写法，后来态度改变了。","correctIndex":0},{"type":"fill","sentence":"(Have / not inform) ___ about the change in venue, several delegates arrived at the wrong building.","subSkill":"perfect_and_passive_infinitives","explanation":"此处需要完成式被动分词的否定形式（Not having been informed），表示主语（delegates）在主句动作发生之前没有被告知——被动（被通知）且时间先于主句，因此用 having been informed，否定加 Not 于最前。","instruction":"用括号中动词的正确形式填空，注意完成式被动分词结构。","acceptableAnswers":["Not having been informed"]},{"type":"fill","sentence":"She tried (contact) ___ the embassy three times but received no response, so she tried (send) ___ a formal letter instead.","subSkill":"verbs_taking_both_with_meaning_change","explanation":"第一个 try + 不定式（to contact）表示努力去完成联系使馆这一目标——暗含困难或失败；第二个 try + 动名词（sending）表示改用另一种方式（发正式信函）作为新的尝试手段。","instruction":"用括号中动词的正确动名词或不定式形式填空，每空一词或词组。","acceptableAnswers":["to contact","sending"]},{"type":"fill","sentence":"(It is not easy / manage a multilateral negotiation) ___.","subSkill":"gerunds_as_subjects_in_formal_writing","explanation":"正式书面语中常以动名词短语（Managing a multilateral negotiation）作主语，将原来的 'It is not easy to manage...' 改写为更直接、更学术的表达。注意主语为动名词短语时谓语用单数（is）。","instruction":"将括号中的词语改写为以动名词短语作主语的正式句子，填入空白处。","acceptableAnswers":["Managing a multilateral negotiation is not easy"]},{"type":"fill","sentence":"There is little prospect of the two sides (reach) ___ an agreement before the summit.","subSkill":"complex_noun_phrase_with_gerund","explanation":"介词 of 后面必须接动名词（reaching），构成复合名词短语 'prospect of reaching'。介词后不可接不定式，这是英语语法的基本规则。","instruction":"用括号中动词的正确形式填空，注意介词后必须接动名词。","acceptableAnswers":["reaching"]},{"type":"fill","sentence":"The ancient manuscript is believed (write) ___ sometime in the ninth century.","subSkill":"perfect_and_passive_infinitives","explanation":"主语（manuscript）是被书写的对象（被动），且书写时间早于现在的推断（完成），因此需要完成式被动不定式（to have been written）。这是 believe + 不定式结构中对远于现在的被动事件的标准表达。","instruction":"用括号中动词的正确完成式不定式或被动式不定式形式填空。","acceptableAnswers":["to have been written"]}],"3":[{"type":"fill","sentence":"The artifact is thought (remove) ___ from the site decades before the current regulations (introduce) ___.","subSkill":"perfect_and_passive_infinitives","explanation":"第一空：主语（artifact）被移走（被动），且移走时间早于现在的推断（完成），故用完成式被动不定式（to have been removed）。第二空：regulations 在特定的过去时间点被引入（被动，简单过去时），故用 were introduced。","instruction":"用括号中动词的正确形式填空（每空填一个完整的动词短语），注意句意对时态和语态的要求。","acceptableAnswers":["to have been removed","were introduced"]},{"type":"reorder","words":["the","likelihood","of","being","misunderstood","increases","significantly","without","precise","terminology"],"subSkill":"complex_noun_phrase_with_gerund","explanation":"本句以复合名词短语 'the likelihood of being misunderstood' 为主语，其中 'of being misunderstood' 是介词短语修饰 likelihood，'being misunderstood' 是被动式动名词（动名词的被动形式）。谓语为 increases，副词 significantly 修饰谓语。","instruction":"将下列词语重新排列，组成一个语法正确、语义完整的句子。","correctSentence":"The likelihood of being misunderstood increases significantly without precise terminology."},{"type":"fill","sentence":"Please remember (submit) ___ your expense claims by the end of the quarter — the finance team will not process late submissions.","subSkill":"verbs_taking_both_with_meaning_change","explanation":"remember + 不定式（to submit）表示记得去做一件将来的事（提醒行为）。句中后半句强调截止日期和后果，说明提交是尚未发生的将来动作。若用 remember submitting，则表示回忆起过去已经提交过，与句意矛盾。","instruction":"用括号中动词的正确形式填空，仔细辨别 remember 在此句中的语义方向。","acceptableAnswers":["to submit"]},{"type":"reorder","words":["having","been","awarded","the","grant","the","research","team","expanded","their","fieldwork"],"subSkill":"perfect_and_passive_infinitives","explanation":"Having been awarded 是完成式被动分词短语，作状语，表示获得资助这一被动事件发生在主句动作（expanded）之前。主语（the research team）是被授予资助的对象，因此用被动形式（been awarded）。","instruction":"将下列词语重新排列，组成一个语法正确的句子，注意完成式被动分词的位置。","correctSentence":"Having been awarded the grant, the research team expanded their fieldwork."},{"type":"reorder","words":["she","went","on","to","become","the","youngest","director","in","the","organisation","after","leading","the","pilot","project"],"subSkill":"verbs_taking_both_with_meaning_change","explanation":"go on + 不定式（to become）表示完成一件事（领导试点项目）之后，接着取得新的成就（成为最年轻的主任）——两个不同的行动按时间顺序相继发生。若用 go on leading，则表示继续领导，与句意不符。","instruction":"将下列词语重新排列，组成语法正确的句子，注意 go on 后接哪种形式以及句意逻辑。","correctSentence":"After leading the pilot project, she went on to become the youngest director in the organisation."}],"4":[{"type":"choice","options":["to inform","informing","having informed","to have informed"],"sentence":"The committee regrets ___ you that your application has been unsuccessful.","subSkill":"verbs_taking_both_with_meaning_change","explanation":"regret + 不定式 表示对即将做的事感到遗憾（正式用法，常见于书面通知）；regret + 动名词 则表示对已经发生的事感到遗憾。此处是正在告知对方坏消息，用不定式。","instruction":"选择正确的选项，注意动词后接动名词与不定式时的语义差异。","correctIndex":0},{"type":"choice","options":["to leave","to be leaving","to have left","to have been leaving"],"sentence":"She is believed ___ the country before the investigation was launched.","subSkill":"perfect_and_passive_infinitives","explanation":"to have left（完成式被动不定式的主动形式）表示离开这一动作发生在 is believed 所指时间之前，即调查启动前已经离开。普通不定式 to leave 无法表达这种时间上的先后关系。","instruction":"选择最准确的选项，注意完成式不定式的语义。","correctIndex":2},{"type":"choice","options":["To burn","Burn","Burning","The burning of"],"sentence":"___ fossil fuels at the current rate will accelerate climate change irreversibly.","subSkill":"gerunds_as_subjects_in_formal_writing","explanation":"在正式书面语中，动名词短语（Burning fossil fuels）作主语比不定式更常见，且更自然。The burning of 后需接名词，结构不同。Burn 直接作主语不符合英语语法。","instruction":"选择在正式书面语中作主语最地道的表达方式。","correctIndex":2},{"type":"fill","sentence":"The suspect is reported (detain) ___ by border police two days before the trial began.","subSkill":"perfect_and_passive_infinitives","explanation":"to have been detained 是完成式被动不定式，表示拘留动作（被动）发生在 is reported 之前（完成）。需要同时体现被动（be detained）和时间先后（have + past participle）。","instruction":"用括号中动词的适当形式填空，注意被动式完成不定式的构成。","acceptableAnswers":["to have been detained"]},{"type":"fill","sentence":"Cutting the budget means (reduce) ___ staff numbers by at least thirty percent.","subSkill":"verbs_taking_both_with_meaning_change","explanation":"mean + 动名词 表示 某事意味着/导致另一件事，即削减预算必然导致裁员。mean + 不定式 则表示打算做某事，语义完全不同。","instruction":"用括号中动词的正确形式填空，注意 mean 接不同结构时的语义变化。","acceptableAnswers":["reducing"]},{"type":"fill","sentence":"It is widely acknowledged that publishing research without peer review undermines academic integrity. → ___ without peer review undermines academic integrity.","subSkill":"gerunds_as_subjects_in_formal_writing","explanation":"将 it is acknowledged that 的形式主语结构改为动名词短语直接作主语，正式书面语中此结构更简洁有力。Publishing research 是动名词复合短语，对应原句 that 从句的主要动作。","instruction":"将下句改写，以动名词短语作主语，保持句意不变。在横线上填写改写后句子的主语部分（动名词短语）。","acceptableAnswers":["Publishing research"]}],"5":[{"type":"choice","options":["fail to provide","failing to provide","failure of providing","failure to provide"],"sentence":"The government's persistent ___ adequate infrastructure in rural areas has drawn widespread criticism.","subSkill":"complex_noun_phrase_with_gerund","explanation":"failure to do sth 是固定的复杂名词短语结构，表示未能做某事；failure of doing 不是标准用法。failing to provide 是动名词短语，不能直接跟在所有格 government's 后作名词核心词。","instruction":"选择最符合语境且语法正确的选项，注意复杂名词短语结构。","correctIndex":3},{"type":"choice","options":["to tell","to have told","being told","to be told"],"sentence":"I distinctly remember ___ that the deadline was the fifteenth, not the twenty-fifth.","subSkill":"perfect_and_passive_infinitives","explanation":"remember + 动名词 表示记得过去发生的事。being told（动名词被动式）表示记得曾经被告知，与语境（我清楚地记得有人告诉我）吻合。to be told 是不定式被动，语义变为记得要去被告知，逻辑不通。","instruction":"选择语义最准确的选项。","correctIndex":2},{"type":"fill","sentence":"The scientist admitted (mislead) ___ the review panel and (fabricate) ___ parts of the data in her earlier publications.","subSkill":"perfect_and_passive_infinitives","explanation":"admit + 动名词 表示承认做过某事。由于误导和造假均发生在承认（admit）之前，应使用完成式动名词 having misled / having fabricated，强调这些行为在时间上先于承认的动作。","instruction":"用括号内动词的正确形式填空（每空一个答案）。","acceptableAnswers":["having misled","having fabricated"]},{"type":"fill","sentence":"It is often argued that implementing stricter data privacy laws too hastily causes more harm than good. → ___ too hastily causes more harm than good.","subSkill":"gerunds_as_subjects_in_formal_writing","explanation":"用动名词短语 Implementing stricter data privacy laws 替换形式主语 it ... that 结构，使句子更简洁正式。动名词短语内部保留原修饰成分（stricter data privacy laws）不变。","instruction":"根据提示，用动名词短语改写句子作正式书面语的主语，填写完整的主语从 ___ 开始处到句子主要动词前的部分。","acceptableAnswers":["Implementing stricter data privacy laws"]},{"type":"fill","sentence":"After briefly summarising the background, the professor went on (examine) ___ the ethical implications of the experiment in considerable depth.","subSkill":"verbs_taking_both_with_meaning_change","explanation":"go on + 不定式 表示做完一件事后接着做另一件不同的事（先概述背景，然后继续深入探讨伦理问题）；go on + 动名词 则表示继续做同一件事。此处两个动作不同，应用 to examine。","instruction":"用括号内词语的正确形式填写，注意 go on 接不同结构时的语义区别。","acceptableAnswers":["to examine"]},{"type":"reorder","words":["the","repeated","delaying","of","key","reforms","by","successive","governments","has","exacerbated","the","crisis"],"subSkill":"complex_noun_phrase_with_gerund","explanation":"The repeated delaying of key reforms by successive governments 是以动名词为核心的复杂名词短语作主语：定冠词 the + 形容词 repeated + 动名词 delaying + of 短语（宾语）+ by 短语（施事）。动名词名词化后，整个短语作主语，谓语用单数 has exacerbated。","instruction":"将下列词语重新排列，组成一个语法正确的正式句子。","correctSentence":"The repeated delaying of key reforms by successive governments has exacerbated the crisis."}]},"mission":{"title":"The Policy Briefing","scenario":"政府正在审议一项关于数据隐私的新法规。你需要在简报中（1）说明问题的严重性，（2）描述过去已采取的措施，（3）提出前瞻性建议。请在写作中自然地运用：动名词短语作主语（正式文体）、完成式或被动式不定式、以及 try / remember / go on + 动名词或不定式的语义区分。","scaffolds":[{"hint":"用动名词短语作主语，说明某项行动的紧迫性或必要性，谓语用单数动词。","prefix":"Implementing robust data protection frameworks","suffix":"across all government departments.","example":"Implementing robust data protection frameworks remains a priority across all government departments.","grammarCheck":"gerunds_as_subjects_in_formal_writing"},{"hint":"用完成式被动不定式（to have been + 过去分词）描述法规的制定早于某一过去时间点，且法规是被制定的对象。","prefix":"The existing regulations appear","suffix":"before the current threat landscape emerged.","example":"The existing regulations appear to have been drafted before the current threat landscape emerged.","grammarCheck":"perfect_and_passive_infinitives"},{"hint":"先用 try + 动名词 表示尝试某种政策手段，再用 go on + 不定式 表示之后进一步采取的不同措施。","prefix":"This office recommends","suffix":"and subsequently going on to establish an independent oversight body.","example":"This office recommends trying a phased enforcement approach and subsequently going on to establish an independent oversight body.","grammarCheck":"verbs_taking_both_with_meaning_change"}],"description":"你是一名政策分析师，需要为高级官员撰写一份正式的政策简报。请运用本单元所学的动名词与不定式高级用法，用准确、正式的书面英语表达复杂的政策观点。","grammarType":"gerund_vs_infinitive_meaning_difference"},"discover":{"tip":"【核心对比：动名词 vs 不定式的语义差异】\n\n1. remember / forget / regret / recall + 动名词 → 指已经发生的过去事件（回忆）\n   remember / forget / regret + 不定式 → 指尚未发生或将来要做的事（意图/提醒）\n   例：She remembered locking the door.（她记得锁了门——已锁）\n       She remembered to lock the door.（她记得要去锁门——去锁了）\n\n2. try + 动名词 → 尝试某种方法，看看有没有效果\n   try + 不定式 → 努力去完成某个目标\n   例：Try using a different password.（换一个密码试试）\n       She tried to open the safe but failed.（她努力想打开保险柜但失败了）\n\n3. go on + 动名词 → 继续做同一件或相同类型的事\n   go on + 不定式 → 做完一件事后接着做另一件事\n   例：He went on talking for an hour.（他继续滔滔不绝地说）\n       She went on to win three awards.（她接着又赢得了三个奖项）\n\n4. 动名词短语作主语（正式书面语）：Conducting research requires patience.\n   这比 'It requires patience to conduct research' 更正式、更学术。\n\n5. 完成式和被动式不定式：\n   Having been warned = 被动式完成分词，表示动作先于主句发生且主语是被动承受者。\n   to have been delayed = 完成式被动不定式，用于表示在参照时间点之前已完成的被动动作。\n\n【常见错误】\n- 错误：She regretted to not take his advice.\n  正确：She regretted not taking his advice.（regret 接动名词时表回忆，否定用 not + 动名词）\n- 错误：Presenting data without analysis are unprofessional.\n  正确：Presenting data without analysis is unprofessional.（动名词短语作主语，谓语用单数）","story":{"text":"Dr. Chen had always enjoyed conducting fieldwork in remote areas, but her latest project forced her to reconsider her methods. She remembered meeting a local elder the previous year who had warned her about the seasonal floods. Having been warned so clearly, she regretted not taking his advice sooner. Her team went on to collect water samples despite the risks, yet she later recalled telling them to be cautious near the riverbanks. Presenting raw data without proper analysis is considered unprofessional in academic circles, so she insisted on verifying every figure before submission. She tried adjusting the filtration settings first, which improved the readings slightly, but she then tried to contact the laboratory for guidance and received no reply. The failure to receive a timely response meant losing two days of work. Her supervisor suggested having the samples retested by an external agency, acknowledging that being delayed by bureaucratic processes was an unfortunate reality of fieldwork. Dr. Chen ultimately accepted the situation, knowing that conducting rigorous research sometimes means tolerating frustrating setbacks, and that to compromise data integrity would be unthinkable.","title":"The Researcher's Dilemma","highlights":["enjoyed conducting","remembered meeting","Having been warned","regretted not taking","went on to collect","recalled telling","Presenting raw data","tried adjusting","tried to contact","having the samples retested","being delayed","to compromise data integrity"]},"questions":[{"options":["She made a mental note to meet the elder in the future.","She recalled a past meeting that had already taken place.","She was reminded to meet the elder by someone else.","She forgot that she had met the elder."],"question":"In the story, Dr. Chen 'remembered meeting a local elder.' What does this tell us?","explanation":"remember + 动名词（meeting）表示回忆起过去已发生的事。若用 remember + 不定式（to meet），则表示记得去做某件将来的事。两者时态指向截然不同。","correctIndex":1},{"options":["Both mean she made an effort but failed in both cases.","The first means she attempted something as an experiment; the second means she made an effort to do something.","The first means she failed; the second means she succeeded.","There is no meaningful difference; both structures are interchangeable here."],"question":"The story says she 'tried adjusting the filtration settings' and then 'tried to contact the laboratory.' What is the difference?","explanation":"try + 动名词表示尝试某种做法（作为实验或手段），try + 不定式表示努力去做某事（强调目标与意图）。本文中调整设置是一种尝试性手段，联系实验室则是一个有目的的行动。","correctIndex":1},{"options":["It is a participial phrase modifying the subject.","It functions as the subject of the sentence, a formal use of a gerund phrase.","It is an adverbial clause expressing condition.","It is an object complement following a reporting verb."],"question":"What grammatical role does 'Presenting raw data without proper analysis' play in the sentence?","explanation":"在正式书面语中，动名词短语可充当句子主语。此处 'Presenting raw data without proper analysis' 是整个句子的主语，谓语是 'is considered'。这是动名词作主语的典型学术用法。","correctIndex":1}]}},"9":{"levels":{"1":[{"type":"choice","options":["A","The","An","(no article)"],"sentence":"___ justice is the foundation of a civilised society.","subSkill":"article_omission_in_abstract_nouns","explanation":"'Justice'在此处表达抽象概念的泛指，代表整体理念而非某一具体情境中的正义，因此使用零冠词。加'the'会变成特指（例如：the justice delivered in this case）。","instruction":"选择正确答案，注意泛指与特指的区别。","correctIndex":3},{"type":"choice","options":["has","have","had","is"],"sentence":"The majority of the world's languages ___ never been written down.","subSkill":"advanced_quantifiers_the_majority_a_number_of","explanation":"'The majority of + 复数名词（languages）'作主语时，谓语动词与of后的名词保持一致，因为languages是复数，所以用'have'而非'has'。","instruction":"选择正确答案，注意'the majority of'的动词一致性。","correctIndex":1},{"type":"choice","options":["A great deal of","A large number of","A majority of","Many"],"sentence":"___ fieldwork has been devoted to studying endangered dialects in recent years.","subSkill":"advanced_quantifiers_the_majority_a_number_of","explanation":"'Fieldwork'是不可数名词，只能与修饰不可数名词的量词搭配。'A great deal of'修饰不可数名词，用法正确。'A large number of'和'many'修饰可数复数名词，不能用于此处。","instruction":"选择正确的量词填入空白处。","correctIndex":0},{"type":"choice","options":["All of","All","Each","Every"],"sentence":"___ the delegates at the conference supported the new language policy.","subSkill":"double_determiners_and_pre_determiners","explanation":"'All'直接修饰限定词'the'时，不需要加'of'（All the delegates）。'All of'后接代词（all of them）或在非正式语体中使用。'Each'和'every'后接单数名词，此处delegates是复数，不适用。","instruction":"选择正确答案，注意前置限定词的用法。","correctIndex":1},{"type":"choice","options":["a","an","the","(no article)"],"sentence":"The report examines ___ extent to which social media influences political opinion.","subSkill":"determiners_in_academic_noun_phrases","explanation":"'The extent to which...'是固定的学术书面语表达，用'the'是因为后置介词短语'to which...'限定了'extent'，使其成为特指。此处不可省略冠词。","instruction":"选择正确答案，注意冠词在学术名词短语中的用法。","correctIndex":2},{"type":"choice","options":["a","the","an","(no article)"],"sentence":"Scientists have long debated whether ___ consciousness can exist without a physical brain.","subSkill":"article_omission_in_abstract_nouns","explanation":"'Consciousness'在此句中指意识这一抽象概念的整体泛指，表达一般性论断而非特定情境中的意识，因此使用零冠词。这是学术写作中抽象名词泛指的典型用法。","instruction":"选择正确答案，辨别泛指与特指用法。","correctIndex":3},{"type":"choice","options":["Both of","Both","All of","Either"],"sentence":"___ the government and the opposition agreed that reform was necessary.","subSkill":"double_determiners_and_pre_determiners","explanation":"'Both'作前置限定词直接置于'the'之前时，不加'of'（both the government and...）。'Both of'后接代词（both of them）。'Either'表示两者之一，含义不同；'all of'用于三者或以上。","instruction":"选择正确答案，注意'both'作前置限定词的结构。","correctIndex":1},{"type":"choice","options":["The; has","A; has","A; have","The; have"],"sentence":"___ a number of studies conducted in the 1990s ___ found a link between diet and cognition.","subSkill":"advanced_quantifiers_the_majority_a_number_of","explanation":"'A number of + 复数名词（studies）'作量词短语，意为'若干'，谓语用复数'have'。若用'The number of studies'，则整体为单数，谓语用'has'，且含义变为'研究的数量'，不符合句意。","instruction":"选择正确答案，注意'a number of'与'the number of'的区别。","correctIndex":2}],"2":[{"type":"choice","options":["A great deal of the","Much of a","A large amount of the","The majority of"],"sentence":"___ previous research on bilingualism has focused primarily on children rather than adults.","subSkill":"advanced_quantifiers_the_majority_a_number_of","explanation":"'A great deal of the previous research'是最地道的学术书面语表达，'the'用于特指之前已有的研究成果。'The majority of'后通常接可数复数名词或表示群体的名词，'research'虽为不可数名词，此处用'a great deal of'更为精确自然。","instruction":"选择最符合学术书面语规范的选项。","correctIndex":0},{"type":"fill","sentence":"Philosophers have argued for centuries about the nature of (knowledge) ___.","subSkill":"article_omission_in_abstract_nouns","explanation":"'Knowledge'在此处表达抽象概念的泛指，指知识这一整体范畴，不需要任何冠词。加'the'会使其特指（例如：the knowledge gained in this experiment），改变句子含义。","instruction":"用括号中的词填写适当形式，注意是否需要冠词。","acceptableAnswers":["knowledge"]},{"type":"choice","options":["All","All of","Both of","Each of"],"sentence":"___ her three published books have been translated into more than twenty languages.","subSkill":"double_determiners_and_pre_determiners","explanation":"'All of her three books'：当'all'后接所有格限定词（her）而非'the'时，需要加'of'。结构为：all of + 所有格/代词 + 名词。若句子为'all the books'，则不需要'of'。'Both of'暗示只有两本，与'three'矛盾。","instruction":"选择正确答案，注意限定词叠加的顺序。","correctIndex":1},{"type":"fill","sentence":"___ (the / majority / of) linguists working in this field reject the strong version of the Sapir-Whorf hypothesis.","subSkill":"advanced_quantifiers_the_majority_a_number_of","explanation":"'The majority of + 复数名词'是正式书面语中表示'大多数'的标准量词结构。注意'the'是'majority'这一名词自身的限定词，而非后面'linguists'的，因此整个短语固定为'the majority of'。","instruction":"将括号内的词组填入空白，完成这个学术句子。","acceptableAnswers":["The majority of"]},{"type":"fill","sentence":"The committee reviewed ___ evidence presented at the hearing and concluded that further action was required.","subSkill":"generic_vs_specific_article_use","explanation":"'The evidence presented at the hearing'：'evidence'是不可数名词，但此处被后置分词短语'presented at the hearing'所限定，指的是听证会上呈交的那批特定证据，因此必须用'the'表示特指，不可省略。","instruction":"根据语境填写适当的冠词（a/an/the）或不填（用'-'表示零冠词）。","acceptableAnswers":["the"]},{"type":"choice","options":["all various the","all the various","the all various","various all the"],"sentence":"The paper analyses ___ assumptions underlying current approaches to language teaching.","subSkill":"double_determiners_and_pre_determiners","explanation":"限定词叠加的顺序是固定的：前置限定词（all）+ 冠词（the）+ 形容词（various）+ 名词。因此正确顺序是'all the various assumptions'。其他选项均违反了英语限定词的严格排列规则。","instruction":"选择最恰当的选项，完成这个学术风格的句子。","correctIndex":1},{"type":"fill","sentence":"Most researchers in this field believe that language acquisition is largely innate. (The majority ___)","subSkill":"advanced_quantifiers_the_majority_a_number_of","explanation":"'Most + 名词'可以改写为'The majority of + 名词'，两者在正式书面语中意义相同，但'the majority of'更具学术正式性。注意谓语动词'believe'保持复数形式不变，因为核心名词'researchers'为复数。","instruction":"改写句子，保持原意不变，使用括号中给出的词开头。（关键词转换）","acceptableAnswers":["The majority of researchers in this field believe that language acquisition is largely innate."]}],"3":[{"type":"fill","sentence":"___ power corrupts, and ___ power gained through deception corrupts absolutely.","subSkill":"generic_vs_specific_article_use","explanation":"第一空：'Power'泛指权力这一抽象概念，使用零冠词（类比常见格言的语言风格）。第二空：'the power gained through deception'被后置分词短语'gained through deception'限定，指通过欺骗获得的那种权力，是特指，必须用'the'。两空对比体现了同一名词在泛指与特指下冠词的截然不同用法。","instruction":"填写适当的冠词或零冠词（'-'）。注意两处空白须分别填写。","acceptableAnswers":["-","the"]},{"type":"fill","sentence":"Several studies have challenged this assumption. (A number ___)","subSkill":"advanced_quantifiers_the_majority_a_number_of","explanation":"'Several + 复数名词'可改写为'A number of + 复数名词'，后者在学术书面语中更为正式。注意谓语'have'保持复数，因为'a number of'的中心名词是复数的'studies'，而非单数的'number'。","instruction":"改写句子，保持原意不变，使用括号中给出的结构。（关键词转换）","acceptableAnswers":["A number of studies have challenged this assumption."]},{"type":"fill","sentence":"___ the qualitative and the quantitative data support the hypothesis, which strengthens the overall argument considerably.","subSkill":"double_determiners_and_pre_determiners","explanation":"'Both the qualitative and the quantitative data'：'both'作前置限定词，直接置于'the'之前，无需'of'（因为后接冠词'the'而非代词）。注意'both...and...'是并列结构，此处连接两个由'the'限定的形容词短语。整个主语'both...data'概念上为复数，谓语'support'使用复数形式。","instruction":"在空白处填入最恰当的限定词结构（使用'both'及适当冠词）。","acceptableAnswers":["Both"]},{"type":"fill","sentence":"Much of the criticism directed at the methodology has been addressed in the revised version. (A great ___)","subSkill":"advanced_quantifiers_the_majority_a_number_of","explanation":"'Much of + 限定词 + 不可数名词'可以改写为'A great deal of + 限定词 + 不可数名词'，后者在正式学术写作中更为常见。'criticism'是不可数名词，'the'保留以维持特指（指向特定方法论的那些批评）。谓语'has been addressed'保持单数被动语态不变。","instruction":"改写句子，保持原意不变。（关键词转换）","acceptableAnswers":["A great deal of the criticism directed at the methodology has been addressed in the revised version."]}],"4":[{"type":"choice","options":["A","An","The","Ø"],"sentence":"___ information provided in the latest report contradicts what scientists had previously assumed about climate change.","subSkill":"generic_vs_specific_article_use","explanation":"此处指的是\"最新报告中提供的信息\"，由后置定语\"provided in the latest report\"特指，因此使用定冠词the表示特指，而非泛指信息。","instruction":"选择正确的冠词或限定词，注意句子的泛指与特指语境。","correctIndex":2},{"type":"choice","options":["The majority of","A majority","Most of","The most of"],"sentence":"___ the students enrolled in the programme had prior research experience, which surprised the committee.","subSkill":"advanced_quantifiers_the_majority_a_number_of","explanation":"\"the majority of + 特指名词短语\"是学术写作中表示\"大多数某特定群体\"的规范用法。\"most of\"语法上也可接\"the students\"，但\"the majority of\"在学术正式语境中更为精确，且符合C1书面表达要求。","instruction":"选择正确的限定词，注意学术语境中名词短语的精确用法。","correctIndex":0},{"type":"choice","options":["a","the","an","Ø"],"sentence":"Researchers argue that ___ justice cannot be achieved without structural reform of existing institutions.","subSkill":"article_omission_in_abstract_nouns","explanation":"\"justice\"作为抽象名词在泛指意义上使用时，前面不加冠词。此句讨论\"公正\"这一概念本身，属于泛指，故不用任何冠词。","instruction":"判断下列句子中抽象名词前冠词的用法，选出正确选项。","correctIndex":3},{"type":"choice","options":["All of","All","Both of","Each of"],"sentence":"___ his numerous publications, only a handful have been cited more than a hundred times.","subSkill":"double_determiners_and_pre_determiners","explanation":"\"all of + 所有格限定词 + 名词\"构成双重限定词结构，表示\"他所有的众多出版物\"。此处\"all of his numerous publications\"中，all作为前置限定词修饰his，是标准书面用法。","instruction":"选择正确的前置限定词结构，注意双重限定词的书面用法。","correctIndex":0},{"type":"fill","sentence":"(A number of / The majority of) ___ scholars now accept that (Ø / the) ___ knowledge is socially constructed rather than objective.","subSkill":"article_omission_in_abstract_nouns","explanation":"第一空：\"a number of scholars\"表示\"若干学者\"，强调数量上的部分群体，适合此处非全称的陈述。第二空：\"knowledge\"作抽象名词泛指\"知识\"这一概念，前面不加冠词，加the则变为特指某一具体知识体系，改变句义。","instruction":"用括号中单词的正确形式或适当冠词填空，注意学术语境中的泛指与特指。","acceptableAnswers":["A number of","Ø"]},{"type":"fill","subSkill":"advanced_quantifiers_the_majority_a_number_of","explanation":"\"the majority of + 特指名词\"与\"most of the + 名词\"在正式书面语中意义相近，均表示\"大多数该特定群体中的成员\"。改写后主语变为\"the majority\"，谓语仍用复数were，因为the majority of...在此语境中指复数实体。","instruction":"改写句子，保持原意不变，使用括号中提示的结构填写空白处。（关键词转换练习）原句：Most of the recommendations in the report were ignored by policymakers. 改写：___ the recommendations in the report ___ ignored by policymakers.（使用 the majority of）","acceptableAnswers":["The majority of","were"]}],"5":[{"type":"fill","sentence":"It is widely acknowledged that ___ freedom of expression and ___ right to privacy are sometimes in direct conflict with each other.","subSkill":"generic_vs_specific_article_use","explanation":"第一空：\"freedom of expression\"作为抽象概念泛指，前面不加冠词。第二空：\"the right to privacy\"中the是固定搭配，表示\"隐私权\"这一特指的、有普遍认同的具体权利概念。两空对比体现了同一句中泛指与特指的精确区分。","instruction":"在空白处填入一个适当的冠词或限定词（可填Ø表示不加冠词），使句子在学术语境中语法正确且意义精确。","acceptableAnswers":["Ø","the"]},{"type":"choice","options":["Each of","All of","Both of all","Every of"],"sentence":"___ these findings have significant implications for public health policy.","subSkill":"double_determiners_and_pre_determiners","explanation":"\"all of + 限定词/代词\"是标准的双重限定词前置结构，表示\"所有这些发现\"。\"both of\"仅限两项；\"every of\"不合语法（every不与of连用）；\"each of\"语法正确但强调逐一，语义上不如\"all of\"适合此泛论性陈述。","instruction":"选择在正式学术写作中最恰当的表达，注意限定词在名词短语中的堆叠规则。","correctIndex":1},{"type":"fill","subSkill":"article_omission_in_abstract_nouns","explanation":"当动名词短语\"being honest\"转换为对应的抽象名词\"honesty\"时，该抽象名词在泛指意义上单独使用，前面不加冠词。加the则变为特指某一具体场合的诚实表现，改变了原句的泛指含义。","instruction":"改写下列句子，保持原意，使用括号中提示的词语，注意冠词与抽象名词的搭配。（关键词转换练习）原句：Being honest is essential in academic writing. 改写：___ is essential in academic writing.（使用 honesty）","acceptableAnswers":["Honesty"]},{"type":"fill","sentence":"___ considerable body of research confirms that ___ majority of urban populations now prefer digital communication, though ___ nature of this preference varies significantly across age groups.","subSkill":"determiners_in_academic_noun_phrases","explanation":"第一空：\"a considerable body of research\"是学术写作中表示\"相当数量的研究\"的固定搭配，body为可数单数名词，用不定冠词a。第二空：\"the majority of urban populations\"特指已被研究确认的特定群体，用the。第三空：\"the nature of this preference\"中nature被后置定语\"of this preference\"特指，故用the。","instruction":"在空白处填写适当的限定词或冠词，使这段学术语篇连贯准确。注意每空只填一个词。","acceptableAnswers":["A","the","the"]}]},"mission":{"title":"The Language Policy Brief","scenario":"国际教育委员会正在审查一项针对濒危语言的保护政策。委员会需要一份简短但正式的政策建议段落（约80-120词），要求：(1) 使用至少一个高级量词（the majority of / a number of / a great deal of）；(2) 正确区分抽象名词的泛指（零冠词）与特指（the）用法；(3) 使用至少一个前置限定词结构（如all the / both the）。","scaffolds":[{"hint":"用'the majority of'引导主语，填入一个表示'被记录的濒危语言'的名词短语（注意是特指还是泛指，选择适当冠词）。","prefix":"The majority of","suffix":"are currently at risk of disappearing within the next two generations.","example":"The majority of the documented endangered languages are currently at risk of disappearing within the next two generations.","grammarCheck":"advanced_quantifiers_the_majority_a_number_of"},{"hint":"在'Preserving'后填入一个抽象名词或名词短语，思考：此处表达的是泛指概念还是特指对象？注意'both the...and the...'结构中的前置限定词用法。","prefix":"Preserving","suffix":"requires both the commitment of national governments and the active involvement of local communities.","example":"Preserving linguistic diversity requires both the commitment of national governments and the active involvement of local communities.","grammarCheck":"double_determiners_and_pre_determiners"},{"hint":"用'a great deal of'引导一个关于'已投入的资金/努力/研究'的句子（注意搭配不可数名词），然后用'however'转折，体现'all the various'结构限定后续名词短语。","prefix":"A great deal of","suffix":"however, all the various recommendations made so far have yet to be implemented at a national level.","example":"A great deal of funding has been allocated to this initiative; however, all the various recommendations made so far have yet to be implemented at a national level.","grammarCheck":"advanced_quantifiers_the_majority_a_number_of"}],"description":"你是一名语言政策顾问，需要为国际教育委员会撰写一份正式简报，就保护濒危语言的政策提出建议。你的书面报告必须使用准确的冠词（泛指/特指）、高级量词以及正确的限定词结构，体现C1级学术书面语规范。","grammarType":"generic_vs_specific_article_use"},"discover":{"tip":"【核心语法：冠词的泛指vs特指 & 高级量词的书面用法】\n\n**一、泛指 vs 特指**\n泛指（Generic reference）指一类事物的整体概念，有三种形式：\n  (a) 零冠词 + 不可数名词或复数名词：Language is complex. / Dogs are mammals.\n  (b) a/an + 可数单数名词（代表一类）：A lion is a dangerous animal.\n  (c) the + 可数单数名词（正式/学术语境）：The lion is a dangerous animal.\n特指（Specific reference）指听话人/读者可以确定的具体所指，必须用the：\n  the language a person speaks（由定语从句限定）；the extent of this influence（由介词短语限定）。\n\n**二、抽象名词的零冠词**\n表示整体抽象概念时，不可数抽象名词通常不加冠词：love, knowledge, justice, language, freedom。加the后变为特指：the justice delivered by the court（该法庭所作的判决）。\n\n**三、高级量词（书面语）**\n  - the majority of + 复数名词/不可数名词（谓语与of后名词一致）\n  - a number of + 复数名词（谓语用复数）\n  - a great deal of / a good deal of + 不可数名词\n  - all (the) + 复数/不可数名词（强调全体）\n\n**四、前置限定词与限定词叠加（Pre-determiners）**\n前置限定词出现在冠词/限定词之前，顺序固定：\n  all / both / half + the/a/possessive + 名词\n  例：all the various assumptions；both the community and the public；half a century\n\n**常见错误：**\n1. 错误：the language shapes the way we think（泛指概念不应加the）→ 正确：Language shapes...\n2. 错误：the majority of the researchers has agreed（majority of后跟复数名词，谓语应为have）→ 正确：...have agreed\n3. 错误：all of the various / both of the communities（all/both直接修饰the时不需要of，除非后接代词）→ 正确：all the various；both the communities（但：all of them / both of them ✓）","story":{"text":"Language shapes the way we think — this is a claim that a number of cognitive scientists have debated for decades. The majority of researchers now accept that the particular language a person speaks influences certain aspects of perception, though the extent of this influence remains contested. What fascinates scholars is not language in general, but the specific mechanisms by which grammar encodes reality. Consider colour: English speakers use a single word for the concept of blue, whereas other languages divide that same spectrum into distinct categories. Such differences are not merely academic curiosities; they reveal how all the various cultural assumptions embedded in a language guide its speakers toward particular ways of interpreting experience. A great deal of recent fieldwork has been devoted to documenting endangered languages before they disappear, since each of these languages carries an irreplaceable body of knowledge. The researchers involved argue that the loss of even a small number of such languages would be an intellectual impoverishment for all of humanity. There is, after all, no other archive quite like a living language, and both the scientific community and the wider public have a stake in preserving linguistic diversity.","title":"The Invisible Hand of Language","highlights":["a number of","the majority of","the particular","a great deal of","all the various","a small number of","both the scientific community and"]},"questions":[{"options":["Because 'language' is a proper noun and proper nouns never take articles.","Because 'language' is used generically here — referring to language as an abstract concept in general, not a specific language.","Because the writer made a grammatical error; it should be 'A language'.","Because 'language' is uncountable and uncountable nouns never take articles."],"question":"In the sentence 'Language shapes the way we think', why is 'Language' used without an article?","explanation":"当名词表示抽象概念的泛指用法时，不加冠词。'Language'在此处指语言这一整体抽象概念，而非某种具体语言，因此使用零冠词。注意：uncountable名词在特指时仍可加the（如the language of this document），所以选项D的说法不准确。","correctIndex":1},{"options":["'The' is used because 'particular' always requires a definite article before it.","'The' signals generic reference — it refers to language in general across all people.","'The' signals specific reference — the noun phrase is narrowed down by the relative clause 'a person speaks', pointing to whichever specific language applies to that individual.","'The' is used because this is the first mention of 'language' in the passage."],"question":"The text uses 'the particular language a person speaks'. Why is 'the' used before 'particular language'?","explanation":"定冠词'the'在此处表达特指：后置定语从句'a person speaks'将'language'限定为某一具体语言（即某人实际说的那种语言），而非语言的泛称。这体现了C1水平的关键考点：the + 名词 + 限定性定语从句 = 特指。","correctIndex":2},{"options":["There is no meaningful difference; both phrases are interchangeable in formal writing.","'A number of researchers' means some/several researchers (quantifier), while 'the number of researchers' refers to a specific count or figure (noun phrase with the).","'A number of' is informal and should not appear in academic writing.","'The number of researchers' is always followed by a plural verb, whereas 'a number of researchers' takes a singular verb."],"question":"Which of the following best explains the difference between 'a number of researchers' and 'the number of researchers' in academic writing?","explanation":"'A number of + 复数名词'是量词短语，意为'若干、一些'，动词用复数（如：A number of studies have shown...）。'The number of + 复数名词'是特指某个数字/数量，整体作单数主语（如：The number of studies is increasing）。两者意义和句法功能截然不同，是高级书面英语的重要区分点。","correctIndex":1}]}},"10":{"levels":{"1":[{"type":"choice","options":["More / more","The more / the more","Most / most","The most / the most"],"sentence":"___ you read, ___ you learn.","subSkill":"double_comparatives_the_more_the_more","explanation":"双重比较结构固定格式为 'the + 比较级...the + 比较级'，表示两件事同步变化，因此选 'The more / the more'。","instruction":"选择正确答案，完成双重比较句。","correctIndex":1},{"type":"choice","options":["is","was","has","had"],"sentence":"This is the most challenging project our team ___ ever undertaken.","subSkill":"superlatives_with_present_perfect","explanation":"最高级与 'ever' 连用时，需要使用现在完成时 'has'，表示迄今为止所经历的范围内程度最高。'had' 是过去完成时，需要有更早的过去时间参照点。","instruction":"选择正确答案，完成最高级与现在完成时的搭配。","correctIndex":2},{"type":"choice","options":["nowhere near","very far","by far","so much"],"sentence":"Her new novel is ___ the best she has written.","subSkill":"degree_adverbs_with_adjectives_and_nouns","explanation":"'by far' 是修饰最高级的固定程度副词，意为'迄今为止最……'，位置固定在最高级之前。其余选项不与最高级搭配使用。","instruction":"选择正确的程度副词搭配。","correctIndex":2},{"type":"choice","options":["nowhere near","by far","the most","so much more"],"sentence":"The results were ___ as impressive as we had hoped.","subSkill":"as_as_constructions_with_inversion","explanation":"'nowhere near as...as' 是固定搭配，意为'远不及……那样'，用于强调程度上的巨大差距。'by far' 修饰最高级，不用于 as...as 结构。","instruction":"选择正确答案，完成 as...as 结构。","correctIndex":0},{"type":"choice","options":["anyone did finish it","anyone else did","anyone else finished it completely","did anyone else"],"sentence":"She finished the report faster than ___.","subSkill":"comparative_clauses_with_ellipsis","explanation":"比较从句中重复的谓语动词部分可省略，'than anyone else did' 省略了 'finish the report'，是最简洁且语法正确的形式。","instruction":"下列哪个句子正确使用了带省略的比较从句？","correctIndex":1},{"type":"choice","options":["Such","Very","So","More"],"sentence":"___ a performer had he become that the critics were speechless.","subSkill":"as_as_constructions_with_inversion","explanation":"'So + 形容词 + a/an + 名词 + 助动词 + 主语' 是书面英语中表示程度的倒装结构，'So accomplished a performer had he become...' 意为'他已成为如此出色的表演者'，触发主谓倒装。","instruction":"选择正确答案，完成倒装结构。","correctIndex":2},{"type":"choice","options":["The more people arrived, the worse the situation grew.","More people arrived, more the situation grew worse.","The most people arrived, the worst the situation grew.","As more people arrived, worst the situation grew."],"subSkill":"double_comparatives_the_more_the_more","explanation":"双重比较结构 'the more...the + 比较级' 可用来改写表示两种趋势同步变化的句子，且两个分句必须都用比较级，不能用最高级。","instruction":"选择与原句意思最接近的选项。原句：The situation grew worse as more people arrived.","correctIndex":0},{"type":"choice","options":["by far","nowhere near","the most","far much"],"sentence":"His performance last night was ___ as polished as his usual standard.","subSkill":"degree_adverbs_with_adjectives_and_nouns","explanation":"'nowhere near as...as' 表示'远不及……那样'，说明他昨晚的表现远未达到他平时的水准。'by far' 与最高级搭配，不与 as...as 连用。","instruction":"选择正确的程度副词，完成句子。","correctIndex":1}],"2":[{"type":"choice","options":["greater / more","more great / most","most / more","greater / much"],"sentence":"The ___ time pressure she faced, the ___ precisely she seemed to work.","subSkill":"double_comparatives_the_more_the_more","explanation":"双重比较结构要求两个分句均使用比较级。'great' 的比较级是 'greater'，'precisely' 的比较级需加 'more'，所以答案是 'greater / more'。","instruction":"选择正确答案，完成双重比较句。","correctIndex":0},{"type":"fill","sentence":"That is the most insightful speech the committee (hear) ___ in years.","subSkill":"superlatives_with_present_perfect","explanation":"最高级与表示迄今经验的时间状语 'in years' 连用时，必须使用现在完成时 'has heard'，表示在过去一段时间内所经历的最高程度。","instruction":"用括号内动词的正确形式填空，注意时态与最高级的搭配。","acceptableAnswers":["has heard"]},{"type":"fill","sentence":"This solution is (by far) ___ the most efficient approach available.","subSkill":"degree_adverbs_with_adjectives_and_nouns","explanation":"'by far' 作程度副词修饰最高级时，固定置于 'the most / the best' 等最高级结构之前，不可置于其后或其他位置。","instruction":"将括号内的词填入正确位置，完成程度副词搭配。","acceptableAnswers":["by far"]},{"type":"choice","options":["the first one performed did","did the first one","the first one did","the first one was performing"],"sentence":"The second prototype performed considerably better than ___.","subSkill":"comparative_clauses_with_ellipsis","explanation":"比较从句中为避免重复，可省略与主句相同的谓语动词主体，保留助动词 'did' 即可，形成 'than the first one did'，简洁自然。","instruction":"选择正确答案，完成带省略的比较从句。","correctIndex":2},{"type":"fill","sentence":"The manuscript was so rare that no library had ever catalogued it. -> So rare ___ the manuscript that no library had ever catalogued it.","subSkill":"as_as_constructions_with_inversion","explanation":"'So + 形容词' 置于句首时，触发主谓倒装，助动词 'was' 移至主语 'the manuscript' 之前，构成 'So rare was the manuscript that...' 的书面倒装句式。","instruction":"改写句子，保持原意，使用 as...as 倒装结构填入空白处。以 'So' 开头。","acceptableAnswers":["was"]},{"type":"choice","options":["every bit","by far","the most","nowhere far"],"sentence":"Her written analysis was ___ as thorough as her oral presentation.","subSkill":"as_as_constructions_with_inversion","explanation":"'every bit as...as' 是固定搭配，意为'与……完全一样……'，用于强调两者程度相同。'by far' 用于最高级，'nowhere near as...as' 表示差距极大，意思相反。","instruction":"选择正确的 as...as 程度结构。","correctIndex":0},{"type":"fill","sentence":"The (deep) ___ you engage with the material, the (well) ___ you retain it.","subSkill":"double_comparatives_the_more_the_more","explanation":"双重比较结构要求两个分句都使用比较级：'deep' 的比较级是 'deeper'，'well' 的比较级是 'better'，构成 'The deeper...the better' 的平行结构。","instruction":"用正确的比较级形式完成双重比较句。","acceptableAnswers":["deeper","better"]},{"type":"choice","options":["ever has","has ever","had ever","ever had"],"sentence":"It was the most complex negotiation the diplomat ___ conducted in her entire career.","subSkill":"superlatives_with_present_perfect","explanation":"最高级与 'ever' 连用时，'ever' 置于助动词 'has' 之后，过去分词之前，构成 'has ever conducted'。此处为现在完成时，强调在整个职业生涯中经历的最高程度。","instruction":"选择正确答案，完成句子。","correctIndex":1}],"3":[{"type":"fill","sentence":"The more investment (increase) ___, the faster economic growth (accelerate) ___.","subSkill":"double_comparatives_the_more_the_more","explanation":"双重比较结构中两个分句的动词须用适当的时态，此处描述普遍规律，用一般现在时。注意 'increases' 和 'accelerates' 均须加第三人称单数词尾 -s。","instruction":"改写句子，使用双重比较结构，保持原意。原句：As investment increases, economic growth accelerates proportionally. 以 'The more' 开头。","acceptableAnswers":["increases","accelerates"]},{"type":"fill","sentence":"The eastern branch generated more revenue than the western branch ___.","subSkill":"comparative_clauses_with_ellipsis","explanation":"比较从句中可省略与前文重复的动词短语，只保留助动词 'did' 替代 'generated'，使句子简洁而不失准确，这是书面英语中带省略的比较从句的标准用法。","instruction":"用关键词改写句子，保持原意。将以下句子改写为使用带省略的比较从句。原句：The eastern branch generated more revenue than the western branch generated.","acceptableAnswers":["did"]},{"type":"fill","sentence":"Critics noted that the director's latest film was ___ as ambitious as her debut, but ___ the most technically refined work she had produced.","subSkill":"degree_adverbs_with_adjectives_and_nouns","explanation":"第一空需要表示'与……一样……'的程度副词，'every bit as...as' 表示程度完全相同；第二空修饰最高级，'by far the most' 表示'迄今为止最……'，两者组合使句意连贯、对比清晰。","instruction":"用正确的程度副词填空，使句子逻辑通顺。从 'by far'、'nowhere near'、'every bit' 中选择。","acceptableAnswers":["every bit","by far"]},{"type":"fill","sentence":"Never before ___ the institution faced such a severe funding crisis.","subSkill":"as_as_constructions_with_inversion","explanation":"否定副词 'Never before' 置于句首时，触发主谓倒装，助动词 'had' 移至主语 'the institution' 之前，形成 'Never before had the institution faced...' 的书面倒装结构，强调程度的历史性。","instruction":"将句子改写为以 'Never before' 开头的倒装句，保持原意。原句：The institution had never before faced such a severe funding crisis.","acceptableAnswers":["had"]}],"4":[{"type":"choice","options":["More / more persuasive","The more / the more persuasive","The most / the most persuasive","More and more / persuasive"],"sentence":"___ you practise writing academic essays, ___ your arguments will become.","subSkill":"double_comparatives_the_more_the_more","explanation":"双重比较结构用 'the + 比较级 ... the + 比较级' 表示'越...越...'，两个分句须保持平行形式，故选 'The more / the more persuasive'。","instruction":"选择正确的双重比较结构完成句子。","correctIndex":1},{"type":"choice","options":["far more","much most","very more","too much more"],"sentence":"The research findings were ___ surprising than the team had anticipated, prompting a complete revision of the hypothesis.","subSkill":"degree_adverbs_with_adjectives_and_nouns","explanation":"'far' 是修饰比较级的程度副词，表示程度上'远远更加'，与 'more' 搭配正确。'very' 不能修饰比较级，'much most' 和 'too much more' 语法错误。","instruction":"选择最符合句意的程度副词搭配。","correctIndex":0},{"type":"choice","options":["expected","expecting","was expected it","had it expected"],"sentence":"The revised policy proved far more effective in reducing carbon emissions than ___ initially.","subSkill":"comparative_clauses_with_ellipsis","explanation":"比较从句中可省略重复成分，完整形式为 'than had been expected initially'，省略后保留 'expected'，表示'比最初预期的有效得多'。","instruction":"选择正确的含省略的比较从句结构。","correctIndex":0},{"type":"choice","options":["the most severe","a most severe","the more severe","most severest"],"sentence":"This is ___ drought the region has experienced in over a century.","subSkill":"superlatives_with_present_perfect","explanation":"最高级表示在特定范围内程度最高，通常与 'the' 连用，且与现在完成时 'has experienced' 搭配，表示'有史以来经历过的最严峻的旱灾'。","instruction":"选择正确的最高级与现在完成时搭配。","correctIndex":0},{"type":"fill","sentence":"As (be) ___ the case in many developing economies, rapid urbanisation has strained public infrastructure.","subSkill":"as_as_constructions_with_inversion","explanation":"'As is the case in...' 是固定的倒装结构，主语 'the case' 后置，助动词 'is' 置于主语前，表示'正如在许多发展中经济体中的情况一样'。","instruction":"用括号中词语的正确形式填空，构成含倒装的 as...as 结构。","acceptableAnswers":["is"]},{"type":"fill","sentence":"Economists have observed that ___ a country invests in education, ___ its long-term GDP growth tends to be.","subSkill":"double_comparatives_the_more_the_more","explanation":"双重比较结构 'the more...the + 比较级' 表示两者之间的正向关联：教育投入越多，GDP增长趋势越强劲。两个空格分别填入对应的比较级引导词。","instruction":"用适当的双重比较结构填空，使句子完整且符合语境。","acceptableAnswers":["the more","the stronger"]}],"5":[{"type":"fill","sentence":"___ abundant the data becomes, ___ difficult analysts find it to identify meaningful patterns.","subSkill":"double_comparatives_the_more_the_more","explanation":"改写使用双重比较 'The more...the more...' 结构，将原句中的 'increasingly difficult' 和 'more abundant' 转化为平行的比较级分句，保持语义不变。","instruction":"用正确形式填空，构成双重比较结构，使两句话意思相同。原句：As data becomes more abundant, analysts find it increasingly difficult to identify meaningful patterns. 改写句：___ data becomes, ___ analysts find it to identify meaningful patterns.","acceptableAnswers":["The more","the more"]},{"type":"fill","sentence":"The policy's implementation turned out to be (significantly / effective) ___ than any previous initiative in the sector, according to the annual review.","subSkill":"degree_adverbs_with_adjectives_and_nouns","explanation":"'significantly' 是修饰比较级的程度副词，'effective' 变为比较级 'more effective'，合并为 'significantly more effective'，表示'比以往任何举措都明显更为有效'。","instruction":"用括号中词语的正确比较级形式及合适的程度副词填空，使句子语义完整。语境：一份分析报告指出某项政策的实施效果远超预期。","acceptableAnswers":["significantly more effective"]},{"type":"choice","options":["the most","a most","by far the most","far the most"],"sentence":"This stands as ___ comprehensive longitudinal study on urban migration patterns that any single research institution has undertaken.","subSkill":"superlatives_with_present_perfect","explanation":"'by far the most' 是书面语中强调最高级程度的标准搭配，意为'迄今为止最为全面的'，语气最强且语体正式。'a most' 表示'极为'但不构成最高级，'far the most' 缺少介词 'by'，语法不完整。","instruction":"选择最准确、最符合书面语语体的选项完成句子。","correctIndex":2},{"type":"fill","sentence":"The relationship between regulatory stringency and innovation proved ___ complex than the researchers had originally (anticipate) ___.","subSkill":"comparative_clauses_with_ellipsis","explanation":"第一空用程度副词 'far' 修饰比较级 'more complex'，构成 'far more complex'，强调程度差距极大。第二空在 'had' 之后用过去分词 'anticipated'，构成过去完成时，表示研究者在此之前的预期。","instruction":"根据语境，用正确结构填空。语境：一篇经济学论文指出，市场监管的严格程度与创新活动之间存在相关性，且实际影响比研究者起初预计的要复杂得多。","acceptableAnswers":["far more","anticipated"]}]},"mission":{"title":"学术书评：语言与思想","scenario":"你是大学英语系学生，受邀为校学报撰写一篇学术书评。书名为 'The Evolving Mind: Language Acquisition Reconsidered'，你需要将它与你读过的其他语言学著作进行比较，客观评价其学术贡献。书评风格应正式、精准，体现书面学术英语的特征。","scaffolds":[{"hint":"用最高级 + 现在完成时，评价该书在同类著作中的地位。在最高级形容词处填入你的评价词，如 'rigorous'、'compelling'、'thoroughly researched' 等。","prefix":"This is by far the most","suffix":"I have read in recent years.","example":"This is by far the most rigorously argued book on language acquisition I have read in recent years.","grammarCheck":"superlatives_with_present_perfect"},{"hint":"完成双重比较结构。在空白处填入 'the more + 形容词/副词 + 主语 + 动词'，例如 'the more far-reaching' 或 'the more significant'。","prefix":"The more deeply one engages with the author's central thesis,","suffix":"the implications become for contemporary linguistics.","example":"The more deeply one engages with the author's central thesis, the more profound the implications become for contemporary linguistics.","grammarCheck":"double_comparatives_the_more_the_more"},{"hint":"使用 'So + 形容词 + a/an + 名词 + 助动词 + 主语 + that...' 的倒装结构。例如：'So original an approach has the author taken that...'","prefix":"So original","suffix":"that it challenges assumptions no previous scholar had dared to question.","example":"So original an approach has the author taken that it challenges assumptions no previous scholar had dared to question.","grammarCheck":"as_as_constructions_with_inversion"}],"description":"你将为一本关于语言习得的学术著作撰写一篇简短书评（约120词），发表于大学学报。书评需要将该书与同领域其他著作进行比较，评价其论点的深度与创新性。请在书评中自然运用本单元的比较结构：双重比较、最高级与现在完成时、程度副词搭配及倒装结构。","grammarType":"double_comparatives_the_more_the_more"},"discover":{"tip":"**C1级比较结构核心要点**\n\n**1. 双重比较（the more...the more）**\n表示两种变化同步发生：'The harder you work, the better the results become.' 两个分句均须用比较级，且第一个分句的主谓通常省略助动词以外的成分。\n常见错误：*The more she practised, the more she played effortlessly.* — 副词 'effortlessly' 应紧跟 'the more'，即 'the more effortlessly she played'。\n\n**2. 带省略的比较从句（comparative clauses with ellipsis）**\n为避免重复，比较从句中重复部分可省略：'She played more beautifully than anyone [had] expected [her to play].' 省略须保证意思清晰，不可造成歧义。\n\n**3. 最高级与现在完成时连用（superlatives with present perfect）**\n最高级常与 'ever' 或时间状语搭配现在完成时，强调在迄今为止的经验范围内：'It is the best performance I have ever seen.' 注意：不能用一般过去时替换，*It is the best performance I saw.* 语义不完整。\n\n**4. 程度副词的搭配（degree adverbs）**\n'by far'（迄今为止最...）、'nowhere near'（远不及）、'quite'（相当）等程度副词在书面语中位置固定：'by far the most' / 'nowhere near as...as' / 'quite as...as'。切勿将 'by far' 置于最高级之后。\n\n**5. as...as结构中的倒装（as...as with inversion）**\n当 'so/as + 形容词' 前置用于强调时触发倒装：'So dedicated a student was she that...' / 'Never before had the hall witnessed such a scene.' 这是书面正式语体的特征，口语中罕用。","story":{"text":"Elena had spent years studying classical piano, and the more she practised, the more effortlessly she played. Her teacher, a remarkably patient woman named Professor Adler, once remarked that Elena was by far the most dedicated student she had ever taught in thirty years of teaching. As Elena approached her final conservatory recital, the pressure grew heavier than she had anticipated. She was nowhere near as calm as her fellow students appeared to be. The longer she waited backstage, the more intensely her nerves took hold. Yet the moment her fingers touched the keys, something shifted. So accomplished a performer had she become that the audience fell completely silent within seconds. Never before had the concert hall witnessed quite as moving a debut as Elena delivered that evening. The critics agreed that she had played more beautifully than anyone expected, and the more glowing their reviews became, the more confidently she stepped into her future career. Professor Adler said that Elena was quite simply the most gifted musician the conservatory had produced in a decade.","title":"The Art of Mastery","highlights":["the more she practised, the more effortlessly she played","by far the most dedicated student she had ever taught","nowhere near as calm as","the longer she waited, the more intensely","so accomplished a performer had she become","never before had","quite as moving a debut as","more beautifully than anyone expected","the most gifted musician the conservatory had produced"]},"questions":[{"options":["She was nowhere near as calm as her fellow students appeared to be.","The longer she waited backstage, the more intensely her nerves took hold.","By far the most dedicated student she had ever taught.","Never before had the concert hall witnessed quite as moving a debut."],"question":"Which sentence from the story is an example of the 'double comparative' structure (the more...the more)?","explanation":"双重比较结构用 'the + 比较级...the + 比较级' 来表示两件事同步变化，句子中 'the longer...the more intensely' 正是这一结构的典型示例，意为'等待越久，紧张感越强烈'。","correctIndex":1},{"options":["A superlative structure with the present perfect.","An as...as construction with inversion.","Subject-verb inversion triggered by a fronted degree expression.","A double comparative parallel structure."],"question":"In the story, 'so accomplished a performer had she become' uses an unusual word order. What grammatical feature is this?","explanation":"当 'so + 形容词' 置于句首用于强调程度时，主谓需要倒装（inversion），形成 'so + adj + a/an + noun + 助动词 + 主语' 的结构，以突显程度之高，属于书面正式英语中的高级用法。","correctIndex":2},{"options":["Elena will be the best musician in the future.","Elena is currently the best musician studying there.","Elena is the best musician the conservatory has produced up to the present moment of speaking.","Elena was the best musician at one specific point in the past, but not necessarily overall."],"question":"What does 'the most gifted musician the conservatory had produced in a decade' tell us about the time frame?","explanation":"最高级与现在完成时（present perfect）连用，表示在从过去到现在的一段时间内所达到的最高程度。'the most gifted musician the conservatory had produced' 中虽用过去完成时（因处于过去语境），其含义仍是在该时间段内所及的极致，强调的是经验范围内的最高级。","correctIndex":2}]}},"11":{"levels":{"1":[{"type":"choice","options":["Because","Although","Whereas","Such"],"sentence":"___ the products are extremely expensive, consumers continue to buy them in large numbers.","subSkill":"concession_clauses_although_while_whereas","explanation":"'Although' 引导让步状语从句，表示'尽管'，意味着结果（大量购买）出人意料。'Because' 表原因，'Whereas' 表纯对比，'Such' 不能引导这类从句。","instruction":"选择正确的让步连词：这家公司的产品非常昂贵，____，消费者仍然大量购买。","correctIndex":1},{"type":"choice","options":["Although","So","Whereas","Such"],"sentence":"___ northern cities saw rising unemployment, southern cities experienced growth in employment.","subSkill":"concession_clauses_although_while_whereas","explanation":"'Whereas' 用于并列对比两个相反的事实，此处北方与南方的情况形成直接对比，没有'意外'含义。'Although' 暗示让步，语义不准确。","instruction":"选择能正确表达直接对比的连词：北方城市失业率上升，南方城市就业率却在增长。","correctIndex":2},{"type":"choice","options":["so strong","such a strong","such strong","so strongly"],"sentence":"There was ___ opposition to the new law that the government was forced to withdraw it.","subSkill":"result_clauses_such_that_so_that","explanation":"'such + 形容词 + 不可数名词 + that' 是正确结构（opposition 是不可数名词，不加 a/an）。'so' 后面直接跟形容词，不跟名词。'so strongly' 是副词，不能修饰名词。","instruction":"选择正确填入的词组，构成'such...that'结果从句：","correctIndex":2},{"type":"choice","options":["She spoke so quietly that nobody heard her.","She spoke such quietly that nobody heard her.","She spoke so quiet that nobody heard her.","She spoke so a quiet voice that nobody heard her."],"sentence":"Choose the correct sentence.","subSkill":"result_clauses_such_that_so_that","explanation":"'so + 副词 + that' 是正确结构（quietly 是副词修饰动词 spoke）。'such' 后需跟名词短语；'quiet' 是形容词不能修饰动词；'so a' 是错误搭配。","instruction":"以下哪个句子正确使用了'so...that'结构？","correctIndex":0},{"type":"choice","options":["That","It","What","Which"],"sentence":"___ we truly need is stricter environmental regulation.","subSkill":"cleft_sentences_for_emphasis_it_is_what","explanation":"What-cleft 结构：'What + 从句 + is/are + 强调信息'，此处用 'What' 引导名词性从句作主语，将焦点放在 'stricter environmental regulation' 上。'That' 不能单独引导这类主语从句。","instruction":"选出正确的分裂句（cleft sentence）：我们真正需要的是更严格的环保法规。","correctIndex":2},{"type":"choice","options":["which","what","who","where"],"sentence":"It was the government's prolonged inaction ___ caused the crisis to worsen.","subSkill":"cleft_sentences_for_emphasis_it_is_what","explanation":"'It is/was + 强调成分 + that/which + 谓语' 是标准分裂句结构。当强调成分指事物时，可用 'that' 或 'which'；'what' 不能用在此位置；'who' 只用于指人。","instruction":"选出正确的It分裂句：正是政府的迟迟不作为导致了危机的恶化。","correctIndex":0},{"type":"choice","options":["It is clear that standards have fallen.","What the report reveals is deeply troubling.","The fact that he lied was shocking.","That she succeeded surprised everyone."],"sentence":"Choose the sentence where a 'what'-clause functions as subject.","subSkill":"noun_clauses_as_subject_and_complement","explanation":"'What the report reveals' 是由 'what' 引导的名词性从句，在句中作主语，这是C1典型的强调性主语结构。选项C和D的主语从句由 'the fact that' 和 'that' 引导，不属于 what-cleft。","instruction":"下列哪个句子中名词性从句作了句子的真正主语（用 'what' 引导）？","correctIndex":1},{"type":"choice","options":["Although acknowledged","Having acknowledged","They acknowledged","Acknowledged that"],"sentence":"___ these limitations, the research team decided to proceed with the pilot study.","subSkill":"fronted_adverbial_clauses_for_cohesion","explanation":"'Having + 过去分词' 构成完成分词短语，前置于句首作状语，表示动作先于主句发生，是C1书面语中提升段落衔接性的典型手段。'Although acknowledged' 缺少主语，语法不完整。","instruction":"选择正确的前置状语从句形式，使段落衔接更自然：","correctIndex":1}],"2":[{"type":"choice","options":["Therefore","Nevertheless","Moreover","Consequently"],"sentence":"The report was thorough and well-researched. ___, the committee rejected its recommendations.","subSkill":"concession_clauses_although_while_whereas","explanation":"'Nevertheless' 是书面语让步副词，表示'尽管如此'，承接前文肯定内容，然后引出意外的相反结果。'Therefore' 和 'Consequently' 表结果，'Moreover' 表递进，均与语境矛盾。","instruction":"选择语义最准确的连接词：这份报告内容翔实，尽管如此，委员会仍然拒绝接受其建议。","correctIndex":1},{"type":"choice","options":["While urban areas boomed, rural areas declined.","While some progress has been made, serious inequalities persist.","While the north produces steel, the south produces textiles.","While he prefers coffee, she prefers tea."],"sentence":"Choose the sentence where 'while' expresses concession.","subSkill":"concession_clauses_although_while_whereas","explanation":"当 'while' 引导的从句与主句在同一主题上有'虽然…但仍然…'的意外关系时，表让步。选项B中'虽然有所进步，但不平等依然存在'是让步。其余选项均为纯粹的并列对比。","instruction":"以下哪个句子中 'while' 表达让步而非对比？","correctIndex":1},{"type":"fill","sentence":"The presentation was ___ compelling that the board approved the budget without debate.","subSkill":"result_clauses_such_that_so_that","explanation":"'so + 形容词（compelling）+ that + 结果从句' 是正确结构。'compelling' 是形容词，前用 'so' 而非 'such'；'such' 后须紧跟名词短语。","instruction":"用适当形式的结果从句连接词填空，使句子语法正确（填入一个词）：","acceptableAnswers":["so"]},{"type":"fill","sentence":"It was such ___ unexpected discovery that the scientists immediately published their findings.","subSkill":"result_clauses_such_that_so_that","explanation":"'such + a/an + 形容词 + 可数名词单数 + that' 是固定结构。'unexpected' 以元音音素开头，因此冠词用 'an'。此题考查考生是否掌握冠词在该结构中的必要性。","instruction":"用适当词语填空，完成 'such...that' 结果从句（填一个词）：","acceptableAnswers":["an"]},{"type":"fill","sentence":"___ prevented the project from succeeding ___ the lack of funding.","subSkill":"cleft_sentences_for_emphasis_it_is_what","explanation":"What-cleft 结构：'What + 从句动词 + 系动词 + 强调成分'。此处 'What prevented the project from succeeding' 作主语，'was' 作系动词，'the lack of funding' 是被强调的表语。","instruction":"将下列句子改写为 What-cleft 结构，保持原意。在空白处填入适当的词（每空一词）：原句：The lack of funding prevented the project from succeeding.","acceptableAnswers":["What","was"]},{"type":"fill","sentence":"___ ___ the discovery of penicillin that transformed modern medicine.","subSkill":"cleft_sentences_for_emphasis_it_is_what","explanation":"It-cleft 用于强调主语：'It was + 强调成分 + that + 其余谓语'。原句的主语 'the discovery of penicillin' 被移到强调位置，'transformed modern medicine' 留在 that 从句中。","instruction":"用 It-cleft 结构改写句子，强调画线部分。填入适当的词（每空一词）：原句：The discovery of penicillin transformed modern medicine.","acceptableAnswers":["It","was"]},{"type":"fill","sentence":"The central question is ___ urban planners can design cities that serve all income groups equally.","subSkill":"noun_clauses_as_subject_and_complement","explanation":"'whether' 引导名词性从句作系动词 'is' 后的表语，表示不确定性（'是否'）。该结构常见于C1学术和议论文写作中，此处不能用 'that'，因为问题本身含有不确定性。","instruction":"填入适当词语完成名词性从句，使其作句子表语（填一个词）：","acceptableAnswers":["whether"]},{"type":"fill","sentence":"___ ___ all the risks, the team submitted the final proposal.","subSkill":"fronted_adverbial_clauses_for_cohesion","explanation":"'Having + 过去分词' 表示分词动作（考虑风险）发生在主句动作（提交提案）之前，是正式书面语中前置状语的标准形式，替代笨重的 'After they had considered' 从句。","instruction":"用分词短语改写前置状语从句，使段落衔接更正式自然（填入两个词，每空一词）：原句：After the team had considered all the risks, they submitted the final proposal.","acceptableAnswers":["Having","considered"]}],"3":[{"type":"fill","sentence":"Strong ___ the evidence ___, the jury found the defendant not guilty.","subSkill":"concession_clauses_although_while_whereas","explanation":"'形容词/副词 + as + 主语 + 动词' 是C1让步从句的倒装结构（concessive inversion），等同于 'Although the evidence was strong'。这是比 'although' 更正式的书面语表达方式。","instruction":"用关键词转换法改写句子，保持原意。在空白处填入适当词语（每空一词）：原句：Although the evidence was strong, the jury found the defendant not guilty.","acceptableAnswers":["as","was"]},{"type":"fill","sentence":"It was ___ ___ noise that residents three streets away could hear it.","subSkill":"result_clauses_such_that_so_that","explanation":"将 'so + 形容词' 转换为 'such + 形容词 + 名词'：'so loud' → 'such loud noise'。注意 'noise' 是不可数名词，不加 'a'。两种结构意义相同，但词类安排不同。","instruction":"关键词转换：用 'such...that' 改写句子，保持原意（每空一词）：原句：The noise was so loud that residents three streets away could hear it.","acceptableAnswers":["such","loud"]},{"type":"reorder","words":["so","severe","were","the","consequences","that","parliament","convened","an","emergency","session"],"subSkill":"result_clauses_such_that_so_that","explanation":"'So + 形容词 + 倒装（助动词/系动词 + 主语）+ that + 结果从句' 是C1强调性倒装结构，将程度副词 'so severe' 提前，谓语倒装，具有强烈的修辞强调效果，常见于正式书面语。","instruction":"将以下词语重新排列，构成一个语法正确、使用'so...that'倒装的C1书面句：","correctSentence":"So severe were the consequences that parliament convened an emergency session."},{"type":"reorder","words":["what","the","investigation","uncovered","was","a","systematic","pattern","of","financial","misreporting"],"subSkill":"cleft_sentences_for_emphasis_it_is_what","explanation":"What-cleft 结构：'What + 主谓（the investigation uncovered）+ 系动词（was）+ 强调的名词短语'。'What' 引导的从句作句子主语，'was' 后是被强调的核心信息，整句将焦点置于所发现的内容上。","instruction":"将以下词语重新排列，构成语法正确的 What-cleft 句子：","correctSentence":"What the investigation uncovered was a systematic pattern of financial misreporting."},{"type":"fill","sentence":"It ___ in the 1970s ___ researchers first identified this syndrome.","subSkill":"cleft_sentences_for_emphasis_it_is_what","explanation":"It-cleft 强调时间状语：'It was + in the 1970s（强调的时间成分）+ that + 其余句子成分'。原句的时间短语被提取到强调位置，'that' 引导其余信息构成关系从句。","instruction":"关键词转换：用 It-cleft 改写句子，强调画线成分 'in the 1970s'，保持原意（每空一词）：原句：Researchers first identified this syndrome in the 1970s.","acceptableAnswers":["was","that"]},{"type":"fill","sentence":"___ multinational corporations continue to avoid taxation in developing nations is a matter of serious international concern.","subSkill":"noun_clauses_as_subject_and_complement","explanation":"'That + 完整从句' 作句子主语，这是C1正式书面语中的高级结构。注意在口语中通常用 'It is a matter of concern that...' 来回避头重脚轻，但书面论文中直接用 'That-clause' 作主语是可以接受的正式选择。","instruction":"填入适当词语，完成名词性 'that' 从句作主语的正式结构（填一个词）：","acceptableAnswers":["That"]},{"type":"reorder","words":["having","examined","the","counterarguments","carefully","the","authors","nonetheless","maintain","their","original","position"],"subSkill":"fronted_adverbial_clauses_for_cohesion","explanation":"'Having + 过去分词 + 宾语/状语'构成前置完成分词短语，其逻辑主语须与主句主语一致（均为 the authors）。'Nonetheless' 在主句中进一步强化让步语义，使段落逻辑层次更加分明。","instruction":"将以下词语重新排列，构成含有前置让步分词短语的C1级书面句：","correctSentence":"Having examined the counterarguments carefully, the authors nonetheless maintain their original position."},{"type":"reorder","words":["whereas","conservative","economists","advocate","deregulation","progressive","scholars","argue","for","greater","state","intervention"],"subSkill":"concession_clauses_although_while_whereas","explanation":"'Whereas + 从句一，主句二' 结构将两种截然相反的立场并列对比。'Whereas' 引导的从句在句首，通过逗号与主句分隔。与 'although' 不同，'whereas' 不暗示任何一方的立场出人意料，是纯中性对比。","instruction":"将以下词语重新排列，构成一个使用 'whereas' 对比两种政策立场的正式书面句：","correctSentence":"Whereas conservative economists advocate deregulation, progressive scholars argue for greater state intervention."}],"4":[{"type":"choice","options":["Because","Although","So that","In order that"],"sentence":"___ the new policy reduced costs significantly, employee satisfaction dropped to its lowest level in a decade.","subSkill":"concession_clauses_although_while_whereas","explanation":"句子前后两部分形成对比：政策降低了成本，但员工满意度下降。although引导让步状语从句，表示\"尽管……但……\"，符合此处逻辑。because表原因，so that和in order that表目的，均不适合。","instruction":"选择最准确的让步连接词，使句子逻辑通顺。","correctIndex":1},{"type":"choice","options":["so ... that","such ... that","too ... to","enough ... that"],"sentence":"The report contained ___ many technical errors ___ the committee refused to accept it.","subSkill":"result_clauses_such_that_so_that","explanation":"so...that结构用于修饰形容词或副词（此处many是形容词修饰复数名词errors），表示\"如此……以至于……\"。such...that后接名词短语，结构为such + a/an + adj + noun，此处many errors不含冠词，所以选so...that。","instruction":"选择正确的结果连接词，完成句子。","correctIndex":0},{"type":"fill","sentence":"It was the lack of communication ___ (that/which) ultimately caused the project to fail, not the shortage of funding.","subSkill":"cleft_sentences_for_emphasis_it_is_what","explanation":"强调句型it is/was + 被强调成分 + that/which + 其余部分。此处被强调的是the lack of communication（名词短语，非人），用that连接最为正式；which在此语境下也可接受，但在书面C1写作中that更为标准。句末的not the shortage of funding进一步确认强调的焦点是沟通缺失，而非资金问题。","instruction":"根据括号中的提示，用适当的强调句型（cleft sentence）改写句子，填入空白处。","acceptableAnswers":["that"]},{"type":"fill","sentence":"___ (be) widely accepted that consistent feedback improves long-term performance.","subSkill":"noun_clauses_as_subject_and_complement","explanation":"句子使用形式主语it作句首，真正的主语是that引导的名词从句。be动词应用第三人称单数现在时is，与it呼应，构成it is widely accepted that...的固定结构，表示普遍认可的事实。这是C1书面英语中常见的正式句型。","instruction":"将括号内的动词用正确形式填入，构成名词从句作句子主语。","acceptableAnswers":["It is"]},{"type":"fill","sentence":"___ (despite / the team / face / severe budget cuts), they managed to deliver the project two weeks ahead of schedule.","subSkill":"fronted_adverbial_clauses_for_cohesion","explanation":"尽管despite看似连词，但它是介词，后接名词短语或动名词，而非完整从句。正确结构为despite + doing，即despite facing severe budget cuts。将其置于句首作前置状语，增强语篇连贯性，与主句形成让步对比关系。","instruction":"用适当的前置状语从句完成句子，使语篇更连贯。将括号中的词组组合成正确的从句结构填入空白处。","acceptableAnswers":["Despite facing severe budget cuts"]},{"type":"choice","options":["which","that","what","when"],"sentence":"It is only through sustained collaboration ___ meaningful social change can be achieved.","subSkill":"cleft_sentences_for_emphasis_it_is_what","explanation":"强调句型it is...that是固定结构，that在此作连接词引导后续分句，不能替换为which（which引导定语从句需有先行词）、what（what引导名词从句）或when（when强调时间，不适合此处强调方式的语境）。","instruction":"选择最恰当的选项，使强调句型语法正确且符合C1书面语风格。","correctIndex":1}],"5":[{"type":"reorder","words":["Such","was","the","complexity","of","the","case","that","even","senior","lawyers","struggled","to","interpret","the","legislation."],"subSkill":"result_clauses_such_that_so_that","explanation":"such...that结构表结果，当such置于句首时，句子发生倒装：such + be动词 + 名词短语 + that从句。此处such was the complexity of the case是倒装形式，正常语序为the complexity of the case was such that...。句首倒装是C1书面英语中表强调的高级手段。","instruction":"将以下词语排列成语法正确、语义连贯的C1级句子。","correctSentence":"Such was the complexity of the case that even senior lawyers struggled to interpret the legislation."},{"type":"fill","sentence":"___ northern regions experienced record rainfall this summer, the southern provinces suffered their worst drought in thirty years.","subSkill":"concession_clauses_although_while_whereas","explanation":"句子将两个地区的截然不同的情况并列对比：北方洪涝，南方干旱。whereas和while均可引导对比从句，强调两种情况的鲜明差异，是书面英语中表对比的标准用法。although也表让步，但侧重于\"尽管……仍然……\"，更适合同一主语的前后矛盾，不如whereas/while在此处准确。","instruction":"用适当的连接词填空，使让步关系准确表达。注意whereas与although在语义侧重上的区别。","acceptableAnswers":["Whereas","While"]},{"type":"fill","subSkill":"noun_clauses_as_subject_and_complement","explanation":"改写后句子使用what从句作主语（what surprised many observers），后接系动词was，再接that引导的名词从句作表语。此处that是名词从句的连接词，不可省略，因为省略后句子结构不够清晰。整个句式属于名词从句作表语，是C1书面英语的高级表达方式。","instruction":"改写句子，保持原意不变，使用括号中指定的句型结构。将改写后句子缺失的部分填入空白处。（关键词改写练习）\n原句：The government introduced the reform without consulting the public, which surprised many observers.\n改写：What surprised many observers was ___ the government introduced the reform without consulting the public.","acceptableAnswers":["that"]},{"type":"reorder","words":["Having","reviewed","all","available","evidence,","the","panel","concluded","that","further","investigation","was","unnecessary."],"subSkill":"fronted_adverbial_clauses_for_cohesion","explanation":"前置完成分词短语having reviewed all available evidence作状语，置于句首，与主语the panel共享同一逻辑主语（panel reviewed the evidence），增强语篇简洁性与连贯性。这是C1书面英语中表示先后动作关系的高级句型，避免了重复主语和啰嗦的连接词。","instruction":"将以下词语排列成前置状语从句开头的正式书面句子。","correctSentence":"Having reviewed all available evidence, the panel concluded that further investigation was unnecessary."},{"type":"choice","options":["It","That","What","Which"],"sentence":"___ is widely acknowledged is that access to quality education remains deeply unequal across different social groups.","subSkill":"noun_clauses_as_subject_and_complement","explanation":"句子需要一个引导名词从句的词作整个句子的主语。what引导名词从句时，本身充当从句中的主语或宾语（此处what = the thing that），整个what从句作主句主语，后接is widely acknowledged，再接that引导的表语从句。it作形式主语时，后面的结构应为it is...that，与此句结构不符；that引导从句通常不单独作主语（除非后接完整句子）；which需要先行词。","instruction":"选择最恰当的选项，使句子语法正确并符合C1书面语的语义逻辑。","correctIndex":2},{"type":"fill","subSkill":"cleft_sentences_for_emphasis_it_is_what","explanation":"强调句型it was + 被强调成分 + that + 其余句子。原句强调失业原因是自动化而非经济衰退，改写时保留否定对比结构not the recession在被强调部分内，再用that引出其余句子成分。两个空格分别填not和that，缺一不可，才能保持原句的对比强调语义。","instruction":"关键词改写练习：改写下列句子，保持原意，使用it...that强调句型。将缺失部分填入空白处。\n原句：The introduction of automation, not the recession, led to widespread job losses.\n改写：It was the introduction of automation, ___ the recession, ___ led to widespread job losses.","acceptableAnswers":["not","that"]}]},"mission":{"title":"The Future of Artificial Intelligence: A Formal Argument","scenario":"你的编辑要求你就以下立场写一段（约120词）正式论证：'人工智能带来的挑战与其经济效益同样重要，政策制定者必须正视这一矛盾。'请使用正式书面语，避免口语化表达，并确保连接词的语义与逻辑关系完全匹配。","scaffolds":[{"hint":"用 What-cleft 引出你认为被低估的核心问题，例如：automation's uneven impact across income groups（自动化对不同收入群体的不均等影响）。","prefix":"What policymakers consistently underestimate is","suffix":", despite the considerable economic data already available.","example":"What policymakers consistently underestimate is the speed at which mid-skill jobs are being eliminated, despite the considerable economic data already available.","grammarCheck":"cleft_sentences_for_emphasis_it_is_what"},{"hint":"用 'although' 承认AI的好处（让步），再用 'such...that' 描述不平等或风险的严重程度（结果）。注意中间需要自己补充主句的主语和谓语。","prefix":"Although artificial intelligence generates measurable productivity gains,","suffix":"to such a degree that urgent legislative intervention is warranted.","example":"Although artificial intelligence generates measurable productivity gains, the displacement of low-income workers has widened existing inequalities to such a degree that urgent legislative intervention is warranted.","grammarCheck":"concession_clauses_although_while_whereas"},{"hint":"用 It-cleft 强调真正决定公平转型的因素（不是技术本身，而是…）。在 'but' 后填入你认为更关键的因素，如 'but the political will to redistribute its benefits'。","prefix":"It is not the technology itself,","suffix":"that will ultimately determine whether this transition is managed equitably.","example":"It is not the technology itself, but the political will to redistribute its benefits equitably across society, that will ultimately determine whether this transition is managed equitably.","grammarCheck":"cleft_sentences_for_emphasis_it_is_what"}],"description":"你将扮演一位为国际政策期刊撰稿的分析师。请运用本单元所学的高级连接词和话语标记，就人工智能对劳动力市场的影响写一篇结构清晰的论证段落。要求在段落中准确运用至少三种不同的C1连接结构（如分裂句、让步从句、结果从句等），展示书面英语的衔接性和论证深度。","grammarType":"cleft_sentences_for_emphasis_it_is_what"},"discover":{"tip":"**C1连接词精准辨析**\n\n**1. 让步 vs 对比**\n- 'Although / Even though + 从句' 表示让步：结果出人意料。('Although she trained hard, she lost.' — 努力却输了，令人意外。)\n- 'While / Whereas + 从句' 表示直接对比：两个事实并列，无意外含义。('Whereas city rents rose, rural rents fell.' — 纯粹对比两种走势。)\n- 常见错误：用 'although' 替换 'whereas' 来表达纯对比，导致语义偏差。\n\n**2. 结果从句：so...that vs such...that**\n- 'so + 形容词/副词 + that'：She was so tired that she collapsed.\n- 'such + (a/an) + 形容词 + 名词 + that'：It was such a tiring day that she collapsed.\n- 常见错误：'so a big problem that...' ✗ → 名词前须用 'such'。\n\n**3. 名词性从句作主语/表语**\n- 'What + 从句 + is/are + that-clause'：What concerns us is that standards are falling.\n- 该结构把焦点放在 'that' 后的信息上，是C1书面语中常见的强调手段。\n\n**4. 前置状语从句的衔接功能**\n- 分词短语前置（Having acknowledged... / Given that...）在段落间起衔接作用，避免生硬的句间转换，是C1学术写作的典型特征。\n\n**5. 分裂句（Cleft sentences）**\n- 'It is/was + 强调成分 + that/who + 其余部分'：It is governments that must act.\n- 'What-cleft'：What we need is better regulation.\n- 两者均可将特定信息置于焦点位置，但结构不可混用。","story":{"text":"It is the relentless pace of technological change that most defines our era, yet the consequences of this change remain deeply contested. Although silicon valley corporations generate enormous wealth, such wealth rarely trickles down to displaced workers in a straightforward manner. What surprises many economists is that productivity gains do not automatically translate into higher wages. The gap between executive pay and median salaries has widened to such a degree that several governments have introduced emergency legislation. Whereas traditional industries offered stable, lifelong employment, the gig economy provides flexibility at the cost of security. Having acknowledged these trade-offs, policymakers still struggle to craft regulation that balances innovation with social protection. So rapid is the pace of automation that entire professional categories — accountants, radiologists, paralegals — face partial obsolescence within a single generation. While critics argue that new jobs will emerge to replace the old ones, the transition period itself causes measurable hardship. What the data ultimately reveal is that progress is never neutral: it is always somebody who bears the hidden cost, even when the aggregate statistics look encouraging.","title":"The Price of Progress","highlights":["It is","that","Although","such...that","What surprises","is that","Whereas","Having acknowledged","So rapid is","While","What the data reveal","it is always somebody who"]},"questions":[{"options":["It introduces a result clause","It forms a cleft sentence to place extra emphasis on the subject","It begins a concession clause contrasting two ideas","It creates a noun clause acting as the grammatical subject"],"question":"In the sentence 'It is the relentless pace of technological change that most defines our era', what grammatical function does 'It is ... that' serve?","explanation":"这是一个分裂句（cleft sentence）结构：It is + 强调成分 + that + 句子其余部分。其作用是把焦点集中在 'the relentless pace of technological change' 上，而非动词或其他成分。","correctIndex":1},{"options":["Although silicon valley corporations generate enormous wealth, such wealth rarely trickles down.","So rapid is the pace of automation that entire professional categories face obsolescence.","The gap has widened to such a degree that several governments have introduced emergency legislation.","What surprises many economists is that productivity gains do not automatically translate into higher wages."],"question":"Which sentence from the story correctly uses a 'such...that' result clause?","explanation":"'such + 名词短语 + that + 结果从句'是固定的结果状语从句结构，表示程度之深以至于产生某种后果。选项A中的 'such' 是指示限定词，选项B是 'so + 形容词 + 倒装' 结构，选项D是名词性从句。","correctIndex":2},{"options":["Concession: the second clause unexpectedly contradicts the first","Direct contrast: two situations are placed side by side as opposites","Cause and result: the first clause explains why the second is true","Addition: the second clause adds a further supporting point"],"question":"The story uses 'Whereas traditional industries offered stable employment, the gig economy provides flexibility at the cost of security.' What relationship does 'whereas' signal?","explanation":"'Whereas' 表示直接对比（direct contrast），将两个相对立的事实并列呈现，强调它们之间的差异，而不含'虽然…但意外地…'的让步含义。让步连词（如although/even though）暗示结果出乎意料，whereas则是中性的对比。","correctIndex":1}]}},"12":{"levels":{"1":[{"type":"choice","options":["due","owing","because","resulting"],"sentence":"The committee decided to postpone the event ___ to adverse weather conditions.","subSkill":"open_cloze_grammar_word_selection","explanation":"'due to' 是介词短语，后接名词短语，表示原因，适合书面正式语境。'owing to' 同样正确但此处 'due to' 更为常见；'because' 后必须接从句而非名词短语；'resulting' 需要搭配 'in' 或 'from'，且意义不同。","instruction":"选择最合适的词，完成语篇填空。","correctIndex":0},{"type":"choice","options":["at","in","by","on"],"sentence":"She was ___ no means the least experienced candidate at the interview.","subSkill":"open_cloze_grammar_word_selection","explanation":"'by no means' 是固定副词短语，意为'绝不，一点也不'，用于强调否定。其他介词均不能与 'no means' 搭配构成此固定表达。","instruction":"选择最合适的词，完成语篇填空。","correctIndex":2},{"type":"choice","options":["responsibleness","responsibility","responsibly","responsive"],"sentence":"The report highlighted the ___ (responsible) of local authorities to maintain public infrastructure.","subSkill":"word_formation_affixation_and_conversion","explanation":"'responsibility' 是 'responsible' 的名词形式，由形容词词干加后缀 '-ity' 构成（注意词根拼写变化：responsible → responsibility）。'responsibleness' 不是标准英语词汇；'responsibly' 是副词；'responsive' 是另一个形容词，意义不同。","instruction":"选择正确的构词形式填入空格。","correctIndex":1},{"type":"choice","options":["at","not","in","by"],"sentence":"The findings were significant, ___ least because they challenged decades of accepted theory.","subSkill":"open_cloze_grammar_word_selection","explanation":"'not least because' 是固定连接短语，意为'尤其因为，特别是因为'，用于强调某个理由在诸多原因中的重要性。其他选项均不能构成此固定搭配。","instruction":"选择最合适的词，完成语篇填空。","correctIndex":1},{"type":"choice","options":["decide","decisive","decision","decidedly"],"sentence":"The government's ___ (decide) to cut funding was met with widespread protest.","subSkill":"word_formation_affixation_and_conversion","explanation":"空格前有定语（government's），需要名词作宾语的中心词，因此选 'decision'（名词，由动词 decide 加后缀 -sion 构成）。'decisive' 是形容词；'decidedly' 是副词；'decide' 是动词，不能跟在所有格后作名词用。","instruction":"选择正确的构词形式填入空格。","correctIndex":2},{"type":"choice","options":["with","by","in","under"],"sentence":"The artist was said to have worked ___ obsessive dedication throughout her final years.","subSkill":"open_cloze_grammar_word_selection","explanation":"'work with dedication/obsession' 是固定搭配，介词 'with' 用来表示伴随的方式或态度。'by' 通常表示手段；'in' 和 'under' 在此语境中均不符合语法规范。","instruction":"选择最合适的词，完成语篇填空。","correctIndex":0},{"type":"choice","options":["Remove 'of' after Despite","Replace 'Despite' with 'Although'","Change 'involved' to 'involving'","Change 'on schedule' to 'in schedule'"],"sentence":"Despite of the difficulties involved, the team completed the project on schedule.","subSkill":"error_correction_in_written_text","explanation":"'Despite' 是介词，直接后接名词或动名词短语，不需要 'of'。'Despite of' 是常见错误；正确用法为 'Despite the difficulties...' 或使用从属连词 'Although the difficulties were involved...'","instruction":"找出句中的错误并选出正确改法。","correctIndex":0},{"type":"choice","options":["in","on","at","by"],"sentence":"The results were ___ accordance with earlier predictions made by the research team.","subSkill":"open_cloze_grammar_word_selection","explanation":"'in accordance with' 是固定介词短语，意为'与...一致，按照...'，是正式书面语常用表达。其他介词均不能与 'accordance with' 搭配使用。","instruction":"选择最合适的词，完成语篇填空。","correctIndex":0}],"2":[{"type":"choice","options":["Had she submitted","Has she submitted","She having submitted","If submitted"],"sentence":"___ the application earlier, she might have secured a place.","subSkill":"key_word_transformation_paraphrase","explanation":"此题考查第三条件句的倒装转换。省略 'if' 后，将助动词 'had' 移至主语前构成倒装：'Had she submitted...' 等同于 'If she had submitted...'。这是书面正式语体中常见的高级句型结构，常出现在关键词句转换题型中。","instruction":"选择最合适的选项完成关键词句转换，使两句意思相同。原句：'If she had submitted the application earlier, she might have secured a place.'","correctIndex":0},{"type":"fill","sentence":"The exhibition attracted an (exception) ___ large number of international visitors.","subSkill":"word_formation_affixation_and_conversion","explanation":"'exceptionally' 是副词，由形容词 exceptional 加后缀 -ly 构成，用于修饰形容词 'large'。注意词根拼写：exception（名词）→ exceptional（形容词）→ exceptionally（副词）。不能用形容词 'exceptional' 修饰另一个形容词。","instruction":"用括号内词的正确形式填空（构词变形）。","acceptableAnswers":["exceptionally"]},{"type":"choice","options":["Replace 'did...been made' with 'had...been made'","Replace 'No sooner' with 'Not until'","Change 'began' to 'had begun'","Remove 'than' and replace with 'when'"],"sentence":"No sooner did the announcement been made than the shares began to fall sharply.","subSkill":"error_correction_in_written_text","explanation":"'No sooner...than' 倒装结构中，主句使用过去完成时（had + 主语 + 过去分词），而非一般过去时的助动词 did。正确结构为 'No sooner had the announcement been made than...'。'No sooner...when' 是常见错误，正确搭配必须用 'than'。","instruction":"找出句中的语法错误并选出正确改法。","correctIndex":0},{"type":"fill","sentence":"The charity relies entirely on the (generous) ___ of private donors to fund its operations.","subSkill":"word_formation_affixation_and_conversion","explanation":"'generosity' 是 'generous' 的名词形式，加后缀 -ity（注意词根拼写变化：generous → generosity）。空格前有定冠词 'the'，且句子需要名词作 'relies on' 的宾语，因此选名词形式。","instruction":"用括号内词的正确形式填空（构词变形）。","acceptableAnswers":["generosity"]},{"type":"choice","options":["with","for","by","at"],"sentence":"The legislation was introduced ___ the aim of reducing carbon emissions by thirty per cent.","subSkill":"open_cloze_grammar_word_selection","explanation":"'with the aim of' 是固定介词短语，意为'以...为目标，旨在'。'for the aim of' 不是标准英语搭配；'for the purpose of' 虽然意义相近但关键词是 'aim'，需搭配 'with'；'by' 和 'at' 在此均不适用。","instruction":"选择最合适的词，完成语篇填空。","correctIndex":0},{"type":"fill","sentence":"The reform is ___ known to have been deeply unpopular.","subSkill":"key_word_transformation_paraphrase","explanation":"此题考查被动语态与不定式完成式的结合。原句中的 'It is widely known that...' 可转换为 'The subject + is + adverb + known + to have been...'，其中 'to have been' 表示过去发生的事情（不定式完成式），'widely' 作副词修饰 'known'。","instruction":"完成关键词句转换，使新句与原句意思相同。关键词已给出。原句：'It is widely known that the reform was deeply unpopular.' 关键词：WIDELY","acceptableAnswers":["widely"]},{"type":"fill","sentence":"Critics argued that the policy was fundamentally (flaw) ___ and would ultimately fail.","subSkill":"word_formation_affixation_and_conversion","explanation":"'flawed' 是形容词，由名词 'flaw'（缺陷）加后缀 '-ed' 构成，意为'有缺陷的，有瑕疵的'。空格在系动词 'was' 之后，需要形容词作表语。'flawing' 是现在分词，不适用；'flaw' 是名词或动词，不能直接作形容词。","instruction":"用括号内词的正确形式填空（构词变形）。","acceptableAnswers":["flawed"]},{"type":"choice","options":["Change 'would had been' to 'would be'","Change 'Were' to 'Was'","Change 'to improve' to 'improving'","Add 'if' before 'Were'"],"sentence":"Were the conditions to improve, the project would had been viable from a financial perspective.","subSkill":"error_correction_in_written_text","explanation":"'Were the conditions to improve...' 是以 were 开头的倒装虚拟条件句，表示对现在或将来的假设（相当于第二条件句）。主句应使用 'would + 动词原形'（would be），而非 'would had been'（过去完成时搭配错误，would 后接动词原形，不接 had）。","instruction":"找出句中的语法错误并选出正确改法。","correctIndex":0}],"3":[{"type":"fill","sentence":"Despite ___ the evidence, the jury remained unconvinced.","subSkill":"key_word_transformation_paraphrase","explanation":"'Despite' 是介词，后接名词短语而非从句。将 'although + 从句' 转换为 'despite + 名词短语' 时，通常使用 'the + 形容词 + nature of + 名词' 这一正式构式，即 'despite the compelling nature of the evidence'。直接写 'despite compelling evidence' 也可接受，但转换时应保留原句的完整语义。","instruction":"完成关键词句转换，使新句与原句意思相同。关键词已给出。原句：'Although the evidence was compelling, the jury remained unconvinced.' 关键词：DESPITE","acceptableAnswers":["the compelling nature of","the compellingness of"]},{"type":"fill","sentence":"The (innovate) ___ approach adopted by the research team proved to be (remark) ___ effective in reducing costs.","subSkill":"word_formation_affixation_and_conversion","explanation":"'innovative' 是形容词（innovate 动词 + -ive 后缀），修饰名词 'approach'；'remarkably' 是副词（remarkable 形容词 + -ly），修饰形容词 'effective'。注意 remarkable 去掉词尾 -e 再加 -ly 的拼写规则。","instruction":"用括号内词的正确形式填空（构词变形），每空一词。","acceptableAnswers":["innovative","remarkably"]},{"type":"reorder","words":["had","the","not","intervened","government","the","crisis","deepened","have","would"],"subSkill":"key_word_transformation_paraphrase","explanation":"此句为第三条件句的倒装形式：省略 if，将 had 提至句首，构成 'Had + 主语 + 过去分词' 结构，等同于 'If the government had not intervened...'。主句使用 'would have + 过去分词' 表示对过去的虚拟推断。","instruction":"将以下词语排列成正确的句子（倒装强调句）。","correctSentence":"Had the government not intervened, the crisis would have deepened."},{"type":"fill","sentence":"No sooner ___ the manuscript ___ she contacted her publisher.","subSkill":"key_word_transformation_paraphrase","explanation":"'No sooner...than' 结构要求主句使用过去完成时倒装（had + 主语 + 过去分词），从句使用一般过去时。完整句为 'No sooner had she finished the manuscript than she contacted her publisher.'。注意：'No sooner...when' 是错误搭配，必须用 'than'。","instruction":"完成关键词句转换，使新句与原句意思相同。关键词已给出。原句：'She finished the manuscript and then immediately contacted her publisher.' 关键词：SOONER","acceptableAnswers":["had she finished","than"]},{"type":"fill","sentence":"The committee expressed its (approve) ___ of the proposed amendments to the charter.","subSkill":"word_formation_affixation_and_conversion","explanation":"根据句子语境，委员会对修正案提出异议（后文暗示修正案未通过），因此需要 'disapproval'（不赞成，反对），由前缀 dis- + approve 的名词形式 approval 构成。单纯填 'approval' 意义相反，与语境矛盾。这类题目要求考生同时注意前缀的语义功能。","instruction":"用括号内词的正确构词形式填空。","acceptableAnswers":["disapproval"]},{"type":"reorder","words":["under","no","circumstances","personal","should","information","disclosed","be","to","third","parties"],"subSkill":"integrated_grammar_accuracy_review","explanation":"'Under no circumstances' 是否定副词短语置于句首时，引发主谓倒装：should 提至主语 personal information 之前，构成 'should + 主语 + 动词' 倒装结构。这类结构常出现在正式书面规定或警示语中，强调绝对禁止。","instruction":"将以下词语排列成正确的句子（强调否定倒装）。","correctSentence":"Under no circumstances should personal information be disclosed to third parties."},{"type":"fill","sentence":"The new regulations had far-reaching consequences, ___ least because they set a precedent for future environmental legislation across the region.","subSkill":"open_cloze_grammar_word_selection","explanation":"'not least because' 是固定副词短语，意为'尤其因为，特别是因为'，用于在列举原因时强调某一原因的重要性。其他功能词（at、in、by）均不能构成此短语。这是C1级正式书面语中频繁出现的连接表达。","instruction":"完成语篇填空，选择正确的功能词。原句描述一项政策的后果。","acceptableAnswers":["not"]},{"type":"reorder","words":["it","not","were","for","her","expertise","the","project","would","have","failed"],"subSkill":"key_word_transformation_paraphrase","explanation":"'Were it not for...' 是固定的虚拟条件倒装句，等同于 'If it were not for...' 或 'But for...'，表示对过去或现在的假设（此处结合 'would have failed' 说明是对过去的假设）。这一结构在C1书面语中极为常见，需要完整掌握其倒装形式及主句时态配合规则。","instruction":"将以下词语排列成正确的句子（综合语法）。","correctSentence":"Were it not for her expertise, the project would have failed."}],"4":[{"type":"fill","sentence":"The committee decided to postpone the project, ___ which all team members were informed by email.","subSkill":"open_cloze_grammar_word_selection","explanation":"固定搭配 informed of 表示被告知某事，of which 引导关系从句，修饰前文的决定，表示所有团队成员都被告知了这一决定。","instruction":"语篇填空：阅读句子，在空白处填入一个合适的语法词（介词、连词、助动词等），使句子语法正确、语义完整。","acceptableAnswers":["of"]},{"type":"fill","sentence":"The new regulations will come ___ force on the first day of next year, affecting all registered businesses.","subSkill":"open_cloze_grammar_word_selection","explanation":"固定短语 come into force 意为法规正式生效，是书面正式英语中的常用搭配，into 不可替换为其他介词。","instruction":"语篇填空：在空白处填入一个合适的语法词，使句子逻辑和语法均正确。","acceptableAnswers":["into"]},{"type":"fill","sentence":"The scientist showed remarkable (persist) ___ in pursuing her research despite repeated funding cuts.","subSkill":"word_formation_affixation_and_conversion","explanation":"此处需要名词形式作 remarkable 的宾语。persist 是动词，加后缀 -ence 变为名词 persistence，表示坚持不懈的品质。","instruction":"构词变形：根据括号中的词，用其正确的派生形式填写空白处，使句子语法正确。","acceptableAnswers":["persistence"]},{"type":"fill","sentence":"The manager's (decide) ___ to restructure the department came as a surprise to most employees.","subSkill":"word_formation_affixation_and_conversion","explanation":"此处需要名词短语作主语，decide 是动词，转化为名词 decision，表示一项决定。The manager's decision to do something 是固定结构。","instruction":"构词变形：根据括号中的词，用其正确的派生形式填写空白处。","acceptableAnswers":["decision"]},{"type":"fill","sentence":"It is thought that the ancient city was abandoned due to a severe drought. (believed)\nThe ancient city ___ ___ have been abandoned due to a severe drought.","subSkill":"key_word_transformation_paraphrase","explanation":"原句用 it is thought that 表示普遍认为，改写后用 is believed to have done 结构，表示对过去已发生事件的推测，to have been 体现过去时态。","instruction":"关键词句转换：用括号中的关键词改写句子，使新句子与原句意思相同，每空填一个词。","acceptableAnswers":["is","believed"]},{"type":"error","words":["Despite","of","the","heavy","rain,","the","outdoor","event","continued","as","planned."],"subSkill":"error_correction_in_written_text","correction":"Despite","errorIndex":1,"explanation":"Despite 是介词，后直接跟名词短语，不需要 of。正确用法是 Despite the heavy rain。若要用 of，则需改为 In spite of，两者意义相同但结构不同。","instruction":"书面纠错：下列句子中有一个词使用错误，找出错误并改正。"},{"type":"error","words":["The","report","was","criticized","for","it","lack","of","concrete","evidence."],"subSkill":"error_correction_in_written_text","correction":"its","errorIndex":5,"explanation":"此处 lack 是名词，前面需要所有格代词修饰，应用 its 而非主格 it。it lack of concrete evidence 语法不通，its lack of concrete evidence 才正确。","instruction":"书面纠错：下列句子中有一个词使用错误，找出错误并改正。"},{"type":"choice","options":["did","had","was","does"],"sentence":"Not until the final results were announced ___ the true scale of the problem become clear to everyone.","subSkill":"integrated_grammar_accuracy_review","explanation":"Not until 置于句首时，主句需要倒装。该情景描述过去某时刻事情变得清晰，用一般过去时，倒装结构为 did + 主语 + 动词原形，因此选 did。","instruction":"语法综合选择：选出最符合语境的选项，使句子语法正确且语义自然。","correctIndex":0}],"5":[{"type":"fill","sentence":"The policy reform, ___ long overdue, was finally implemented after years of debate among legislators.","subSkill":"open_cloze_grammar_word_selection","explanation":"此处需要一个让步连词引导插入成分 long overdue，表示尽管早该如此。though 在此作副词/连词，形成 though long overdue 的简略让步结构，是C1书面语中的正式用法。","instruction":"语篇填空：阅读下面的语篇片段，在每个空白处填入一个合适的语法词，使整篇语言连贯、语法正确。","acceptableAnswers":["though"]},{"type":"fill","sentence":"The author's (ambiguous) ___ use of symbolism throughout the novel invites multiple interpretations.","subSkill":"word_formation_affixation_and_conversion","explanation":"此处修饰名词 use，需要形容词。ambiguous 本身已是形容词，意为含糊的、模棱两可的，无需变形，直接用于修饰名词，体现作者有意为之的多义写法。","instruction":"构词变形：根据括号中的基础词，结合语境选择正确的派生形式填入空白处。","acceptableAnswers":["ambiguous"]},{"type":"fill","sentence":"She only realised how serious the situation was when she read the full report. (not)\nOnly ___ she ___ how serious the situation was.","subSkill":"key_word_transformation_paraphrase","explanation":"原句含 only when 结构，改写时将 only when she read the full report 置于句首，触发主句倒装：Only when she read the full report did she realise... 但此处两空分别为 when 和 realised，填入形成 Only when + 从句，主句倒装部分已给出。","instruction":"关键词句转换：用括号中的关键词改写句子，使新句意思与原句完全相同，每空填一个词。","acceptableAnswers":["when","realised"]},{"type":"fill","sentence":"People say that the new director has already transformed the company culture. (said)\nThe new director ___ ___ have already transformed the company culture.","subSkill":"key_word_transformation_paraphrase","explanation":"原句用 people say that 表示普遍说法，改写为被动结构 is said to have done，其中 to have done 表示动作发生在说话时间之前，体现完成时的语义。","instruction":"关键词句转换：用括号中的关键词改写句子，每空填一个词，使新句与原句意思一致。","acceptableAnswers":["is","said"]},{"type":"reorder","words":["Rarely","has","such","a","comprehensive","study","of","urban","poverty","been","conducted."],"subSkill":"integrated_grammar_accuracy_review","explanation":"Rarely 置于句首时，助动词与主语倒装，结构为 Rarely + has + 主语 + 过去分词。此句用现在完成时被动语态，表示如此全面的研究几乎从未被开展过。","instruction":"词序重排：将下列单词重新排列，组成一个语法正确、语义完整的句子。","correctSentence":"Rarely has such a comprehensive study of urban poverty been conducted."},{"type":"error","words":["The","findings","suggest","that","further","research","is","needed","before","any","conclusion","can","be","reached."],"subSkill":"error_correction_in_written_text","correction":"conclusions","errorIndex":10,"explanation":"在此语境中，研究人员尚未得出结论，any conclusions 指代研究中可能形成的多项结论，用复数更为准确和自然。虽然单数在某些语境可接受，但 reach conclusions 是学术写作中的标准搭配，通常用复数形式。","instruction":"书面纠错：下列句子中有一个词使用错误，找出并改正，注意C1级书面语法的精确性要求。"},{"type":"choice","options":["thereby","therefore","however","moreover"],"sentence":"The minister refused to comment on the allegations, ___ fuelling speculation about her involvement.","subSkill":"integrated_grammar_accuracy_review","explanation":"thereby 是正式书面语中的连接副词，意为由此、从而，后接动名词短语，表示前一行为导致的结果。therefore 后需接完整句子；however 和 moreover 表示转折或递进，与语境逻辑不符。","instruction":"语法综合选择：选出最符合C1书面语语境的选项，使句子语法和文体均正确。","correctIndex":0},{"type":"fill","sentence":"Had the government ___ more decisive action earlier, the economic crisis ___ have been avoided.","subSkill":"integrated_grammar_accuracy_review","explanation":"此句为虚拟语气第三类条件句（与过去事实相反）。条件从句省略 if，需倒装 Had + 主语 + 过去分词，故填 taken。主句用 might/could/would have done 表示对过去情况的虚拟推断，填 might 或 could 均可表示可能性。","instruction":"综合语法填空：阅读下面的句子，在空白处各填入一个合适的词，使两处填空在语法和语义上均正确。","acceptableAnswers":["taken","might"]}]},"mission":{"title":"The Policy Brief","scenario":"市政府正在考虑一项大规模城市绿化计划，计划在未来五年内将城市绿地面积扩大40%。你的任务是撰写简报的关键段落，说明该计划的必要性、潜在挑战及建议措施。每个句子都应体现C1级书面语法的准确运用。","scaffolds":[{"hint":"用虚拟条件句倒装（第三条件句），说明过去若采取了某项措施，现状会有所不同。","prefix":"Had the authorities","suffix":", the current shortage of urban green space might never have arisen.","example":"Had the authorities invested in green infrastructure a decade ago, the current shortage of urban green space might never have arisen.","grammarCheck":"key_word_transformation_paraphrase"},{"hint":"用强调否定倒装句（Under no circumstances + should + 主语 + 动词原形）明确指出某项做法绝对不应被允许。","prefix":"Under no circumstances should","suffix":", as doing so would undermine the long-term sustainability of the initiative.","example":"Under no circumstances should financial constraints be used as justification for reducing the scope of the project, as doing so would undermine the long-term sustainability of the initiative.","grammarCheck":"integrated_grammar_accuracy_review"},{"hint":"用 'Were it not for + 名词短语' 表示对现在情况的假设，说明某个因素的关键作用。","prefix":"Were it not for","suffix":", the implementation of this scheme would prove considerably more challenging.","example":"Were it not for the generous financial commitment from private stakeholders, the implementation of this scheme would prove considerably more challenging.","grammarCheck":"key_word_transformation_paraphrase"}],"description":"你是一名政策研究员，需要为市政府撰写一份正式的政策简报，就城市绿化方案的实施提出建议。请运用本单元所学的C1级书面语法结构，包括虚拟条件句倒装、强调否定倒装、构词变形及正式连接词语，使简报语言专业、准确、有说服力。","grammarType":"key_word_transformation_paraphrase"},"discover":{"tip":"本单元聚焦C1书面语法的三大核心技能：\n\n【1. 语篇填空（Open Cloze）】需要根据语境判断语法功能词，包括：介词短语（by virtue of, in possession of）、连接词（not least because, rather than）、代词与限定词。常见错误：混淆功能相近的介词（e.g. despite vs. although — despite 后接名词/动名词，although 后接从句）。\n\n【2. 构词变形（Word Formation）】需掌握前缀（un-, in-, mis-, over-）与后缀（-tion, -ity, -ment, -ous, -ise）的系统运用，以及词性转换规律。常见错误：①混淆名词与形容词后缀（responsible → responsibility NOT responsibleness）；②忘记双写辅音或改变词根拼写（begin → beginning）。\n\n【3. 关键词句转换（Key-Word Transformation）】要求在保持原句意义不变的前提下，用给定关键词重构句子，常涉及：条件句倒装（If she had... → Had she...）、强调否定倒装（Not until/No sooner）、双重否定（by no means + 负面形容词）、固定搭配替换。常见错误：改变了原句的语态或情态含义。","story":{"text":"When Clara's elderly aunt passed away, she left behind considerably more than anyone had anticipated. The solicitor informed Clara that, had she not contested the original will, the entire estate would have been divided among distant relatives. It was only by virtue of a recently discovered codicil that Clara found herself in possession of a sprawling country house. Despite having lived frugally for most of her adult life, Clara was by no means unprepared for the responsibilities that came with such wealth. She immediately set about renovating the property, not least because the roof was in dire need of repair. What struck her neighbours most was the extent to which she went out of her way to preserve the original features of the house. It was widely acknowledged that, were it not for her meticulous attention to detail, the historic building might well have fallen into disrepair. Clara later remarked to a journalist that she regarded the inheritance not as a windfall but rather as a custodial duty. No sooner had the renovation been completed than she opened the grounds to the public, free of charge. Her actions bore testimony to the belief that privilege, however unexpectedly bestowed, carries with it an obligation to serve the wider community.","title":"The Unexpected Inheritance","highlights":["had she not contested","were it not for","by no means unprepared","not least because","no sooner had...than","by virtue of","to the extent to which","bears testimony to"]},"questions":[{"options":["A second conditional with 'if' omitted","A third conditional with inversion replacing 'if'","A past perfect used to express regret","A subjunctive used in a nominal clause"],"question":"In the sentence 'had she not contested the original will, the estate would have been divided', what grammatical structure is being used?","explanation":"这是一个省略了 if 的第三条件句（虚拟语气过去完成时）。当 if 被省略时，助动词 had/were/should 提前到主语之前，构成倒装结构。'had she not contested' 等同于 'if she had not contested'，表示与过去事实相反的假设。","correctIndex":1},{"options":["She was completely unprepared","She was somewhat unprepared","She was actually quite well prepared","She was barely prepared at all"],"question":"The phrase 'by no means unprepared' is best interpreted as meaning:","explanation":"'by no means' 是强调否定的副词短语，意为'绝不、一点也不'。'unprepared' 是否定词，'by no means unprepared' 是双重否定，产生强烈肯定效果，意思是'完全有准备的'。这是C1级书面语中常见的修辞手法。","correctIndex":2},{"options":["She opened the grounds before the renovation was completed.","The renovation was barely finished when she immediately opened the grounds.","She waited a long time after the renovation before opening the grounds.","She completed the renovation because she wanted to open the grounds."],"question":"Which sentence most accurately paraphrases 'No sooner had the renovation been completed than she opened the grounds'?","explanation":"'No sooner...than' 是一个倒装结构，强调两个动作几乎同时发生，第一个动作刚一完成，第二个动作立即跟随。主句用过去完成时倒装（had + 主语 + 过去分词），从句用一般过去时。意思等同于 'As soon as the renovation had been completed, she opened the grounds'。","correctIndex":1}]}}}};
